  @override
  String get benzoMilestone60Description =>
      'في دراسة استمرت 8 أسابيع على كبار السن الذين استخدموا منومات البنزوديازيبين لفترات طويلة، أظهر من أكملوا خفض الجرعة والتوقف تحسنًا في الذاكرة الفورية والانتباه واللغة وثبات الجسم. هذا تعافٍ نهاري قابل للقياس.';

  @override
  String get benzoMilestone90Title => 'ثلاثة أشهر: تفكير أسرع وخمول أقل';

  @override
  String get benzoMilestone90Description =>
      'بعد 12 أسبوعًا من الفطام، أنجز مستخدمو البنزوديازيبينات لفترات طويلة الذين نجحوا في التوقف مهامًا معرفية تعتمد على السرعة بشكل أسرع، وأبلغوا عن خمول ذهني وجسدي أقل من الأشخاص الذين استمروا في تناول البنزوديازيبينات. هذا تعافٍ نهاري قابل للقياس.';

  @override
  String get benzoMilestone180Title => 'يبدأ التفكير والذاكرة في التعافي';

  @override
  String get benzoMilestone180Description =>
      'وبعد ستة أشهر، تظهر الذاكرة والانتباه تحسنًا ملحوظًا. تشير الأبحاث إلى التعافي في العديد من مهارات التفكير، مع استمرار المكاسب بعد ستة أشهر.';

  @override
  String get benzoMilestone365Title => 'سنة واحدة من الشفاء';

  @override
  String get benzoMilestone365Description =>
      'وبعد عام واحد، أصبحت التحسينات الكبيرة في الصحة العقلية والجسدية واضحة. أبلغ الكثيرون عن انخفاض القلق وتحسين نوعية النوم وتحسين الصحة العامة مقارنة بتناول البنزوديازيبينات على المدى الطويل. يستمر شفاء الدماغ.';

  @override
  String get benzoMilestone540Title => 'استمرار تعافي الدماغ';

  @override
  String get benzoMilestone540Description =>
      'في عمر 18 شهرًا، تستمر الذاكرة والانتباه والتفكير الواضح في التحسن. لقد استغرق نظام GABA المهدئ في الدماغ أكثر من عام حتى يستقر، بينما يستمر الدماغ في بناء أنماط أكثر صحة.';

  @override
  String get benzoMilestone730Title => 'سنتان: تقدم كبير';

  @override
  String get benzoMilestone730Description =>
      'عامان يمثلان تعافيًا كبيرًا. لدى معظم الناس تفكير أوضح بكثير، ومشاعر أكثر استقرارًا، ونوعية حياة أفضل بكثير مما كانت عليه أثناء الاستخدام طويل الأمد للبنزوديازيبينات.';

  @override
  String get benzoMilestone1095Title => 'ثلاث سنوات: التعافي طويل الأمد';

  @override
  String get benzoMilestone1095Description =>
      'بعد ثلاث سنوات، تكون فترة الانسحاب الطويلة قد أصبحت بعيدة بالنسبة إلى معظم الناس. لقد أتيح للنوم والمزاج والذاكرة والانتباه سنوات للتعافي، وعادةً ما تكون الحياة اليومية أفضل بكثير مما كانت عليه أثناء الاستخدام طويل الأمد.';

  @override
  String get benzoMilestone1460Title => 'أربع سنوات: تقدم راسخ';

  @override
  String get benzoMilestone1460Description =>
      'أربع سنوات بعيدًا عن البنزوديازيبينات تمثل مسيرة تعافٍ طويلة بُنيت يومًا بعد يوم. تختلف جداول التعافي من شخص لآخر، لذا تحتفي هذه الذكرى بالاستقرار والعادات والمرونة التي تعززت لديك من دون الادعاء بوجود خط نهاية واحد للجميع.';

  @override
  String get benzoMilestone1825Title => 'خمس سنوات: أساس متين';

  @override
  String get benzoMilestone1825Description =>
      'خمس سنوات إنجاز كبير على المدى الطويل. لا يسير التعافي وفق جدول واحد، لكن خمس سنوات من التغيير المستمر تعني آلاف الأيام من الممارسة والدعم والحياة التي بُنيت بعيدًا عن البنزوديازيبينات.';

