  @override
  String get nitrousOxideMilestone1Description =>
      'يغادر الغاز جسمك خلال دقائق، لكن الشفاء يستغرق وقتًا أطول. تستقر الدوخة، ويخف الصداع، ويبدأ دماغك في التكيف دون الحاجة إلى اختصار الدوبامين. يبدأ تعافي B12 الآن.';

  @override
