  @override
  String get nitrousOxideMilestone3Description =>
      'إليك أخبار جيدة: أكسيد النيتروز لا يسبب الانسحاب الجسدي. إن الحوافز التي تشعر بها هي أمور نفسية - عادة وارتباط، وليست مطالبة جسدك بمادة ما. وهذا يجعلهم قابلين للإدارة.';

  @override
  String get nitrousOxideMilestone7Title => 'أسبوع واحد - ارتفاع B12';

  @override
  String get nitrousOxideMilestone7Description =>
      'أسبوع واحد دون تدمير B12 جديد. إذا كنت قد بدأت في تناول المكملات الغذائية، فإن مستوياتك في الارتفاع بالفعل. ترتبط الطاقة والمزاج والتركيز جميعها بفيتامين B12، ويجب أن تبدأ في الشعور بتحسنها.';

  @override
  String get nitrousOxideMilestone14Title => 'اسبوعين - شفاء الأعصاب';

  @override
  String get nitrousOxideMilestone14Description =>
      'B12 ضروري للطبقة الواقية على أليافك العصبية. وبعد مرور أسبوعين، تجري عملية الإصلاح هذه بشكل نشط. من المفترض أن يخف أي وخز أو تنميل لديك – حيث يقوم جهازك العصبي بإصلاح نفسه مرة أخرى.';

  @override
  String get nitrousOxideMilestone30Title => 'شهر واحد - عودة الطاقة';

  @override
  String get nitrousOxideMilestone30Description =>
      'يلعب فيتامين ب12 دورًا رئيسيًا في إنتاج خلايا الدم الحمراء، مما يعني توصيل الأكسجين إلى كل خلية في الجسم. شهر واحد من التعافي والمكملات يعني طاقة أفضل وتفكيرًا أكثر وضوحًا ومزاجًا أكثر استقرارًا.';

  @override
  String get nitrousOxideMilestone90Title => 'ثلاثة أشهر - التعافي العصبي';

  @override
  String get nitrousOxideMilestone90Description =>
      'ثلاثة أشهر دون تدمير فيتامين B12 تعني ثلاثة أشهر من إصلاح الأعصاب. يتمتع الجهاز العصبي بالمرونة، حيث يرى معظم الأشخاص الذين بدأوا العلاج على الفور تعافيًا ملحوظًا في الوخز والضعف وضباب الدماغ عند هذه النقطة.';

  @override
  String get nitrousOxideMilestone365Title => 'سنة واحدة - حماية طويلة الأمد';

  @override
  String get nitrousOxideMilestone365Description =>
      'سنة كاملة خالية من أكسيد النيتروز. يتم استعادة مخزون B12 الخاص بك، ويحتاج جهازك العصبي إلى عام للشفاء، ويتم حل خطر القلب والأوعية الدموية الناجم عن ارتفاع الهوموسيستين. جسمك يعمل على الكيمياء الخاصة به مرة أخرى.';

