  @override
  String get nicotinePouchesMilestone3Title => 'ذروة الانسحاب';

  @override
  String get nicotinePouchesMilestone3Description =>
      'يبلغ انسحاب النيكوتين ذروته عادةً قرب اليوم الثالث، ثم يخف تدريجيًا خلال الأسابيع 3–4 التالية. لقد وصلت إلى قمة التل — ومن هنا يتجه المسار العام إلى الانخفاض.';

  @override
  String get nicotinePouchesReferenceDay1 =>
      'اليوم الأول: يبدأ انسحاب النيكوتين\n\nالمصدر: McLaughlin وDani وDe Biasi — Nicotine Withdrawal\n\nتشير مراجعة للانسحاب بعد الاستخدام المزمن للمنتجات المحتوية على النيكوتين إلى أن متلازمة الانسحاب يمكن أن تبدأ خلال 4–24 ساعة من التوقف. لذلك فإن أول يوم بلا أكياس يمثل علامة فسيولوجية حقيقية.\n\nما التالي\nتبلغ الأعراض ذروتها عادةً قرب اليوم الثالث ثم تخف خلال الأسابيع 3–4 التالية. وتختلف شدة الانسحاب باختلاف طريقة استهلاك النيكوتين، لذلك قد تختلف التجربة من شخص لآخر.';

  @override
  String get nicotinePouchesReferenceDay3 =>
      'اليوم الثالث: ذروة انسحاب النيكوتين\n\nالمصدر: McLaughlin وDani وDe Biasi — Nicotine Withdrawal\n\nتضع المراجعة الذروة المعتادة لانسحاب النيكوتين قرب اليوم الثالث بعد إيقاف الاستخدام المزمن للنيكوتين.\n\nالمسار من هنا\nبعد الذروة، تخف الأعراض عادةً خلال الأسابيع 3–4 التالية. كما تشير المراجعة إلى أن شدة الانسحاب تختلف باختلاف طريقة استهلاك النيكوتين، لذلك تختلف الشدة الدقيقة من شخص لآخر.\n\nاليوم الثالث علامة تستحق الاحتفال: لقد وصلت إلى قمة منحنى الانسحاب المبكر المعتاد.';

  @override
  String get nicotinePouchesMilestone7Title => 'أسبوع واحد: أعراض الانسحاب تخف';

  @override
  String get nicotinePouchesMilestone7Description =>
      'أسبوع كامل بلا أكياس نيكوتين يضعك بعد الذروة المعتادة لأعراض انسحاب النيكوتين في اليوم الثالث. عادةً ما تتراجع الأعراض خلال الأسابيع 3–4 التالية — وأنت بالفعل على المنحدر.';

  @override
  String get nicotinePouchesMilestone14Title =>
      'أسبوعان: أعراض الانسحاب تواصل التراجع';

  @override
  String get nicotinePouchesMilestone14Description =>
      'أسبوعان بلا أكياس نيكوتين يضعانك بوضوح داخل فترة التراجع الممتدة 3–4 أسابيع التي تلي عادةً ذروة اليوم الثالث. المنحنى ما زال ينخفض — تعافٍ حقيقي قيد التقدم.';

  @override
  String get nicotinePouchesReferenceDay7 =>
      'أسبوع واحد: أعراض الانسحاب تخف\n\nالمصدر: McLaughlin, Dani & De Biasi — Nicotine Withdrawal\n\nتذكر المراجعة أن الانسحاب بعد الاستخدام المزمن للمنتجات المحتوية على النيكوتين يبدأ خلال 4–24 ساعة من التوقف، ويبلغ ذروته قرابة اليوم الثالث، ثم تتراجع الأعراض خلال الأسابيع 3–4 التالية.\n\nإنجاز حقيقي بعد أسبوع\nعند مرور أسبوع تكون قد تجاوزت الذروة المعتادة بعدة أيام ودخلت مرحلة التراجع. وتشير المراجعة أيضًا إلى أن شدة الانسحاب تختلف باختلاف طريقة تناول النيكوتين، لذلك تختلف شدة الأعراض بين الأشخاص.\n\nأسبوع كامل بلا أكياس نيكوتين يعني أن أشد جزء من منحنى الانسحاب المبكر المعتاد أصبح خلفك.';

  @override
  String get nicotinePouchesReferenceDay14 =>
      'أسبوعان: أعراض الانسحاب تواصل التراجع\n\nالمصدر: McLaughlin, Dani & De Biasi — Nicotine Withdrawal\n\nتضع المراجعة الذروة المعتادة لانسحاب النيكوتين قرابة اليوم الثالث وتذكر أن الأعراض تتراجع خلال الأسابيع 3–4 التالية.\n\nفي قلب مرحلة التراجع\nبعد أسبوعين تكون قد دخلت بوضوح في نافذة التراجع التي تلي الذروة. وتتناول المراجعة الاستخدام المزمن للمنتجات المحتوية على النيكوتين وتذكر أن شدة الانسحاب تختلف حسب طريقة تناول النيكوتين.\n\nأسبوعان بلا أكياس نيكوتين محطة واضحة على المنحنى الهابط: أعراض الانسحاب المعتادة تواصل التراجع.';

  @override
  String get nicotinePouchesMilestone730Title => 'عامان: قوة بلا أكياس';

  @override
  String get nicotinePouchesMilestone730Description =>
      'عامان كاملان بلا أكياس نيكوتين. لم تثبت الأبحاث وجود عتبة تعافٍ خاصة عند العامين، لذلك يحتفل هذا الإنجاز بعامين من دون التعرض المتكرر لنيكوتين الأكياس وبالتغيير المستمر.';

  @override
  String get nicotinePouchesReferenceDay730 =>
      'عامان: قوة بلا أكياس\n\nالمصدر: Rungraungrayabkul وزملاؤه (2024)، مراجعة منهجية عن أكياس النيكوتين وصحة الفم\n\nوجدت المراجعة ثلاث دراسات بشرية فقط شملت 190 مشاركًا، وصُنفت جميعها عالية الخطورة من حيث التحيز. ولم تثبت وجود عتبة تعافٍ محددة بعد عامين من التوقف.\n\nومع ذلك، يظل عامان بلا أكياس إنجازًا كبيرًا لتغيير مستمر. يحتفل هذا النص بالإنجاز من دون اختراع جدول زمني طبي.';

  @override
  String get nicotinePouchesMilestone1095Title => 'ثلاثة أعوام: الحرية مستمرة';

  @override
  String get nicotinePouchesMilestone1095Description =>
      'ثلاثة أعوام بلا أكياس نيكوتين انتصار ثابت. ما زالت الآثار طويلة المدى قيد الدراسة، لذا فالخلاصة الصادقة بسيطة: ثلاثة أعوام من التحرر المستمر من نيكوتين الأكياس.';

  @override
  String get nicotinePouchesReferenceDay1095 =>
      'ثلاثة أعوام: الحرية مستمرة\n\nالمصدر: مراكز مكافحة الأمراض والوقاية منها — أكياس النيكوتين\n\nتذكر المراكز أن فهم الآثار الصحية القصيرة والطويلة المدى لأكياس النيكوتين يحتاج إلى مزيد من البحث، ولا تشير إلى تغير طبي خاص بعد ثلاثة أعوام من التوقف.\n\nتستحق ثلاثة أعوام بلا أكياس الاحتفال كما هي: ثلاثة أعوام من التحرر المستمر من نيكوتين الأكياس.';

  @override
  String get nicotinePouchesMilestone1460Title => 'أربعة أعوام: تغيير راسخ';

  @override
  String get nicotinePouchesMilestone1460Description =>
      'أربعة أعوام بلا أكياس نيكوتين دليل على الاستمرار. لا يوجد تحول طبي مثبت يحدث تحديدًا عند أربعة أعوام، لكن هناك إنجاز حقيقي جدًا: أربعة أعوام من دون العودة إلى عادة الأكياس.';

  @override
  String get nicotinePouchesReferenceDay1460 =>
      'أربعة أعوام: تغيير راسخ\n\nالمصدر: Rungraungrayabkul وزملاؤه (2024)، مراجعة منهجية عن أكياس النيكوتين وصحة الفم\n\nتخلص المراجعة إلى أن الأدلة على الآثار القصيرة والطويلة المدى في صحة الفم ما زالت محدودة وأن مزيدًا من البحث ضروري. ولا تدعم حدث تعافٍ عامًا يحدث تحديدًا عند أربعة أعوام.\n\nأربعة أعوام بلا أكياس علامة كبيرة على تغيير مستمر، من دون الحاجة إلى ادعاء طبي غير مثبت.';

  @override
  String get nicotinePouchesMilestone1825Title => 'خمسة أعوام: انتصار كبير';

  @override
  String get nicotinePouchesMilestone1825Description =>
      'خمسة أعوام بلا أكياس نيكوتين إنجاز هائل. ما زالت الأبحاث طويلة المدى تتطور، لذلك لا يقدم هذا الإنجاز وعودًا صحية مختلقة بل يحتفل بخمسة أعوام من التغيير المستمر.';

  @override
  String get nicotinePouchesReferenceDay1825 =>
      'خمسة أعوام: انتصار كبير\n\nالمصدر: مراكز مكافحة الأمراض والوقاية منها — أكياس النيكوتين\n\nتوضح المراكز أن أكياس النيكوتين حديثة نسبيًا وأن آثارها الصحية طويلة المدى ما زالت قيد الدراسة. ولا تثبت الأدلة الحالية حدث تعافٍ محدد عند خمسة أعوام.\n\nخمسة أعوام بلا أكياس إنجاز ضخم بحد ذاته: خمسة أعوام من التغيير المستمر.';

