  @override
  String get pornographyMilestone30Title => 'شهر من السيطرة';

  @override
  String get pornographyMilestone30Description =>
      'الشهر هو اختبار مفيد للسيطرة. في دراسة أجريت على 14581 شخصًا، ارتبطت مشاكل الوظيفة الجنسية بقوة أكبر مع الاستخدام الإشكالي مقارنة بتكرار المشاهدة البسيط، لذا فإن استعادة السيطرة هي الهدف الأكثر مستندة إلى الأدلة.';

  @override
  String get pornographyMilestone90Title => 'التغيير يمكن أن يصمد';

  @override
  String get pornographyMilestone90Description =>
      'وجدت تجربة ACT العشوائية لاستخدام المواد الإباحية الإشكالية تخفيضات كبيرة في المشاهدة بعد 12 جلسة، مع استمرار وجود تخفيضات كبيرة في متابعة لمدة 3 أشهر. التغيير الدائم أمر واقعي، خاصة عندما تقوم ببناء مهارات منظمة بدلاً من الاعتماد فقط على قوة الإرادة.';

  @override
  String get pornographyMilestone180Title => 'استقرار لمدة ستة أشهر';

  @override
  String get pornographyMilestone180Description =>
