  @override
  String get pornographyMilestone730Title => 'عامان: سيطرة مستقرة';

  @override
  String get pornographyMilestone730Description =>
      'الحفاظ على التغيير لمدة عامين إنجاز سلوكي مهم. تركز الأدلة حول اضطراب السلوك الجنسي القهري والاستخدام الإشكالي للمواد الإباحية على السيطرة والضيق والأداء والسياق، لا على إعادة ضبط دماغية عامة بعد عامين. حافظ على العادات التي تجعل الخيارات السليمة أسهل.';

  @override
