  @override
  String get pornographyMilestone1095Description =>
      'تُظهر ثلاثة أعوام أن التغيير صمد أمام حالات مزاجية وروتين وأحداث حياتية مختلفة. لا توجد نقطة نهاية بيولوجية بعد ثلاثة أعوام تدعمها الأدلة؛ فالسيطرة المستمرة وتحسن الأداء نتيجتان مهمتان بالفعل.';

