  @override
  String get pornographyMilestone1825Description =>
      'خمس سنوات هي صيانة طويلة الأمد. يتم تعريف CSBD سريريًا على أنه فقدان السيطرة المستمر مع الضيق أو الضعف، لذا فإن الحفاظ على السيطرة والأداء الجيد على مدار السنوات يعد نتيجة ذات معنى في حد ذاته.';

  @override
  String get customMilestone1Title => 'اكتملت أول 24 ساعة';

  @override
  String get customMilestone1Description =>
      'أكملت يومًا كاملًا دون العادة التي اخترت التوقف عنها. في الأيام الأولى بعد التوقف عن بعض المواد، قد يؤدي الانسحاب إلى اضطراب النوم، وقد تستمر تغيّرات النوم خلال التعافي. تتبّع نومك يمكن أن يجعل هذه التغيّرات أسهل ملاحظة.';

  @override
  String get customMilestone3Title => 'ذروة أعراض الانسحاب';

  @override
  String get customMilestone3Description =>
      'أنت تواجه العاصفة وجهاً لوجه! عادةً ما تبلغ أعراض الانسحاب الجسدي ذروتها في اليوم الثالث تقريبًا بالنسبة للعديد من المواد، بما في ذلك القلق وتقلب المزاج وعدم الراحة الجسدية. هذا يعني أنك تجاوزت الجزء الأصعب.';

  @override
  String get customMilestone7Title => 'انتهاء مرحلة الانسحاب الحاد';

  @override
  String get customMilestone7Description =>
      'الأسوأ خلفك! وبعد أسبوع واحد، تبدأ أعراض الانسحاب الحادة في التراجع بالنسبة لمعظم المواد. يتكيف جسمك مع وضعه الطبيعي الجديد ويبدأ في الاستقرار.';

  @override
  String get customMilestone14Title => 'استقرار التعافي المبكر';

  @override
  String get customMilestone14Description =>
      'ذهنك يصفو! غالبًا ما يجلب أسبوعان من الامتناع وضوحًا ذهنيًا أفضل ورغبة أقل في التعاطي، بينما يبدأ الدماغ في التكيف مع العمل من دون المواد المسببة للإدمان.';

  @override
  String get customMilestone30Title => 'معلم شهر واحد';

  @override
  String get customMilestone30Description =>
      'انتصار كبير! تمثل ثلاثون يومًا من الرصانة تقدمًا كبيرًا. يجد الكثير من الناس أن أنماط النوم والمزاج ومستويات الطاقة تستمر في التحسن خلال هذه الفترة.';

  @override
  String get customMilestone90Title => 'معلم التعافي لمدة ثلاثة أشهر';

  @override
  String get customMilestone90Description =>
      'التزامك يؤتي ثماره! تمثل ثلاثة أشهر من التعافي إنجازًا كبيرًا. عادةً ما تبدأ أعراض الانسحاب بعد الحادة في التلاشي، ويشعر العديد من الأشخاص بأنهم أصبحوا يشبهون أنفسهم مرة أخرى.';

  @override
  String get customMilestone180Title => 'إنجاز التعافي لمدة ستة أشهر';

  @override
  String get customMilestone180Description =>
      'أنت تقوم ببناء تغيير دائم! غالبًا ما تؤدي ستة أشهر من الرصانة إلى تحسينات مستمرة في الصحة البدنية والاستقرار العاطفي ونوعية الحياة بشكل عام مع استمرار جسمك في الشفاء.';

  @override
  String get customMilestone365Title => 'سنة واحدة من التعافي';

  @override
  String get customMilestone365Description =>
      'إنجاز رائع! تمثل سنة كاملة من الامتناع علامة فارقة مهمة في الحياة. يلاحظ كثير من الناس بحلول هذه المرحلة تحسنًا واضحًا في الصحة البدنية والعلاقات والرفاه العام.';

  @override
  String get customMilestone730Title => 'سنتان من التعافي المستدام';

  @override
  String get customMilestone730Description =>
      'لقد بنيت حياة جديدة! يظهر عامان من التعافي مرونة والتزامًا ملحوظين. وغالبًا ما يرتبط التعافي طويل الأمد بتغييرات إيجابية عميقة في مجالات الحياة المختلفة وانخفاض خطر الانتكاس.';

  @override
  String get customMilestone1095Title => 'ثلاث سنوات: جذور راسخة';

  @override
  String get customMilestone1095Description =>
      'ثلاث سنوات من التعافي تمثل تقدماً مستمراً. لقد ترسخت العادات والعلاقات ومهارات التكيف التي مارستها على مدى سنوات. واصل البناء على ما يفيدك.';

  @override
  String get customMilestone1460Title => 'أربع سنوات: تغيير راسخ';

  @override
  String get customMilestone1460Description =>
      'أربع سنوات تجعل التغيير الدائم ملموساً. أصبحت الخيارات والدعم اللذان أوصلاك إلى هنا جزءاً من حياتك اليومية. حافظ عليهما وواصل التقدم.';

  @override
  String get customMilestone1825Title => 'خمس سنوات: نصف عقد';

  @override
  String get customMilestone1825Description =>
      'خمس سنوات تعني نصف عقد من التقدم المستمر. احتفل بالحياة والمهارات وشبكة الدعم التي بنيتها، وواصل الاستثمار في العادات التي تساعدك على الازدهار.';

  @override
  String get customReferenceDay1095 =>
      'ثلاث سنوات من التعافي: جذور راسخة\n\nالمصدر: NIDA، المخدرات والدماغ والسلوك: علم الإدمان\n\nتصف NIDA اضطرابات استخدام المواد بأنها قابلة للعلاج، والتعافي بأنه التوقف عن تعاطي المخدرات والعودة إلى حياة منتجة. ولا تحدد موعداً بيولوجياً عاماً بعد ثلاث سنوات ينطبق على جميع المواد.\n\nثلاث سنوات إنجاز راسخ بحد ذاته. لقد كان أمام العادات والدعم والخيارات التي أوصلتك إلى هنا سنوات لتترسخ.';

  @override
  String get customReferenceDay1460 =>
      'أربع سنوات من التعافي: تغيير راسخ\n\nالمصدر: NIDA، المخدرات والدماغ والسلوك: علم الإدمان\n\nتقدم NIDA الإدمان بوصفه حالة قابلة للعلاج ويمكن إدارتها بنجاح. ولا تحدد نقطة صحية نهائية عامة بعد أربع سنوات لكل مادة أو لكل شخص.\n\nأربع سنوات تجعل الاستمرارية واضحة. واصل حماية العادات والعلاقات والدعم التي تجعل التعافي قابلاً للاستمرار.';

  @override
  String get customReferenceDay1825 =>
      'خمس سنوات من التعافي: نصف عقد\n\nالمصدر: NIDA، المخدرات والدماغ والسلوك: علم الإدمان\n\nتدعم NIDA العلاج والتعافي القائمين على الأدلة، لكنها لا تدعي أن كل شخص يصل إلى الحالة البيولوجية نفسها بعد خمس سنوات.\n\nخمس سنوات نصف عقد من التقدم المستمر. احتفل بما بنيته وواصل الاستثمار في ما يفيدك.';

  @override
  String get addictionSsri => 'مثبطات استرداد السيروتونين الانتقائية';

  @override
  String get ssriPageTitle => 'استرداد SSRI';

  @override
  String get ssriHeaderStarted => 'رحلة التعافي الخاصة بك';

  @override
  String get ssriHeaderNotStarted =>
      'فوائد التقليص التدريجي لمثبطات استرداد السيروتونين الانتقائية';

  @override
  String get ssriSubtitleStarted => 'تتبع تقدمك واحتفل بكل إنجاز';

  @override
  String get ssriSubtitleNotStarted => 'انظر ماذا يحدث عند التناقص التدريجي';

  @override
  String get ssriMilestone3Title => 'اليوم 3: ذروة متلازمة FINISH';

  @override
  String get ssriMilestone3Description =>
      'غالبًا ما تبلغ أعراض الانسحاب ذروتها في الأيام 2-4 تقريبًا. تغير مثبطات استرداد السيروتونين الانتقائية كيفية إعادة تدوير السيروتونين، لذلك يحتاج الدماغ إلى وقت للتكيف بعد التوقف. توقع ظهور أعراض تشبه أعراض الأنفلونزا، والدوخة، والأرق، والغثيان، و\"صعقات الدماغ\". يميل الباروكستين إلى التسبب في انسحاب أقوى. يستمر فلوكستين لفترة أطول في الجسم وعادة ما يكون أكثر اعتدالًا.';

  @override
  String get ssriMilestone7Title => 'أسبوع: بدء انحسار المرحلة الحادة';

  @override
  String get ssriMilestone7Description =>
      'بدأت الأعراض الجسدية الأكثر شدة في التراجع. يقوم دماغك بتعديل إشارات السيروتونين الخاصة به ليعمل بدون الدواء. بدأ النوم والشهية في الاستقرار.';

  @override
  String get ssriMilestone14Title => 'أسبوعان: تراجع الأعراض الجسدية';

  @override
  String get ssriMilestone14Description =>
      'تم تقليل أو حل معظم أعراض التوقف الجسدي الحادة بشكل ملحوظ. تتلاشى صعقات الدماغ والغثيان والدوخة. قد تستمر الحساسية العاطفية في الارتفاع مع استمرار عقلك في إعادة توازن أنظمة السيروتونين الخاصة به.';

  @override
  String get ssriMilestone30Title => 'شهر واحد: استقرار المزاج والطاقة';

  @override
  String get ssriMilestone30Description =>
      'شهر واحد يمثل معلما هاما. تتحسن جودة النوم، وتستقر مستويات الطاقة، ويلاحظ العديد من الأشخاص أن مزاجهم بدأ في العثور على توازن جديد. يستعيد الدماغ بنشاط تنظيم السيروتونين الطبيعي.';

  @override
  String get ssriMilestone90Title => '3 أشهر: منعطف أعراض الانسحاب';

  @override
  String get ssriMilestone90Description =>
      'في تجربة ANTLER كان الفرق في أعراض الانسحاب بعد إيقاف مضادات الاكتئاب طويلة المدى أكبر ما يكون عند 12 أسبوعًا، ثم أصبح أصغر في المتابعات اللاحقة. لذلك تمثل ثلاثة أشهر نقطة تحول حقيقية في مسار الانسحاب المقاس.';

  @override
  String get ssriMilestone180Title => 'ستة أشهر: 65٪ ظلوا بحالة جيدة';

  @override
  String get ssriMilestone180Description =>
      'في متابعة استمرت ستة أشهر لأشخاص في حالة هدوء بعد إيقاف مضادات الاكتئاب، ظل 54 من أصل 83 مشاركًا لديهم بيانات متابعة — أي 65٪ — بحالة جيدة. ستة أشهر محطة ملموسة للاستقرار طويل الأمد.';

  @override
  String get ssriMilestone365Title => 'عام واحد: محطة ضخمة';

  @override
  String get ssriMilestone365Description =>
      'عام كامل من دون الدواء محطة ضخمة. في ANTLER، مرّ كثير من مستخدمي مضادات الاكتئاب طويلة الأمد الذين أوقفوها بـ52 أسبوعًا من دون انتكاس، رغم أن الانتكاس كان أكثر شيوعًا بعد الإيقاف مقارنةً بالعلاج الاستمراري. إذا كنت بخير بعد عام، فهذا تقدّم حقيقي يستحق الاحتفال.';

  @override
  String get settingsShowSsriTracking => 'إظهار تتبع SSRI';

  @override
  String get settingsNotifySsri => 'إخطار SSRI بالتقدم في الإقلاع عن التدخين';

  @override
  String get addictionSnri => 'SNRIs';

  @override
  String get snriPageTitle => 'استرداد SNRI';

  @override
  String get snriHeaderStarted => 'رحلة التعافي الخاصة بك';

  @override
  String get snriHeaderNotStarted => 'فوائد تقليص SNRIs';

  @override
  String get snriSubtitleStarted => 'تتبع تقدمك واحتفل بكل إنجاز';

  @override
  String get snriSubtitleNotStarted => 'انظر ماذا يحدث عند التناقص التدريجي';

  @override
  String get snriMilestone3Title => 'اليوم 3: ذروة أعراض التوقف';

  @override
  String get snriMilestone3Description =>
      'ترتبط مثبطات استرداد السيروتونين والنورإبينفرين (SNRIs) — وخاصة فينلافاكسين (إيفكسور) — ببعض من أشد متلازمات التوقف عن مضادات الاكتئاب. ويعني نصف عمر فينلافاكسين القصير جدًا (5 ساعات) أن الأعراض قد تكون أشد من معظم مثبطات استرداد السيروتونين الانتقائية (SSRIs). وتؤثر أعراض FINISH (أعراض شبيهة بالإنفلونزا، والأرق، والغثيان، وعدم التوازن، والاضطرابات الحسية، وفرط الاستثارة) في نظامي السيروتونين والنورإبينفرين معًا.';

  @override
  String get snriMilestone7Title => 'أسبوع: تكيف نظامين عصبيين';

  @override
  String get snriMilestone7Description =>
      'تؤثر SNRIs على إعادة امتصاص السيروتونين والنورإبينفرين. يتم ضبط كلا النظامين في وقت واحد. تبدأ الأعراض الجسدية الأكثر شدة في التراجع، ولكن الآلية المزدوجة تعني أن التكيف يمكن أن يكون أكثر تعقيدًا من مثبطات استرداد السيروتونين الانتقائية وحدها.';

  @override
  String get snriMilestone14Title => 'أسبوعين: تلاشي الأعراض الجسدية';

  @override
  String get snriMilestone14Description =>
      'لقد انخفضت بشكل ملحوظ معظم أعراض التوقف الجسدي الحادة. تتلاشى صعقات الدماغ والغثيان والدوخة. ربما لا تزال إعادة ضبط نظام النورإبينفرين تسبب بعض القلق أو تقلبات ضغط الدم، وعادةً ما تختفي هذه التقلبات خلال الأسابيع القادمة.';

  @override
  String get snriMilestone30Title => 'شهر واحد: استقرار نظام النوربينفرين';

  @override
  String get snriMilestone30Description =>
      'شهر واحد يمثل معلما هاما. يقوم كل من نظامي السيروتونين والنورإبينفرين بإعادة التوازن بشكل فعال. تستقر جودة النوم ومستويات الطاقة. يلاحظ العديد من الأشخاص تحسنًا في النطاق العاطفي حيث يبدأ تأثير الدواء على التدهور العاطفي في التلاشي.';

  @override
  String get snriMilestone90Title => '3 أشهر: تجاوز فترة الانسحاب';

  @override
  String get snriMilestone90Description =>
      'تبدأ أعراض انسحاب SNRIs عادةً خلال بضعة أيام وتستمر بضعة أسابيع. عند اليوم 90 تكون فترة الأعراض المعتادة قد أصبحت خلفك بوضوح — علامة تعافٍ ملموسة.';

  @override
  String get snriMilestone180Title => 'ستة أشهر: التعافي العصبي';

  @override
  String get snriMilestone180Description =>
      'ستة أشهر تسمح بتعديل جوهري لكل من أنظمة السيروتونين والنورإبينفرين. إن محور HPA – الذي تؤثر عليه SNRIs من خلال النورإبينفرين – يعود إلى طبيعته. أبلغ العديد من الأشخاص عن تحسن ملحوظ في القدرة على مواجهة الضغوطات اليومية في هذه المرحلة.';

  @override
  String get snriMilestone365Title => 'سنة واحدة: تم تحقيق التعافي';

  @override
  String get snriMilestone365Description =>
      'يمثل عام واحد دورة كاملة من التعافي المزدوج من السيروتونين والنورإبينفرين. تظهر الأبحاث باستمرار أن الأشخاص الذين توقفوا عن استخدام SNRIs بنجاح تحت إشراف طبي ومع دعم نفسي، حافظوا على نتائج جيدة بعد عام واحد.';

  @override
  String get snriMilestone730Title => 'عامان: ثبات مستمر';

  @override
  String get snriMilestone730Description =>
      'مرّ عامان منذ إكمال خفض جرعة SNRI تدريجيًا، وهذا إنجاز يستحق الاحتفال. تختلف تجارب الانسحاب، لذا تمثل هذه الذكرى تقدمًا مستمرًا لا موعدًا بيولوجيًا موحدًا للتعافي.';

  @override
  String get snriReferenceDay730 =>
      'بعد عامين من إيقاف SNRI: علامة تقدم\n\nالمصدر: Royal College of Psychiatrists — إيقاف مضادات الاكتئاب\n\nتنصح الكلية عادةً بعدم إيقاف مضادات الاكتئاب فجأة، وبأن يكون خفض الجرعة ملائمًا لكل شخص. وقد تتطلب أدوية مثل دولوكستين أو فينلافاكسين خفضًا أبطأ على مدى أشهر أو أكثر.\n\nلا يحدد الإرشاد عامين كحد بيولوجي للتعافي بعد إيقاف SNRI؛ هذه الذكرى تحتفل بالتقدم المستمر فقط.';

  @override
  String get snriMilestone1095Title => '3 أعوام: تقدم راسخ';

  @override
  String get snriMilestone1095Description =>
      'ثلاثة أعوام مدة كبيرة بعد إكمال خفض الجرعة. احتفل بالعادات والدعم والقرارات التي حافظت على تقدمك؛ فالطب لا يحدد في هذا التاريخ حدًا خاصًا للتعافي.';

  @override
  String get snriReferenceDay1095 =>
      'بعد 3 أعوام من إيقاف SNRI: تقدم مستمر\n\nالمصدر: Royal College of Psychiatrists — إيقاف مضادات الاكتئاب\n\nتختلف تجربة الانسحاب من شخص إلى آخر، وينبغي أن تراعي سرعة خفض الجرعة الشخص ومدة العلاج والأعراض السابقة والدواء المستخدم.\n\nلا يحدد أي إرشاد سريري ثلاثة أعوام كموعد عالمي للتعافي من SNRI؛ هذه المحطة تكرّم تقدمك واستقرارك.';

  @override
  String get snriMilestone1460Title => '4 أعوام: قوة مع الزمن';

  @override
  String get snriMilestone1460Description =>
      'تعكس أربعة أعوام تقدمًا ثابتًا بُني مع الوقت. تجربتك فردية، وهذه المحطة تكرّم ما حافظت عليه من دون الادعاء بوجود جدول زمني عصبي ثابت.';

  @override
  String get snriReferenceDay1460 =>
      'بعد 4 أعوام من إيقاف SNRI: تقدم طويل الأمد\n\nالمصدر: Royal College of Psychiatrists — إيقاف مضادات الاكتئاب\n\nتصف الكلية انسحاب مضادات الاكتئاب بأنه متفاوت وتوصي بخفض تدريجي ومخصص للجرعة. ويُذكر دولوكستين وفينلافاكسين ضمن الأدوية الأعلى خطرًا لأعراض الانسحاب.\n\nلا تجعل هذه الأدلة أربعة أعوام محطة عصبية محددة؛ اليوم احتفال بالتقدم المستمر.';

  @override
  String get snriMilestone1825Title => '5 أعوام: إنجاز خمس سنوات';

  @override
  String get snriMilestone1825Description =>
      'خمس سنوات محطة شخصية كبيرة. إنها تحتفل بالتقدم طويل الأمد بعد إيقاف SNRI مع الإقرار بأن الانسحاب والتعافي لا يسيران وفق جدول واحد للجميع.';

  @override
  String get snriReferenceDay1825 =>
      'بعد 5 أعوام من إيقاف SNRI: محطة خمس سنوات\n\nالمصدر: Royal College of Psychiatrists — إيقاف مضادات الاكتئاب\n\nيركز الإرشاد على خفض آمن ومخصص للجرعة والاستجابة لأعراض الانسحاب بدل فرض جدول تعافٍ ثابت على الجميع.\n\nلا يتضمن الإرشاد حدًا قائمًا على الأدلة للتعافي من SNRI عند خمس سنوات؛ ومع ذلك تبقى هذه ذكرى شخصية مهمة.';

  @override
