  @override
  String get tcaHeaderStarted => 'رحلة التعافي الخاصة بك';

  @override
  String get tcaHeaderNotStarted => 'فوائد التقليص التدريجي لـ TCAs';

  @override
  String get tcaSubtitleStarted => 'تتبع تقدمك واحتفل بكل إنجاز';

  @override
  String get tcaSubtitleNotStarted => 'انظر ماذا يحدث عند التناقص التدريجي';

  @override
  String get tcaMilestone3Title => 'اليوم 3: ارتداد كوليني';

  @override
  String get tcaMilestone3Description =>
      'يمكن أن يسبب إيقاف مضادات الاكتئاب ثلاثية الحلقات أعراض انسحاب حقيقية، ويُعد فرط النشاط الكوليني إحدى الآليات المقترحة. قد تظهر مبكرًا أعراض مثل الغثيان والإسهال وألم البطن والأرق والقلق والهياج والصداع، خاصة بعد الإيقاف المفاجئ أو الخفض السريع. اليوم الثالث إنجاز؛ توقيت الأعراض وشدتها يختلفان من شخص لآخر.';

  @override
  String get tcaMilestone7Title => 'أسبوع واحد: اجتزت المرحلة الأولى';

  @override
  String get tcaMilestone7Description =>
      'يبدأ انسحاب مضادات الاكتئاب عادة خلال بضعة أيام وغالبًا يستمر بضعة أسابيع. بعد أسبوع قد تظل أعراض مثل الغثيان والتعرق واضطراب النوم والخفقان والدوخة موجودة. سبعة أيام تقدم حقيقي، ويمكن أن يستمر التحسن وفق جداول زمنية مختلفة.';

  @override
  String get tcaMilestone14Title => 'أسبوعان: الانسحاب الحاد يخف';

  @override
  String get tcaMilestone14Description =>
      'عادةً ما تستمر أعراض إيقاف مضادات الاكتئاب مثل الغثيان والأرق واضطراب التوازن والأعراض الحسية وفرط الاستثارة من أسبوع إلى أسبوعين. عند اليوم 14 يصل كثير من الناس إلى نهاية هذه المرحلة الحادة.';

  @override
  String get tcaMilestone30Title => 'شهر واحد: الانسحاب الحاد هدأ غالبًا';

  @override
  String get tcaMilestone30Description =>
      'تستمر أعراض التوقف عن مضادات الاكتئاب عادةً من أسبوع إلى أسبوعين. عند 30 يومًا، يكون معظم الناس قد تجاوزوا تلك المرحلة الحادة، وتكون الأعراض الشبيهة بالإنفلونزا والغثيان واضطراب التوازن والأرق والاضطرابات الحسية وفرط الاستثارة قد هدأت أو زالت عادةً.';

  @override
  String get tcaMilestone90Title => '3 أشهر: الانسحاب الحاد خلفك';

  @override
  String get tcaMilestone90Description =>
      'تستمر أعراض التوقف عن مضادات الاكتئاب عادةً من أسبوع إلى أسبوعين. عند 90 يومًا، تكون قد تجاوزت الحد الأعلى لهذه الفترة الحادة المعتادة بأكثر من عشرة أسابيع؛ وعادةً ما تكون الأعراض الشبيهة بالإنفلونزا والغثيان واضطراب التوازن والأرق والاضطرابات الحسية وفرط الاستثارة قد هدأت أو زالت منذ مدة.';

  @override
  String get tcaMilestone180Title => 'ستة أشهر: الغالبية بلا انتكاسة';

  @override
  String get tcaMilestone180Description =>
      'بين الأشخاص الذين أوقفوا مضادات الاكتئاب بعد علاج الاكتئاب الشديد، وجد تحليل تلوي لـ35 تجربة أن معدل الانتكاس المجمع بعد ستة أشهر بلغ 34.8% — أي أن نحو 65% ظلوا بلا انتكاسة. هذه فترة استقرار هائلة.';

  @override
  String get tcaMilestone365Title => 'سنة واحدة: الغالبية بلا انتكاسة';

  @override
  String get tcaMilestone365Description =>
      'بين الأشخاص الذين أوقفوا مضادات الاكتئاب بعد علاج الاكتئاب الشديد، وجد تحليل تلوي لـ35 تجربة أن معدل الانتكاس المجمع بعد 12 شهرًا بلغ 45.12% — أي أن نحو 55% ظلوا بلا انتكاسة لعام كامل. هذه محطة كبرى من الاستقرار طويل الأمد.';

  @override
  String get tcaMilestone730Title => 'عامان: أساس راسخ';

  @override
  String get tcaMilestone730Description =>
      'مرّ عامان على إكمال الخفض التدريجي لجرعة TCA، وهو إنجاز مهم. تختلف تجربة التوقف من شخص إلى آخر، لذلك تحتفي هذه المحطة بالتقدم المستمر من دون الادعاء بوجود نقطة نهاية بيولوجية واحدة للجميع.';

  @override
  String get tcaReferenceDay730 =>
      'بعد عامين من TCA: تقدم مستمر\n\nالمصدر: NICE NG222 — Depression in adults: treatment and management\n\nتذكر NICE بوضوح أن TCA من مضادات الاكتئاب التي قد تظهر بعد إيقافها أعراض انسحاب. تختلف التجربة بين الأشخاص، ويُنصح بخفض الجرعة تدريجياً وبسرعة تناسب استجابة الفرد.\n\nلا تحدد الإرشادات عتبة بيولوجية عند عامين. تحتفي هذه الذكرى بعامين من التقدم المستمر من دون اختراع خط نهاية موحد.';

  @override
  String get tcaMilestone1095Title => '3 أعوام: تقدم مستمر';

  @override
  String get tcaMilestone1095Description =>
      'ثلاثة أعوام تمثل فترة طويلة من التقدم المستمر. لا تحدد الإرشادات السريرية هذه المدة كنهاية خاصة للتعافي بعد TCA؛ فالإنجاز هو الاستقرار والعادات والخيارات التي استمرت طوال هذه الأعوام.';

  @override
  String get tcaReferenceDay1095 =>
      'بعد ثلاثة أعوام من TCA: تقدم ثابت\n\nالمصدر: NICE NG222 — Depression in adults: treatment and management\n\nتذكر NICE بوضوح أن TCA من مضادات الاكتئاب التي قد تظهر بعد إيقافها أعراض انسحاب. تختلف التجربة بين الأشخاص، ويُنصح بخفض الجرعة تدريجياً وبسرعة تناسب استجابة الفرد.\n\nلا تعتبر الإرشادات ثلاثة أعوام مهلة موحدة للتعافي. تكرّم هذه المحطة الاستقرار والتقدم اللذين استمرا ثلاثة أعوام.';

  @override
  String get tcaMilestone1460Title => '4 أعوام: تقدم راسخ';

  @override
  String get tcaMilestone1460Description =>
      'أربعة أعوام تعكس تقدماً ثابتاً بُني مع الوقت. تختلف التجربة بعد إيقاف TCA بين الأفراد، وهذه المحطة تكرّم ما تم الحفاظ عليه من دون اختراع جدول عصبي ثابت.';

  @override
  String get tcaReferenceDay1460 =>
      'بعد أربعة أعوام من TCA: تقدم طويل الأمد\n\nالمصدر: NICE NG222 — Depression in adults: treatment and management\n\nتذكر NICE بوضوح أن TCA من مضادات الاكتئاب التي قد تظهر بعد إيقافها أعراض انسحاب. تختلف التجربة بين الأشخاص، ويُنصح بخفض الجرعة تدريجياً وبسرعة تناسب استجابة الفرد.\n\nلا توجد في الإرشادات عتبة بيولوجية عند أربعة أعوام. ومع ذلك تظل أربعة أعوام علامة مهمة على التقدم طويل الأمد.';

  @override
  String get tcaMilestone1825Title => '5 أعوام: تقدم يدوم';

  @override
  String get tcaMilestone1825Description =>
      'خمسة أعوام ذكرى شخصية كبيرة. إنها علامة على تغير مستمر بعد إيقاف TCA، مع احترام أن التوقف والتعافي لا يسيران وفق جدول واحد لدى الجميع.';

  @override
  String get tcaReferenceDay1825 =>
      'بعد خمسة أعوام من TCA: ذكرى كبيرة\n\nالمصدر: NICE NG222 — Depression in adults: treatment and management\n\nتذكر NICE بوضوح أن TCA من مضادات الاكتئاب التي قد تظهر بعد إيقافها أعراض انسحاب. تختلف التجربة بين الأشخاص، ويُنصح بخفض الجرعة تدريجياً وبسرعة تناسب استجابة الفرد.\n\nلا تحدد الأدلة عتبة للتعافي من TCA عند خمسة أعوام. تظل خمسة أعوام ذكرى شخصية كبيرة وعلامة قوية على تغير مستمر.';

  @override
  String get settingsShowTcaTracking => 'إظهار تتبع TCA';

