  @override
  String get maoiPageTitle => 'استعادة ماوي';

  @override
  String get maoiHeaderStarted => 'رحلة التعافي الخاصة بك';

  @override
  String get maoiHeaderNotStarted => 'فوائد التقليص التدريجي لمثبطات MAOI';

  @override
  String get maoiSubtitleStarted => 'تتبع تقدمك واحتفل بكل إنجاز';

  @override
  String get maoiSubtitleNotStarted => 'انظر ماذا يحدث عند التناقص التدريجي';

  @override
  String get maoiMilestone3Title => 'اليوم 3: أعلى مراحل الخطر';

  @override
  String get maoiMilestone3Description =>
      'تحمل مثبطات MAOIs أخطر مخاطر التوقف عن تناول أي فئة من مضادات الاكتئاب. يمكن أن يؤدي التوقف المفاجئ — خاصة عن الفينيلزين والترانيلسيبرومين — إلى إثارة شديدة، وارتباك، وهلوسة، ورمع عضلي، وارتفاع الحرارة. إذا كنت تعاني من هذه الأعراض، فاطلب العناية الطبية الفورية. تعمل مثبطات MAOI عن طريق تعطيل إنزيمات MAO بشكل دائم؛ يتطلب التعافي من الجسم تصنيع إنزيم جديد، وهي عملية تستغرق حوالي 14 يومًا.';

  @override
  String get maoiMilestone7Title => 'أسبوع: تجدد إنزيم MAO';

  @override
  String get maoiMilestone7Description =>
      'تقوم مثبطات MAOI بتدمير جزيئات إنزيم MAO بشكل دائم؛ يتطلب التعافي تخليق إنزيم جديد تمامًا. بحلول أسبوع واحد، قد يكون ما يقرب من 50٪ من نشاط MAO الطبيعي قد تعافى. يتم تقليل أعراض التوقف الحادة الشديدة (الهذيان، الرمع العضلي، ارتفاع الحرارة) بشكل كبير. يظل الإشراف الطبي الدقيق مهمًا.';

  @override
  String get maoiMilestone14Title => 'أسبوعان: تعافي نشاط MAO';

  @override
  String get maoiMilestone14Description =>
      'أسبوعين هو الإطار الزمني السريري القياسي لاستعادة إنزيم MAO بعد التوقف. بحلول اليوم الرابع عشر تقريبًا، يتم استعادة نشاط MAO-A وMAO-B إلى حد كبير ويتم إعادة إنشاء التمثيل الغذائي الطبيعي للتيرامين. يمكن عادةً تخفيف القيود الغذائية المطلوبة أثناء علاج MAOI بالتشاور مع واصف الدواء الخاص بك.';

  @override
  String get maoiMilestone30Title => 'شهر: توازن كيمياء الدماغ';

  @override
  String get maoiMilestone30Description =>
      'بعد شهر واحد من إيقاف MAOI، ينشط إنزيم MAO مرة أخرى ويتعامل الدماغ مع السيروتونين والنورادرينالين والدوبامين والتيرامين بشكل طبيعي. لقد انتهت فترة التفاعل الغذائي والدواء الخاصة، على الرغم من أنه لا يزال يتعين عليك إخبار الأطباء عن استخدام MAOI السابق.';

  @override
  String get maoiMilestone90Title => 'ثلاثة أشهر: تطبيع كيمياء الدماغ';

  @override
  String get maoiMilestone90Description =>
      'تمنح ثلاثة أشهر الحالة المزاجية وأنظمة الطاقة في الدماغ وقتًا كبيرًا لإعادة التكيف بعد مثبطات MAOI. يستقر المزاج والطاقة والتفكير الواضح حيث يتعامل الدماغ مع هذه المواد الكيميائية بشكل طبيعي مرة أخرى.';

  @override
  String get maoiMilestone180Title => 'ستة أشهر: التعافي طويل الأمد';

  @override
  String get maoiMilestone180Description =>
      'تمثل ستة أشهر فترة كبيرة من وظيفة أحادي الأمين الطبيعية. لقد عادت أعداد مستقبلات السيروتونين والنورادرينالين والدوبامين إلى طبيعتها. وقد عادت مسارات الفينيثيلامين (PEA) المتأثرة أيضًا بمثبطات MAOI إلى مستوياتها الطبيعية، وهو جانب من جوانب التعافي غالبًا ما يتم التغاضي عنه والذي يساهم في التطبيع العاطفي.';

  @override
  String get maoiMilestone365Title => 'سنة واحدة: تم تحقيق التعافي';

  @override
  String get maoiMilestone365Description =>
      'بعد مرور عام على إيقاف MAOI، يمنح الدماغ والجسم عامًا كاملاً بدون الدواء. لقد كان للمزاج والطاقة والتفكير الواضح والتنظيم الكيميائي الطبيعي للدماغ وقتًا طويلاً للاستقرار والتعافي.';

  @override
  String get settingsShowMaoiTracking => 'إظهار تتبع MAOI';

  @override
  String get settingsNotifyMaoi => 'إخطار MAOI بالتقدم في الإقلاع عن التدخين';

