  @override
  String get adderallReferenceDay1 =>
      'انسحاب الأمفيتامين: ما الذي يحدث في البداية؟\n\nالمصدر: MedlinePlus (U.S. National Library of Medicine)\n\nما الأمفيتامينات؟\nالأمفيتامينات منشطات تشمل مواد غير مشروعة، مثل «السبيد» المتداول في الشارع، وأدوية موصوفة لعلاج اضطراب فرط الحركة ونقص الانتباه والخدار، مثل Adderall وVyvanse. وهي ترفع الدوبامين والنورإبينفرين بسرعة، ما قد يسبب تركيزًا وطاقة ونشوة شديدة. ومع الاستخدام المنتظم والكثيف يتكيف الدماغ مع هذه الزيادات المتكررة، لذلك قد ينخفض المزاج والطاقة والدافع مؤقتًا بعد التوقف.\n\nأعراض الانسحاب الشائعة\nيذكر MedlinePlus أن الأعراض التالية شائعة عند إيقاف الأمفيتامينات:\n• رغبة شديدة في تعاطي المادة\n• تقلبات في المزاج بين الاكتئاب والانفعال والقلق\n• الشعور بالتعب طوال اليوم\n• صعوبة في التركيز\n• هلوسات، أي رؤية أو سماع أشياء غير موجودة\n• أعراض جسدية مثل الصداع والأوجاع والآلام وزيادة الشهية واضطراب النوم\n\nهل الانسحاب خطير؟\nلا يصف MedlinePlus انسحاب الأمفيتامين بحد ذاته بأنه خطر طبي، لكنه يشير إلى أن الأعراض الشديدة قد تتطلب برنامج علاج سكنيًا، وأن مشكلات المزاج والانفعالات المرتبطة باستخدام الأمفيتامين، بما فيها الاكتئاب، قد تكون خطيرة وتحتاج إلى دعم.\n\nالحصول على المساعدة\nينصح MedlinePlus بالتواصل مع مقدم رعاية صحية إذا كنت أنت أو شخص تعرفه يعتمد على الأمفيتامينات ويحتاج إلى مساعدة للتوقف. وإذا راودتك أفكار لإيذاء النفس، فيشير المصدر إلى خدمات الأزمات مثل 988 أو 911.';

  @override
  String get adderallReferenceDay3 =>
      'إدارة انسحاب الأمفيتامين: اليوم الثالث\n\nالمصدر: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings,\" World Health Organization (2009)، NCBI Bookshelf\n\nأين يقع اليوم الثالث؟\nتذكر إرشادات منظمة الصحة العالمية أن أعراض انسحاب المنشطات «تبدأ خلال 24 ساعة من آخر استخدام للمنشط وتستمر 3–5 أيام». لذلك يقع اليوم الثالث في قلب المرحلة الحادة، وغالبًا ما يكون من أصعب الأيام قبل أن تبدأ الأعراض في التراجع.\n\nالأعراض\nبالنسبة للمنشطات من نوع الأمفيتامين، تذكر الإرشادات:\n• الانفعال والتهيج\n• الاكتئاب\n• زيادة النوم والشهية\n• آلام العضلات\nوقد تظهر لدى من يستخدمون كميات كبيرة أعراض ذهانية مثل الارتياب أو اضطراب التفكير أو الهلوسات.\n\nالتحدي نفسي في الغالب\nبخلاف انسحاب الكحول أو الأفيونات، لا يُعد القيء أو الرعشة أو الاختلاجات من السمات المعتادة لانسحاب المنشطات. وتكون الصعوبة الرئيسية نفسية غالبًا، مثل انخفاض المزاج وفقدان المتعة والرغبة الشديدة في التعاطي.\n\nنهج التعامل\nتوصي إرشادات منظمة الصحة العالمية بالرعاية الداعمة:\n• شرب ما لا يقل عن 2–3 لترات من الماء يوميًا\n• تناول مكمل متعدد الفيتامينات يحتوي على فيتامينات المجموعة B وفيتامين C\n• علاج الأوجاع والقلق بحسب الأعراض\n• في حالات الانفعال الشديد، البدء بالاستراتيجيات السلوكية واستخدام التهدئة بالديازيبام عند الضرورة فقط\n\nبعد المرحلة الحادة\nتذكر الإرشادات أن أصعب مرحلة من الانسحاب تستمر بضعة أيام فقط، ثم قد تليها فترة تعافٍ أخف تمتد من شهر إلى شهرين.';

  @override
  String get adderallReferenceDay7 =>
      'أسبوع من دون Adderall: أصعب مرحلة بدأت تمر\n\nالمصدر: Li & Shoptaw, \"Clinical Management of Psychostimulant Withdrawal: Review of the Evidence,\" Addiction (2023)، PubMed Central\n\nتراجع المرحلة الحادة\nتقسم مراجعة الأدلة هذه انسحاب المنشطات النفسية إلى مراحل. في المرحلة الحادة «تبلغ الأعراض ذروتها بعد أول 2–3 أيام»، و«عادة ما يزول الانزعاج الشديد الناتج عنها خلال 4–7 أيام». وبنهاية الأسبوع الأول يكون معظم الناس قد تجاوزوا أصعب جزء من الانهيار الأولي؛ تبدأ الطاقة والشهية في الاستقرار ويصبح النوم أكثر انتظامًا.\n\nماذا بعد؟\nتذكر المراجعة أن معظم الأعراض المتبقية تواصل التراجع خلال الأسبوعين أو الأسابيع الثلاثة التالية. وفي اليوم السابع يكون التعافي قد بدأ بالفعل.\n\nما الذي قد يبقى في اليوم السابع؟\nغالبًا ما تستمر الأعراض النفسية بعد زوال الجزء الجسدي من الانهيار:\n• انخفاض الدافع وفقدان المتعة\n• صعوبة التركيز\n• مزاج ما زال أدنى من المعتاد\nيعكس ذلك نظام الدوبامين وهو يعيد التكيف، وهو جزء طبيعي ومؤقت من التعافي.\n\nعلامة على التعافي\nلا يوجد دواء معتمد من إدارة الغذاء والدواء الأمريكية FDA لعلاج انسحاب المنشطات على وجه التحديد. لذلك تمثل الرعاية الداعمة والروتين المنظم والنوم والتغذية والدعم النفسي ركائز مهمة في هذه المرحلة.';

  @override
  String get adderallReferenceDay14 =>
      'أسبوعان من دون Adderall: الدخول في مرحلة تعافٍ أطول\n\nالمصدر: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings,\" World Health Organization (2009)، NCBI Bookshelf\n\nبعد المرحلة الحادة\nتضع منظمة الصحة العالمية أشد مرحلة من انسحاب المنشطات في حدود 3–5 أيام، تليها فترة تعافٍ أخف تستمر نحو شهر إلى شهرين. وبعد أسبوعين يكون الانهيار الأولي قد أصبح بعيدًا وراءك.\n\nكيف تبدو مرحلة التعافي الأطول؟\nيكون النوم المفرط والانفعال وآلام العضلات قد هدأت إلى حد كبير. وما يبقى يكون عادة أخف: مزاج منخفض أو متقلب، ودافع أقل، ورغبة متقطعة في التعاطي بينما يعيد نظام المكافأة في الدماغ التكيف.\n\nالنوم والشهية\nتبدأ زيادة النوم والشهية في المرحلة الحادة بالعودة إلى الوضع المعتاد. ومع استقرار النوم يميل المزاج والتركيز والطاقة إلى التحسن أيضًا.\n\nخطر الانتكاس واضطراب فرط الحركة ونقص الانتباه\nتظل هذه مرحلة يرتفع فيها خطر الانتكاس نسبيًا، ولا سيما إذا عادت أعراض اضطراب فرط الحركة ونقص الانتباه الأساسية من دون دواء. وتؤكد إرشادات منظمة الصحة العالمية أهمية الدعم النفسي ومهارات الوقاية من الانتكاس. ولمن كانوا يتناولون Adderall لعلاج الاضطراب، قد يكون هذا وقتًا مناسبًا لمناقشة استراتيجيات غير منشطة أو بدائل مع الطبيب.';

  @override
  String get adderallReferenceDay30 =>
      'شهر من دون Adderall: معظم الأعراض أصبحت وراءك\n\nالمصدر: Li & Shoptaw, \"Clinical Management of Psychostimulant Withdrawal: Review of the Evidence,\" Addiction (2023)، PubMed Central\n\nأين يقع الشهر الأول؟\nوجدت المراجعة أن معظم أعراض الانسحاب تتراجع خلال أول أسبوعين إلى ثلاثة أسابيع. وبعد 30 يومًا يكون معظمها قد خف، ويكون المزاج والدافع عادة أفضل بكثير مما كانا عليه في الأسبوع الأول.\n\nمرحلة التعافي اللاحقة\nمن شهر إلى ستة أشهر يمكن أن تستمر الذاكرة والتخطيط والتركيز واتخاذ القرار في التحسن. وبعد شهر يكون الانهيار الأولي قد انتهى وتكون هذه التحسينات جارية بالفعل.\n\nالمزاج والدافع\nيكون الفقد الشديد للمتعة في مرحلة الانهيار قد تراجع بدرجة كبيرة. وقد تبدأ الأنشطة التي بدت بلا متعة في الأسبوع الأول بالشعور بالمكافأة من جديد مع تعافي الإشارات الطبيعية للدوبامين.\n\nلمن لديهم اضطراب فرط الحركة ونقص الانتباه\nإذا كان Adderall موصوفًا لعلاج اضطراب فرط الحركة ونقص الانتباه، فقد تصبح الأعراض الأساسية أوضح الآن. ومن المهم في هذه المرحلة العمل مع مقدم رعاية صحية على استراتيجيات غير منشطة أو بدائل مناسبة.';

  @override
  String get adderallReferenceDay60 =>
      'شهران من دون Adderall: مرحلة التعافي الأطول تقترب من نهايتها\n\nالمصدر: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings,\" World Health Organization (2009)، NCBI Bookshelf\n\nأين يقع الشهران؟\nتصف منظمة الصحة العالمية فترة تعافٍ أخف تستمر نحو شهر إلى شهرين بعد الانهيار الأولي. وعند 60 يومًا تكون في الطرف الآخر من هذه الفترة، فيما تكون الأعراض المتبقية قد تراجعت إلى حد كبير.\n\nما الذي يتحسن؟\nيهدأ بدرجة كبيرة، لدى معظم الناس، الانفعال والمزاج المكتئب واضطراب النوم والشهية التي تذكرها الإرشادات ضمن أعراض انسحاب المنشطات:\n• يصبح المزاج المعتاد أكثر استقرارًا وتقل تقلبات التعافي المبكر\n• يعود النوم والشهية إلى نمط أكثر طبيعية\n• يستجيب نظام المكافأة بسهولة أكبر لمتع الحياة اليومية، مثل الطعام والرياضة والتواصل مع الآخرين\n\nعلامة على التعافي\nقد تجعل الجرعات الأعلى وفترات الاستخدام الأطول التعافي أبطأ، بينما يمنح الاستمرار في الامتناع عن استخدام المنشطات المزاج والدافع وصفاء التفكير فرصة لمواصلة الاقتراب من الوضع الطبيعي خلال الأشهر التالية.\n\nالصحة الجسدية\nمع خروج الدواء من الحياة اليومية، تتراجع آثاره المنشطة في معدل ضربات القلب والشهية والوزن، ويخف العبء القلبي الوعائي المرتبط باستخدام المنشطات.';

  @override
  String get adderallReferenceDay90 =>
      'ثلاثة أشهر من دون Adderall: تجاوزت الأصعب والتعافي مستمر\n\nالمصدر: Li & Shoptaw, \"Clinical Management of Psychostimulant Withdrawal: Review of the Evidence,\" Addiction (2023)، PubMed Central\n\nأين تقع 90 يومًا؟\nبعد ثلاثة أشهر تكون الأعراض المبكرة قد انتهت منذ فترة، بينما قد تستمر الذاكرة والتخطيط والتركيز واتخاذ القرار ونظام المكافأة في التحسن.\n\nالتفكير والذاكرة يواصلان التعافي\nوجدت المراجعة أن الذاكرة والتخطيط والتركيز واتخاذ القرارات المتعلقة بالمخاطر قد تتحسن على مدى أشهر. وعند 90 يومًا يظل التركيز والذاكرة يتحركان في اتجاه أفضل مع استمرار الامتناع عن استخدام المنشطات.\n\nلماذا لا تزال هذه المرحلة مهمة؟\nلا يوجد دواء معتمد من FDA يستهدف انسحاب المنشطات تحديدًا، لذلك تمثل البنية اليومية والعلاج والرياضة والنوم والدعم أدوات مهمة لعبور هذه المرحلة. وبناء هذه العادات الآن يدعم استمرار التعافي.\n\nالصورة الأكبر\nثلاثة أشهر إنجاز حقيقي. لقد أصبحت أصعب الفترات الجسدية والعاطفية وراءك، ومع استمرار الامتناع عن الاستخدام يمكن أن يستمر التحسن تدريجيًا.';

  @override
  String get adderallReferenceDay180 =>
      'ستة أشهر من دون Adderall: بعيدًا عن أصعب مرحلة\n\nالمصدر: \"Withdrawal Syndromes,\" StatPearls (NCBI Bookshelf)، U.S. National Library of Medicine\n\nماذا يقول StatPearls عن المنشطات؟\nيصف هذا المرجع السريري التعافي بعد المنشطات بأنه انهيار أولي يتبعه تحسن تدريجي. وتشمل المشكلات الشائعة الاكتئاب وكثرة النوم وزيادة الجوع وانخفاض المزاج وبطء الحركة والتفكير. وقد يستمر الاكتئاب عدة أسابيع، مع استمرار تعافٍ أخف بعد ذلك.\n\nأين تقع الستة أشهر؟\nبعد ستة أشهر تكون قد تجاوزت بكثير المرحلة الحادة ومرحلة الاكتئاب التي تمتد عدة أسابيع كما يصفها StatPearls. ويكون التعافي التدريجي قد حظي بوقت طويل للتقدم، وبالنسبة لمعظم الناس يصبح المزاج المعتاد والنوم والشهية والدافع أكثر استقرارًا.\n\nعلامة على التعافي\nيصف StatPearls تعافيًا تدريجيًا يستمر بعد الأسابيع الأولى. وبعد ستة أشهر يكون الانهيار الحاد ومرحلة الاكتئاب الممتدة لعدة أسابيع بعيدين وراءك، فيما يصبح استقرار المزاج والنوم والشهية والدافع هو النمط الغالب.\n\nالعلاقة باضطراب فرط الحركة ونقص الانتباه\nبالنسبة لمن كانوا يتناولون Adderall لعلاج اضطراب فرط الحركة ونقص الانتباه، تعد ستة أشهر وقتًا مناسبًا لمراجعة الأعراض الحالية بوضوح مع الطبيب ومعرفة ما إذا كانت الأساليب غير المنشطة، مثل الرياضة والنوم والروتين والعلاج النفسي أو الأدوية البديلة، تلبي احتياجاتك.';

  @override
  String get adderallReferenceDay365 =>
      'سنة من دون Adderall: تعافٍ كبير بصياغة واقعية\n\nالمصدر: Berman et al., \"Potential Adverse Effects of Amphetamine Treatment on Brain and Behavior: A Review,\" Molecular Psychiatry (2008)، PubMed Central\n\nعن هذه المراجعة\nتبحث هذه المراجعة في الآثار التي قد يسببها التعرض للأمفيتامين بجرعات عالية أو لمدة طويلة على الدماغ، وتوثق تعافيًا يمكن قياسه خلال الامتناع عن الاستخدام.\n\nماذا تقول عن التعافي؟\nتوثق المراجعة تعافي تدفق الدم في الدماغ والبروتينات التي تعيد تدوير الدوبامين بعد الامتناع طويل الأمد. تتعافى بعض مناطق الدماغ أسرع من غيرها، لكن الاتجاه العام واضح: يحدث تعافٍ بعد توقف الاستخدام.\n\nالتعافي طويل الأمد\nتوثق المراجعة تحسنًا يمكن قياسه في تدفق الدم الدماغي وإعادة تدوير الدوبامين بعد الامتناع طويل الأمد. وبعد سنة تكون هذه الأنظمة الدماغية قد حظيت بعام كامل لمواصلة التعافي.\n\nماذا يعني ذلك بعد سنة؟\nبالنسبة لمعظم الناس، وخصوصًا من تناولوا Adderall بالجرعات الموصوفة، قد تعني سنة من دون الدواء أن أنظمة المكافأة والانتباه والدافع تعمل جيدًا في الحياة اليومية. وقد يحتاج الاستخدام الأثقل أو الأطول إلى وقت إضافي، لكن التعافي يستمر. ويكون خطر الانتكاس أقل بكثير مما هو عليه في بدايات التعافي.';

  @override
  String get alcoholReferenceDay1 =>
      'ماذا يحدث لنومك عندما تتوقف عن الشرب؟\n\nالمصدر: \"Alcohol and the Sleeping Brain\" (Colrain, Nicholas & Baker)، Handbook of Clinical Neurology — بحث مُراجع من الأقران ومستضاف لدى NIH\n\nبنية النوم والكحول\nللكحول تأثير مهدئ، لذلك قد يقلل زمن الاستغراق في النوم ويزيد نوم الموجات البطيئة العميق في النصف الأول من الليل. لكن لذلك ثمنًا: فهو يثبط نوم حركة العين السريعة (REM)، المرتبط بتثبيت الذاكرة وتنظيم المشاعر، ويجعل النوم أكثر تقطعًا في النصف الثاني من الليل أثناء استقلابه.\n\nأول ليلة بلا كحول\nلأن الكحول يثبط نوم REM، قد تجلب الليالي الأولى بدونه ارتدادًا في REM: أحلامًا حية ونومًا أخف ومتقطعًا بينما تعود أنماط النوم الطبيعية. وهذا جزء طبيعي ومؤقت من التعافي.\n\nبدء التعافي\nمع إعادة تكيّف الدماغ خلال الأيام والأسابيع التالية، يتحسن نوم REM وجودة النوم عمومًا. واضطراب النوم من أكثر أعراض الانسحاب استمرارًا، لكنه يميل إلى الاقتراب من الطبيعي مع استمرار الامتناع عن الكحول.\n\nملاحظة عن الشرب بكثرة\nلدى من يشربون بكثرة أو يوميًا منذ مدة طويلة، قد تظهر خلال أول 24 ساعة أيضًا أعراض انسحاب مثل القلق والتعرق والرعشة والغثيان. وقد يكون الانسحاب الشديد خطيرًا؛ إذا كنت تشرب بكثرة كل يوم فتحدث إلى طبيب قبل التوقف المفاجئ.';

  @override
  String get alcoholReferenceDay3 =>
      'اليوم الثالث: نافذة ذروة الانسحاب\n\nالمصدر: \"Alcohol Withdrawal\"، StatPearls — مراجَع من الأقران، المكتبة الوطنية للطب التابعة للمعاهد الوطنية للصحة\n\nحول 72 ساعة\nيمكن أن تبدأ أعراض انسحاب الكحول خلال ساعات وغالبًا ما تبلغ ذروتها قرب 72 ساعة. يذكر StatPearls الارتعاش والأرق والهياج والتعرق وارتفاع ضغط الدم وتسارع القلب والنوبات ضمن علامات فرط الاستثارة العصبية.\n\nثلاثة أيام قوية\nالوصول إلى 72 ساعة إنجاز كبير لأنه يقع في نافذة الذروة الموثقة للعديد من الأعراض الحادة. يتفاعل الجهاز العصبي مع الفقد المفاجئ لتأثير الكحول المثبط عبر GABA بينما يدفع فائض الغلوتامات فرط النشاط الذاتي.\n\nقد يصل الانسحاب الشديد لاحقًا\nقد يحدث هذيان انسحاب الكحول (delirium tremens) خلال 3–8 أيام بعد التوقف وقد يكون مميتًا. الانسحاب الشديد حالة طبية طارئة. من يشربون بكثرة يوميًا، وأي شخص لديه تاريخ من نوبات الانسحاب أو الهذيان، ينبغي أن يطلبوا نصيحة طبية بدل التوقف المفاجئ دون دعم.\n\nما الذي يستدعي الانتباه؟\nتحتاج الحمى أو الهياج الشديد أو التعرق الغزير أو الهلوسة أو الارتباك أو النوبات أو تسارع القلب الشديد أو ارتفاع ضغط الدم الشديد إلى رعاية طبية عاجلة.';

  @override
  String get alcoholReferenceDay7 =>
      'كيف يتعافى الجهاز المناعي\n\nالمصدر: \"Alcohol and the Immune System\" (Sarkar, Jung & Wang)، Alcohol Research: Current Reviews — بحث مُراجع من الأقران ومستضاف لدى NIH\n\nكيف يضعف الكحول المناعة\nيضعف الكحول الجهاز المناعي بطرق متعددة. وحتى نوبة واحدة من الشرب بكثرة قد تقلل القدرة على مقاومة العدوى لمدة تصل إلى 24 ساعة. أما الاستخدام طويل الأمد فيقلل خلايا الدم البيضاء ويعطل الإشارات المناعية ويضر دفاعات الأمعاء والرئتين، ما يزيد خطر العدوى ويبطئ التئام الجروح.\n\nإزالة العامل الضار\nتتحسن كثير من هذه الآثار بعد توقف التعرض للكحول. تبدأ خلايا الدم البيضاء والإشارات المناعية في التعافي، وتبدأ دفاعات الأمعاء والمجاري الهوائية في الإصلاح. وخلال الأسبوع الأول لا يعود الجهاز المناعي يتعرض للتثبيط اليومي، وتبدأ مقاومة العدوى الشائعة في التحسن.\n\nعملية تدريجية\nيستغرق التعافي المناعي الكامل أكثر من أسبوع، وتعتمد درجة الإصلاح على شدة الشرب ومدته، لكن الأسبوع الأول بلا كحول هو بداية إعادة البناء.';

  @override
  String get alcoholReferenceDay14 =>
      'التعافي المبكر للدماغ مع الامتناع عن الكحول\n\nالمصدر: Bartsch AJ وآخرون، \"Manifestations of early brain recovery associated with abstinence from alcoholism\"، Brain (2007) — بحث مُراجع من الأقران\n\nقياس التعافي\nاستخدمت الدراسة التصوير بالرنين المغناطيسي لمتابعة أشخاص خضعوا حديثًا لإزالة السموم وكانوا يعانون من الاعتماد على الكحول خلال الأسابيع الأولى من الامتناع، وقارنتهم بأشخاص أصحاء. ورصدت الدراسة إعادة البناء الجسدي للدماغ بعد توقف الشرب.\n\nاستعادة حجم الدماغ\nيمكن للاستخدام المزمن للكحول أن يقلص الدماغ، جزئيًا بسبب انخفاض قابل للعكس في حجم الخلايا وليس فقط بسبب فقدان دائم للخلايا. ومع الامتناع، قاس الباحثون زيادة متوسطة تقارب 2٪ في حجم الدماغ الكلي، وتركزت حول المخيخ والدماغ المتوسط والبطينات والمناطق الجبهية. ويحدث جزء كبير من هذا التحسن مبكرًا خلال أول أسبوعين تقريبًا بلا كحول.\n\nالمخيخ والانتباه\nكان التعافي واضحًا خصوصًا في مناطق الدماغ المرتبطة بالحركة والانتباه. وارتفع مؤشر لصحة خلايا الدماغ بالتوازي مع تحسن قابل للقياس في الانتباه، أي إن التعافي الجسدي رافقته مكاسب فعلية في التفكير.\n\nأساس وليس خط النهاية\nتتعافى الوظائف العليا مثل الاستدلال المعقد بصورة أكثر تدريجية، لكن أول أسبوعين يوضحان أن الدماغ يبدأ التعافي سريعًا بعد إزالة الكحول.';

  @override
  String get alcoholReferenceDay30 =>
      'ينخفض ضغط الدم عندما تتوقف عن تناول الكحول\n\nالمصدر: روريك وآخرون، \"تأثير انخفاض استهلاك الكحول على ضغط الدم: مراجعة منهجية وتحليل تلوي\"، مجلة لانسيت للصحة العامة (2017) - مراجعة النظراء\n\nالدليل\nجمع هذا التحليل التلوي 36 تجربة عشوائية (حوالي 2865 مشاركًا) لاختبار ما يحدث لضغط الدم عندما يشرب الناس كميات أقل. ووجدت تأثيرًا واضحًا يعتمد على الجرعة: كلما قلّل شخص ما من تناوله، انخفض ضغط دمه.\n\nما مدى حجم التأثير؟\nالأشخاص الذين شربوا مشروبين أو أقل يوميًا لم يلاحظوا أي تغير ملحوظ في ضغط الدم نتيجة للتخفيض. وفوق هذا الحد، كان التأثير يعتمد على الجرعة: كان التأثير أقوى لدى الأشخاص الذين يشربون ستة مشروبات أو أكثر يوميًا وخفضوا تناولهم بمقدار النصف تقريبًا، حيث انخفض ضغط الدم الانقباضي بنحو 5.5 ملم زئبق والضغط الانبساطي بنحو 4.0 ملم زئبقي في المتوسط. إن تقليل هذا الحجم له معنى سريريًا، حيث يمكن مقارنته ببعض أدوية ضغط الدم، وهو ما يكفي لخفض خطر الإصابة بالسكتة الدماغية وأمراض القلب على المدى الطويل.\n\nلماذا يهم شهر واحد\nيرفع الكحول ضغط الدم عن طريق تنشيط الاستجابة للتوتر، ورفع الكورتيزول وتصلب الأوعية الدموية. تظهر التجارب في هذه المراجعة أن الفوائد تظهر على مدى أسابيع من الانخفاض المستمر - لذلك، بعد حوالي شهر من الامتناع عن شرب الخمر، يكون لدى ضغط الدم لدى الشخص الذي يشرب الخمر وقتًا طويلاً للاستقرار نحو مستوى صحي.\n\nتأثير العتبة\nوجدت المراجعة عتبة واضحة: تركزت الفائدة لدى الأشخاص الذين يشربون أكثر من مشروبين في اليوم، وتزداد تدريجياً كلما زاد الشرب السابق. إذا كنت تشرب الخمر بشكل خفيف، فلا تتوقع هذه الفائدة المحددة لضغط الدم - ولكن الأشخاص الذين يشربون بكثرة يحصلون على فائدة حقيقية وقابلة للقياس للقلب والأوعية الدموية من التوقف.';

  @override
  String get alcoholReferenceDay60 =>
      'تعافي الكبد بعد التوقف عن الشرب\n\nالمصدر: المعهد الوطني لتعاطي الكحول وإدمان الكحول (NIAAA)، \"Alcohol\'s Effects on the Body\"\n\nكيف يضر الكحول بالكبد\nيعالج الكبد معظم الكحول الذي تشربه ويتحمل الجزء الأكبر من الضرر. يصف NIAAA تطور إصابات الكبد المرتبطة بالكحول: تبدأ بالكبد الدهني (التنكس الدهني، أي تراكم الدهون في خلايا الكبد)، وقد تتطور إلى التهاب الكبد الكحولي، ومع الاستهلاك الكثيف طويل الأمد إلى التليف وتشمع الكبد.\n\nالمراحل المبكرة قابلة للتحسن\nالنقطة المهمة أن الكبد يتمتع بقدرة كبيرة على التجدد، ويمكن أن تتحسن المراحل المبكرة من الضرر عند التوقف عن الشرب. والكبد الدهني خصوصًا يتحسن غالبًا مع استمرار الامتناع عن الكحول. وبعد نحو شهرين بلا كحول تكون للكبد فرصة فعلية لتقليل تراكم الدهون وتهدئة الالتهاب واستعادة وظيفة أكثر صحة، وهو ما ينعكس عادة في انخفاض إنزيمات الكبد (ALT وAST).\n\nأبعد من الكبد\nيشير NIAAA إلى أن الكحول يجهد أيضًا القلب والبنكرياس والجهاز المناعي. ومنح الجسم فترة ممتدة بلا كحول يسمح لهذه الأجهزة بالتعافي كذلك، ما يساهم في طاقة أكثر استقرارًا وصحة عامة أفضل في هذه المرحلة.';

  @override
  String get alcoholReferenceDay90 =>
      'التفكير والذاكرة بعد ثلاثة أشهر بلا كحول\n\nالمصدر: مراجعة منهجية للتعافي العصبي النفسي بعد الامتناع عن الكحول (PubMed Central، 2024) — بحث مُراجع من الأقران\n\nما الذي تظهره الأدلة؟\nجمعت المراجعة دراسات تابعت كيفية تعافي التفكير والذاكرة بعد توقف الأشخاص عن الشرب. تتجه معظم القدرات نحو الطبيعي خلال نحو ستة إلى اثني عشر شهرًا، وبعضها يتحسن أبكر.\n\nما الذي يتحسن أولًا؟\nتتعافى قدرتان أسرع نسبيًا: سرعة المعالجة الأساسية، التي وجدت المراجعة أنها تتحسن عادة بحلول نحو شهر رغم تأخر الدقة في المهام الأكثر تعقيدًا، وتحديث الذاكرة العاملة. وبحلول قرابة ثلاثة أشهر يلاحظ كثيرون تحسنًا في هاتين القدرتين.\n\nما الذي يستغرق وقتًا أطول؟\nيواصل الانتباه والتخطيط واتخاذ القرار والتحكم في الاندفاعات والإدراك والذاكرة التحسن خلال فترة التعافي الممتدة من ستة إلى اثني عشر شهرًا.\n\nما الذي يؤثر في التعافي؟\nتشير المراجعة إلى أن التعافي يتأثر بعوامل مثل العمر وحالة التدخين والقدرات السابقة للمرض، لكنه لا يرتبط بصورة ثابتة بإجمالي كمية الكحول التي شُربت سابقًا. والمسار المتوقع هو التحسن.\n\nلماذا يهم ذلك؟\nوضوح التفكير جزء عملي من التعافي: فالانتباه واتخاذ القرار بصورة أفضل يساعدان الناس على الاستمرار في العلاج وتجنب الانتكاس.';

  @override
  String get alcoholReferenceDay180 =>
      'تعافي الدماغ بعد ستة أشهر بلا كحول\n\nالمصدر: مراجعة مُحكّمة للتعافي البنيوي والوظيفي للدماغ أثناء الامتناع عن تعاطي المواد (PubMed Central)\n\nالتعافي مستمر\nالاستعادة المبكرة لحجم الدماغ في الأسابيع الأولى ليست سوى البداية. توثق هذه المراجعة أن الدماغ يواصل التعافي بنيويًا ووظيفيًا مع استمرار الامتناع؛ فتتعافى المادة الرمادية وتُصلح مسارات المادة البيضاء المتضررة التي تنسق الاتصال بين مناطق الدماغ على مدى أشهر.\n\nمقدمة الدماغ\nيكتسب التعافي أهمية خاصة في المناطق الأمامية المسؤولة عن الحكم والتخطيط وضبط النفس. ومع تحسنها تقوى القدرة على اتخاذ القرار والتحكم في الاندفاعات.\n\nإعادة تنظيم الدماغ ووظيفته\nإلى جانب الإصلاح الجسدي تتعافى وظائف الدماغ وروابطه أيضًا. يستطيع الدماغ إعادة تنظيم مساراته والتعلم من جديد، لذلك تمثل فترة الامتناع المستمر فرصة قوية للعلاج وبناء عادات جديدة.\n\nإشارة التعافي\nبحلول ستة أشهر تتحرك بنية الدماغ ووظيفته بوضوح نحو وضع أكثر صحة. والاستمرار بلا كحول يمنح هذا التعافي مزيدًا من الوقت ليتراكم.';

  @override
  String get alcoholReferenceDay365 =>
      'الكحول وخطر السرطان والتوقف عن الشرب\n\nالمصدر: المعهد الوطني للسرطان (NCI)، \"Alcohol and Cancer Risk\"\n\nالكحول يسبب السرطان\nيذكر NCI أن هناك إجماعًا علميًا قويًا على أن شرب الكحول يمكن أن يسبب السرطان. ويرتبط الكحول بسرطانات الفم والبلعوم والحنجرة والمريء والكبد والثدي والقولون والمستقيم. وكلما زادت الكمية وطالت مدة الشرب ارتفع الخطر.\n\nكيف يساهم الكحول في السرطان؟\nتشمل الآليات الأسيتالديهيد، وهو ناتج سام من استقلاب الكحول يضر بالحمض النووي، والإجهاد التأكسدي والالتهاب، وإضعاف امتصاص العناصر الغذائية الواقية، وارتفاع الإستروجين في حالة سرطان الثدي.\n\nينخفض الخطر بعد التوقف\nالمهم أن NCI يفيد بأن التوقف عن الشرب يرتبط بانخفاض الخطر مع مرور الوقت. وتظهر الدراسات أن الخطر المرتفع لسرطاني الفم والمريء ينخفض بعد التوقف، وإن كان الاقتراب من خطر شخص لم يشرب قط قد يستغرق سنوات. عام كامل بلا كحول خطوة مهمة في هذا المسار.\n\nفوائد متراكمة\nالوصول إلى عام يرسخ أيضًا مكاسب القلب والأوعية والكبد الناتجة عن الامتناع، مثل انخفاض ضغط الدم وتراجع خطر اضطراب النظم واستمرار تعافي الكبد، إلى جانب انخفاض خطر السرطان.';

  @override
  String get benzodiazepineReferenceDay7 =>
      'انسحاب البنزوديازيبين: الأسبوع الأول\n\nالمصدر: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings\"، منظمة الصحة العالمية (2009)، على NCBI Bookshelf\n\nالسلامة أولاً\nيمكن أن يسبب انسحاب البنزوديازيبين نوبات. وتوضح إرشادات منظمة الصحة العالمية أن الطريقة الأكثر أماناً هي خفض كمية البنزوديازيبين تدريجياً، مما يخفف أعراض الانسحاب ويساعد على الوقاية من النوبات. بعد الاستخدام المطول لا تتوقف فجأة — خفّض الجرعة تدريجياً مع مختص طبي.\n\nمتى يبدأ الانسحاب\nيعتمد توقيت منظمة الصحة العالمية على مدة مفعول الدواء:\n• قصير المفعول (oxazepam، alprazolam، temazepam): يبدأ عادةً بعد 1–2 يوم من آخر جرعة ويستمر 2–4 أسابيع أو أكثر\n• طويل المفعول (diazepam، nitrazepam): يبدأ عادةً بعد 2–7 أيام من آخر جرعة ويستمر 2–8 أسابيع أو أكثر\nيغطي الأسبوع الأول نافذة البدء المعتادة حتى للبنزوديازيبينات طويلة المفعول.\n\nالأعراض التي قد تظهر\nتذكر منظمة الصحة العالمية القلق والأرق والتململ والهياج أو التهيج وضعف التركيز أو الذاكرة وتوتر العضلات أو آلامها.\n\nالمراقبة\nقد تتذبذب شدة الانسحاب بشكل ملحوظ. وتوصي منظمة الصحة العالمية بمراقبة الأعراض والمضاعفات بانتظام؛ وفي بروتوكولها للأماكن المغلقة يتحدث العاملون الصحيون مع المريض كل 3–4 ساعات ويقدمون الطمأنة والتفسير عند الحاجة.';

  @override
  String get benzodiazepineReferenceDay14 =>
      'انسحاب البنزوديازيبينات: أسبوعان\n\nالمصدر: Poyares وآخرون، \"Chronic benzodiazepine usage and withdrawal in insomnia patients\"، Journal of Psychiatric Research ‏(2004)، على PubMed\n\nإشارة حقيقية للتعافي بعد نحو أسبوعين\nتابع الباحثون أشخاصًا يعانون من أرق مستمر وكانوا يتناولون البنزوديازيبينات كل ليلة لسنوات، ثم قاسوا نومهم مجددًا بعد 15 يومًا من الإيقاف التدريجي. تحسن نوم الموجات البطيئة، ونشاط دلتا في تخطيط النوم، وجودة النوم التي أبلغ عنها المشاركون مقارنة بالقياسات أثناء الاستخدام المزمن للبنزوديازيبينات.\n\nالنوم العميق يعود\nنوم الموجات البطيئة هو أعمق مراحل النوم غير المصحوب بحركة العين السريعة. بحلول اليوم 15 كان نوم الموجات البطيئة ونشاط دلتا أعلى، بينما انخفض نوم المرحلة الثانية غير المصحوب بحركة العين السريعة باتجاه النمط المرصود لدى الأصحاء.\n\nتعافٍ مبكر تم قياسه\nساء النوم مباشرة بعد الإيقاف لدى المشاركين الذين أكملوا الانسحاب، ثم تحسنت المقاييس الموضوعية للنوم العميق وجودة النوم المبلغ عنها بحلول متابعة اليوم 15. وهذا يجعل علامة الأسبوعين محطة تعافٍ حقيقية ومقاسة.';

  @override
  String get benzodiazepineReferenceDay60 =>
      'البنزوديازيبينات: الوظائف النهارية بعد ثمانية أسابيع\n\nالمصدر: Tsunoda وآخرون، \"Effects of discontinuing benzodiazepine-derivative hypnotics on postural sway and cognitive functions in the elderly\"، International Journal of Geriatric Psychiatry (2010)، على PubMed\n\nإشارة تعافٍ مقاسة بعد ثمانية أسابيع\nتابع الباحثون بالغين بعمر 60 عامًا فأكثر يعيشون في دار رعاية وكانوا يستخدمون منومات البنزوديازيبين. خُفِّضت جرعتهم تدريجيًا حتى التوقف خلال ثلاثة أسابيع، ثم أُعيدت اختبارات الإدراك والتوازن عند نهاية الأسبوع الثامن.\n\nتحسن التركيز والذاكرة\nمن بين 26 شخصًا أكملوا الدراسة، تحسنت بدرجة ملحوظة درجات الذاكرة الفورية والانتباه واللغة. هذه مكاسب ملموسة في الأداء النهاري بعد التوقف عن البنزوديازيبين.\n\nثبات أفضل على القدمين\nتحسنت أيضًا مقاييس تمايل الجسم مع إغلاق العينين. وخلص الباحثون إلى أن إيقاف منومات البنزوديازيبين ارتبط بتحسن ثبات الجسم وتعافي الوظائف المعرفية النهارية لدى هذه المجموعة الأكبر سنًا.\n\nالنوم بقي مستقرًا\nلم يبلغ من أكملوا الدراسة عن تدهور ذاتي في النوم في استبيان النوم المستخدم. عند نهاية الأسبوع الثامن، سجلت الدراسة مكاسب نهارية قابلة للقياس دون تراجع مُبلغ عنه في جودة النوم.';

  @override
  String get benzodiazepineReferenceDay90 =>
      'بعد ثلاثة أشهر من البنزوديازيبينات: تفكير أسرع وخمول أقل\n\nالمصدر: Rickels et al., \"Psychomotor performance of long-term benzodiazepine users before, during, and after benzodiazepine discontinuation,\" Journal of Clinical Psychopharmacology (1999), على PubMed\n\nإشارة تعافٍ مقاسة بعد 12 أسبوعًا\nاختبر الباحثون مستخدمي البنزوديازيبينات لفترات طويلة قبل الفطام ثم بعد 5 و12 أسبوعًا منه. توفرت بيانات 12 أسبوعًا لـ77 شخصًا، وتم تأكيد خلوّ الناجحين في الفطام من البنزوديازيبينات بفحوص دم أسبوعية.\n\nأداء معرفي أسرع\nأنجز الأشخاص الذين نجحوا في الفطام من البنزوديازيبينات مهام نسخ الرموز واستبدال الأرقام بالرموز أسرع من المشاركين الذين ظلوا يتناولون البنزوديازيبينات. وظل الفرق ذا دلالة بعد أخذ العمر والتعليم والدرجات الأساسية في الحسبان.\n\nخمول ذهني وجسدي أقل\nأبلغ الناجحون في الفطام أيضًا عن خمول ذهني وجسدي أقل من الأشخاص الذين واصلوا تناول البنزوديازيبينات.\n\nكيف يمكن أن تبدو الأشهر الثلاثة\nبالنسبة إلى الناجحين في الفطام في هذه الدراسة، ارتبط مرور 12 أسبوعًا بعد الفطام بتحسن قابل للقياس في سرعة المعالجة وبانخفاض الخمول الذهني والجسدي. صار التفكير أسرع وخفّ الإحساس بالتثبيط.';

  @override
  String get benzodiazepineReferenceDay180 =>
      'التفكير والذاكرة في ستة أشهر: مكاسب قابلة للقياس\n\nالمصدر: تاتا وآخرون، \"الافتقار إلى التعافي المعرفي بعد الانسحاب من استخدام البنزوديازيبين على المدى الطويل\"، الطب النفسي (1994)، في PubMed\n\nما فعلته الدراسة\nاختبرت هذه الدراسة 21 مريضًا بالبنزوديازيبين على المدى الطويل قبل الانسحاب، وبعد الانسحاب مباشرة، ومرة أخرى بعد ستة أشهر من الامتناع عن البنزوديازيبينات، ومقارنتهم بالضوابط المتطابقة. إنها واحدة من أكثر نقاط البيانات صراحةً في أدبيات استرداد البنزو.\n\nما وجدته\nقبل التوقف، كان المرضى يعانون من مشاكل في التعلم اللفظي والذاكرة وسرعة الحركة والتنسيق البصري والتفكير البصري. مباشرة بعد التوقف كان هناك تغيير طفيف. وبعد ستة أشهر، تحسنت العديد من هذه المجالات بشكل ملحوظ.\n\nماذا يعني هذا\nوبعد ستة أشهر، كان التعلم اللفظي والذاكرة وسرعة الحركة والتنسيق البصري يتعافى بشكل ملحوظ. كان التحسن واضحًا بالفعل وكان لديه مجال للاستمرار.\n\nالصورة الأكبر\nإذا شعرت بالضبابية في الشهر السادس، فإن هذا البحث يقول: هذا أمر متوقع، واستمرار الامتناع عن البنزوديازيبينات هو الطريق إلى الأمام. تظهر الدراسات طويلة المدى أن التعافي يستمر إلى ما بعد هذه النقطة، حيث يستمر الدماغ في التعافي.';

  @override
  String get benzodiazepineReferenceDay365 =>
      'سنة واحدة بعد تناول البنزوديازيبينات: يستمر التفكير والذاكرة في التعافي\n\nالمصدر: باركر وآخرون، \"استمرار التأثيرات المعرفية بعد الانسحاب من استخدام البنزوديازيبين على المدى الطويل: التحليل التلوي\"، أرشيف علم النفس العصبي السريري (2004)، في PubMed\n\nأقوى الأدلة لدينا\nقام الباحثون بدمج الدراسات التي أعادت اختبار مستخدمي البنزوديازيبين على المدى الطويل بعد ستة أشهر على الأقل من التوقف عن تناول الدواء. تظهر النتيجة المجمعة انتعاشًا واضحًا في التفكير والذاكرة بعد الانسحاب.\n\nالأخبار الجيدة\nوجدت الدراسات المجمعة تحسنًا حقيقيًا وقابلاً للقياس في العديد من مجالات التفكير والذاكرة بعد الانسحاب. حوالي عام واحد، يكون التعافي واسع النطاق وواضحًا مقارنة بالاستخدام النشط.\n\nيستمر التعافي\nوجدت الدراسات المشتركة انتعاشًا واسعًا في التفكير والذاكرة. بحلول عام واحد، تكون قد قطعت شوطا طويلا في اتجاه التعافي الذي كان يمكن قياسه بالفعل خلال ستة أشهر.\n\nماذا يعني هذا في سنة واحدة\nتوقع انتعاشًا كبيرًا في التفكير والذاكرة والوضوح لمدة عام، حيث يشعر معظم الأشخاص بأنهم أكثر وضوحًا بشكل ملحوظ مما كانوا عليه أثناء الاستخدام. ولكن إذا كانت بعض المناطق لا تزال متخلفة، فهذا يتوافق مع الأدلة، وليس علامة على المماطلة. ويستمر التعافي، ويعد عام من الامتناع عن البنزوديازيبينات علامة بارزة وجديرة بالاهتمام على هذا الطريق.';

  @override
  String get benzodiazepineReferenceDay540 =>
      '18 شهرًا بعد تناول البنزوديازيبينات: تعافي بطيء ولكنه حقيقي\n\nالمصدر: أشتون، \"متلازمات الانسحاب المطولة من البنزوديازيبينات،\" مجلة علاج تعاطي المخدرات (1991)، على PubMed\n\nلماذا يستغرق تعافي بنزو وقتًا طويلاً؟\nتعمل البنزوديازيبينات على GABA، وهو نظام التهدئة الرئيسي في الدماغ. يؤدي الاستخدام طويل الأمد إلى تغيير مدى قوة استجابة هذا النظام، وقد تستغرق هذه التغييرات أشهرًا حتى يتم عكسها. ولهذا السبب يتم قياس تعافي البنزو بالأشهر وليس بالأسابيع.\n\nحيث يجلس 18 شهرا\nتصف أشتون أعراض الانسحاب طويلة الأمد والتي يمكن أن تستغرق شهورًا حتى تهدأ. وبحلول 18 شهرًا، يكون الأسوأ قد تجاوز معظم الأشخاص، ويستقر القلق المستمر والتغيرات الحسية وضباب الدماغ بشكل كبير.\n\nعكسها ببطء\nوالأهم من ذلك، أن أشتون تؤطر التغييرات الأساسية على أنها \"تغيرات وظيفية يمكن عكسها ببطء في الجهاز العصبي المركزي\". بطيء، ولكن قابل للعكس – يعكس الجدول الزمني الطويل عمق التكيف الذي تسببه البنزوديازيبينات، وليس الضرر الدائم لدى معظم الناس.\n\nإشارة إلى التعافي\nتصف أشتون التغييرات الأساسية بأنها قابلة للعكس ببطء. بحلول 18 شهرًا، يكون لدى نظام GABA المهدئ في الدماغ وقتًا طويلًا للاستقرار ويكون الاتجاه السائد هو استمرار التعافي نحو الوضع الطبيعي.';

  @override
  String get benzodiazepineReferenceDay730 =>
      'بعد عامين من تناول البنزوديازيبينات: تقدم كبير ودائم\n\nالمصدر: باركر وآخرون، \"استمرار التأثيرات المعرفية بعد الانسحاب من استخدام البنزوديازيبين على المدى الطويل: التحليل التلوي\"، أرشيف علم النفس العصبي السريري (2004)، في PubMed\n\nعلامة فارقة في التعافي\nعامين هو علامة فارقة كبيرة، وخاصة بعد انسحاب طويل. لقد مرت مراحل الأعراض المبكرة والمستمرة منذ فترة طويلة، وما زال أمام المكاسب التي تحققت من السنة الأولى سنة أخرى لتعزيزها.\n\nما تدعمه الأدلة\nتظهر الدراسات المجمعة التعافي في العديد من المناطق بعد الانسحاب. بحلول عامين، يبلغ معظم الأشخاص عن قلقهم عند مستوى ما قبل البنزو أو أقل منه، والنوم الموثوق بدون دواء، والعواطف الأكثر ثباتًا، والتفكير الأكثر وضوحًا مقارنة بالاستخدام.\n\nإشارة إلى التعافي\nتثبت الدراسات المجمعة التعافي في العديد من مجالات التفكير والذاكرة. وبعد مرور عامين، يعد التعافي المستدام هو التوقع المدعوم بالأدلة.\n\nحفظ المنظور\nعامين يمنحان النوم والمزاج والذاكرة والتفكير الواضح نافذة طويلة للتعافي. تظهر الأدلة تحسنًا كبيرًا في جميع الحالات الأربعة، مع استمرار الشفاء من هنا.';

  @override
  String get benzodiazepineReferenceDay1095 =>
      'ثلاث سنوات بعد البنزوديازيبينات: الشفاء على المدى الطويل\n\nالمصدر: باركر وآخرون، \"استمرار التأثيرات المعرفية بعد الانسحاب من استخدام البنزوديازيبين على المدى الطويل: التحليل التلوي\"، أرشيف علم النفس العصبي السريري (2004)، في PubMed\n\nالمنظر الطويل\nتقع ثلاث سنوات في أقصى نهاية الجدول الزمني لاسترداد البنزو. بالنسبة للغالبية العظمى من الناس، حتى بعد الانسحاب الشديد طويل الأمد، تكون الأعراض التخريبية قد تخلفت كثيرًا وتتغير نوعية الحياة مقارنة بالاستخدام النشط.\n\nما وجده التحليل التلوي\nتظهر الدراسات المجمعة للمستخدمين على المدى الطويل التعافي في العديد من المناطق بعد الانسحاب. على مدى سنوات من الامتناع عن البنزوديازيبينات، كانت القصة السائدة هي التعافي الواسع النطاق في التفكير والذاكرة والوظيفة اليومية.\n\nإشارة إلى التعافي\nتُظهر الأبحاث طويلة المدى التعافي في العديد من مجالات التفكير والذاكرة. بحلول ثلاث سنوات، تكون مراحل الانسحاب المبكرة والمستمرة قد تأخرت كثيرًا عن تلك المكاسب، وقد تحتاج هذه المكاسب إلى سنوات لتعزيزها.\n\nرسالة أمل\nتعد رحلة تعافي البنزو واحدة من أكثر الرحلات تطلبًا في مجال الطب، وتعد ثلاث سنوات من الشفاء المستمر إنجازًا عميقًا. والدليل واضح: يتعافى الدماغ بشكل كبير، ويستعيد معظم الناس وضوحهم ونومهم ونطاقهم العاطفي، ويستمر التحسن مع مرور الوقت.';

  @override
  String get benzodiazepineReferenceDay1460 =>
      'أربع سنوات بعد البنزوديازيبينات: تقدم مستدام\n\nالمصدر: الدليل السريري المشترك لتقليل البنزوديازيبينات، بقيادة ASAM وبمشاركة تخصصات متعددة (2025)\n\nما الذي يدعمه الدليل\nيشير الدليل إلى أن التكيف بعد إيقاف البنزوديازيبينات قد يستمر مدة أطول بكثير من بقاء الدواء في الجسم. وقد يعاني بعض الأشخاص أعراض انسحاب ممتدة لأشهر أو سنوات، لذلك ينبغي متابعة التعافي ودعمه بصورة فردية.\n\nماذا تعني أربع سنوات\nلا يحدد الدليل نقطة بيولوجية عالمية عند أربع سنوات. لذلك تحتفي هذه المحطة بما يمكن دعمه دون مبالغة: أربع سنوات من التغيير المستمر، مع السماح للتعافي بأن يسير وفق وتيرته الخاصة.\n\nمحطة تستحق الاحتفال\nأربع سنوات تساوي 1,460 يومًا. إنه إنجاز راسخ سواء كان مسار التعافي سلسًا أو متقلبًا أو بينهما.';

  @override
  String get benzodiazepineReferenceDay1825 =>
      'خمس سنوات بعد البنزوديازيبينات: إنجاز طويل الأمد\n\nالمصدر: الدليل السريري المشترك لتقليل البنزوديازيبينات، بقيادة ASAM وبمشاركة تخصصات متعددة (2025)\n\nلا يوجد خط نهاية واحد\nيؤكد الدليل أن الانسحاب من البنزوديازيبينات والتكيف بعد إيقافها يختلفان بين الأشخاص. ولا يحدد نقطة عالمية عند خمس سنوات يُعلن فيها أن الدماغ أو الجسم تعافى بالكامل.\n\nماذا تمثل خمس سنوات\nخمس سنوات ذكرى حقيقية طويلة الأمد: تغيير مستمر على مدى 1,825 يومًا، مع سنوات من ترسخ العادات والدعم والحياة اليومية الجديدة.\n\nالفضل للعمل الذي أنجزته\nتحتفي هذه المحطة بالعمل نفسه، لا بموعد طبي مختلق. خمس سنوات من التقدم المستمر إنجاز كبير بحد ذاته.';

  @override
  String get cocaineReferenceDay1 =>
      'انسحاب الكوكايين: أول 24 ساعة\n\nالمصدر: \"Withdrawal Syndromes\"، StatPearls (NCBI Bookshelf)، المكتبة الوطنية الأمريكية للطب\n\nالكوكايين والدماغ\nيمنع الكوكايين إعادة امتصاص الدوبامين وغيره من النواقل الأحادية الأمين في دوائر المكافأة بالدماغ، فيتراكم الدوبامين وينتج عنه شعور قوي بالنشوة والطاقة. ومع الاستخدام المنتظم يتكيف الدماغ بخفض نشاط هذا النظام، لذلك قد تبدو الأنشطة العادية أقل إشباعًا في غياب المخدر.\n\nمرحلة الانهيار\nتصف StatPearls بداية انسحاب المنشطات بمرحلة \"انهيار\" بعد توقف الاستخدام، تتسم باكتئاب واضح وكثرة النوم والجوع وانخفاض المزاج وبطء شديد في الحركة والتفكير. وخلال أول 24 ساعة يشمل ذلك عادة:\n• إرهاقًا شديدًا وحاجة أكبر إلى النوم\n• مزاجًا مكتئبًا وبطئًا في الحركة والتفكير\n• زيادة الشهية، لأن الكوكايين يثبط الشهية\n\nكما تُذكر الرغبة الشديدة في تعاطي الكوكايين والتهيّج والقلق كثيرًا في أدبيات الإدمان خلال هذه الفترة، رغم أن StatPearls لا تعددها تحديدًا ضمن مرحلة الانهيار.\n\nبخلاف بعض المواد الأخرى\nتشير StatPearls إلى أن انسحاب المنشطات يُعالج بالملاحظة والرعاية الداعمة. وعلى خلاف انسحاب الكحول أو البنزوديازيبينات، فإنه لا يسبب عادة نوبات صرع أو هذيانًا. ويكمن الخطر الرئيسي في الجانب النفسي؛ فقد يحدث الاكتئاب، وقد تظهر أفكار انتحارية لدى من يستخدمون بكثرة خلال مرحلة الانهيار، لذلك يُنصح بالدعم والمتابعة.\n\nلا دواء معتمدًا\nلا توجد حاليًا أدوية معتمدة لعلاج انسحاب الكوكايين. ويعتمد التدبير على الرعاية الداعمة، بينما تُعد الأساليب غير الدوائية مثل إدارة الحوافز من العلاجات القائمة على الأدلة لاضطراب التعاطي الأساسي.';

  @override
  String get cocaineReferenceDay3 =>
      'ثلاثة أيام من دون كوكايين: ذروة التحدي\n\nالمصدر: \"Cocaine Toxicity\"، StatPearls (NCBI Bookshelf)، المكتبة الوطنية الأمريكية للطب\n\nكيف يؤثر الكوكايين في الجسم\nتوثق StatPearls أن الكوكايين يمنع إعادة امتصاص الدوبامين والنورإبينفرين والسيروتونين، ما يطيل التنبيه الودي. وهذا يفسر النشوة التي يسببها كما يفسر خطورته، إذ يمكن أن يؤثر في معظم أجهزة الجسم.\n\nالأيام 2–4: ذروة الانسحاب النفسي\nبحلول اليوم الثالث تكون مرحلة الانهيار الحادة قد أفسحت المجال عادة لأشد فترة من الانسحاب النفسي:\n• انخفاض المزاج والاكتئاب في أشدهما\n• فقدان المتعة\n• رغبة شديدة في التعاطي تثيرها المحفزات\n• القلق والتململ\n• اضطراب النوم، مع فرط النوم لدى بعض الأشخاص والأرق لدى آخرين\n\nيتراجع الخطر القلبي الوعائي\nتصف StatPearls السمية القلبية الوعائية بأنها أخطر آثار الكوكايين: ارتفاع معدل ضربات القلب وضغط الدم وزيادة حاجة عضلة القلب إلى الأكسجين وتشنج الشرايين التاجية وتنشيط الصفائح الدموية، وهي عوامل تزيد خطر اضطراب النظم واحتشاء القلب والسكتة الدماغية حتى لدى الشباب. نصف عمر الكوكايين نفسه قصير، نحو ساعة، وبحلول اليوم الثالث يكون المخدر نفسه قد خرج من الجسم. لكن StatPearls تشير إلى أن مستقلباته قد تواصل تضييق الأوعية لساعات بعد الاستخدام، وقد يبقى أحد المستقلبات لأسابيع، لذلك قد يستمر بعض الإجهاد القلبي الوعائي بعد زوال الكوكايين نفسه.\n\nالطريق إلى الأمام\nالمرحلة الحادة شديدة، لكن الأعراض النفسية، مثل الاكتئاب والرغبة الشديدة وفقدان المتعة، هي التي تحتاج عادة إلى أكبر قدر من الدعم وقد تستمر لأطول مدة.';

  @override
  String get cocaineReferenceDay7 =>
      'أسبوع واحد من دون كوكايين: بدء التعافي الجسدي\n\nالمصدر: \"Withdrawal Syndromes\"، StatPearls (NCBI Bookshelf)، المكتبة الوطنية الأمريكية للطب\n\nالمرحلة الحادة تقترب من نهايتها\nتصف StatPearls انتقال انسحاب الكوكايين من مرحلة الانهيار الأولى إلى مرحلة تعافٍ أطول. وبحلول نهاية الأسبوع الأول تبدأ أسوأ الأعراض عادة في الانحسار بينما يواصل نظام الدوبامين التعافي.\n\nالتعافي الجسدي جارٍ\nبعد توقف التنبيه الودي الذي يسببه الكوكايين، تبدأ تأثيراته في القلب والأوعية الدموية والشهية والنوم والمجاري الهوائية في التراجع خلال الأيام والأسابيع التالية:\n• يتجه معدل ضربات القلب وضغط الدم نحو الطبيعي\n• تعود الشهية تدريجيًا، إذ إن الكوكايين يثبطها بشدة\n• تبدأ أنماط النوم في الاستقرار\n• تبدأ الممرات الأنفية في الالتئام إذا كان الكوكايين يُستنشق عبر الأنف\n\nقد تستمر الأعراض النفسية\nتشير StatPearls إلى أن الاكتئاب وفقدان المتعة من سمات انسحاب المنشطات وقد يستمران بعد زوال الأعراض الجسدية:\n• يبقى المزاج منخفضًا، لكنه يكون عادة أقل شدة من فترة الذروة\n• تظل الرغبة التي تثيرها المحفزات قوية\n• يظل التركيز والدافع متأثرين\n\nمرحلة ما بعد الانسحاب الحاد\nبعد ذلك ينتقل التعافي إلى أسابيع أو أشهر من التحسن الأبطأ والأكثر ثباتًا في المزاج والرغبة والتفكير الواضح. ومعرفة هذا النمط تساعد على فهم الجزء الأبطأ من التعافي.';

  @override
  String get cocaineReferenceDay14 =>
      'أسبوعان من دون كوكايين: استعادة الاستقرار\n\nالمصدر: \"Withdrawal Syndromes\"، StatPearls (NCBI Bookshelf)، المكتبة الوطنية الأمريكية للطب\n\nبعد أسبوعين\nبحلول أسبوعين تكون أعراض الانهيار الشديدة، مثل الاكتئاب العميق وكثرة النوم وبطء الحركة والتفكير، قد خفت عادة بدرجة كبيرة. وينصب التعافي الآن بدرجة أكبر على استعادة صحة الدماغ والصحة العاطفية.\n\nالمزاج والحالة العاطفية\nقد يظل المزاج دون مستواه المعتاد بعد أسبوعين بينما يتعافى نظام الدوبامين. ومقارنة بالأسبوع الأول، يبدأ فقدان المتعة الشديد في التراجع وتعود لحظات حقيقية من الشعور بالراحة.\n\nالرغبة والمحفزات\nتمثل الرغبة التي تثيرها المحفزات تحديًا مهمًا في هذه المرحلة. فقد كوّن الدماغ ارتباطات قوية بين تعاطي الكوكايين وبيئات وأشخاص ومشاعر وأنشطة محددة. وقد يؤدي التعرض لأي من هذه المحفزات إلى رغبة شديدة حتى مع تحسن المزاج العام. لذلك يفيد تجنب البيئات عالية الخطورة وبناء ارتباطات جديدة.\n\nتحسن النوم\nيكون النوم عادة أكثر استقرارًا وتجددًا بعد أسبوعين مما كان عليه خلال مرحلة الانسحاب الحاد. ويساعد تحسن النوم في المزاج والتفكير الواضح والقدرة على التعامل مع الرغبة.\n\nبناء الأساس\nلأن العلاجات القائمة على الأدلة لاضطراب استخدام المنشطات سلوكية، ومنها إدارة الحوافز والعلاج ودعم الأقران، فإن علامة الأسبوعين وقت مهم للانخراط في هياكل الدعم التي تدعم التعافي طويل الأمد.';

  @override
  String get cocaineReferenceDay60 =>
      'شهران من دون كوكايين: بدء تعافي المزاج ونظام المكافأة\n\nالمصدر: \"Recovering from Cocaine: Insights from Clinical and Preclinical Investigations\"، Neuroscience & Biobehavioral Reviews (2013)، على PubMed Central\n\nما الذي يحدث في الدماغ\nيجمع هذا الاستعراض دراسات بشرية وحيوانية عن التغيرات التي تحدث في الدماغ بعد توقف استخدام الكوكايين. يغير الاستخدام المزمن للكوكايين نظام الدوبامين ويخفض النشاط في القشرة الجبهية، ويشكل تعافي هذه الأنظمة أساسًا للتحسن في المزاج والدافع الذي يلاحظه الناس في المراحل المبكرة من الامتناع.\n\nتقدم نظام المكافأة\nفي الدراسات الحيوانية، تحركت التغيرات المرتبطة بالكوكايين في مستقبلات الدوبامين وبروتينات إعادة التدوير نحو مستويات أقرب إلى الطبيعي مع استمرار الامتناع. ومع تعافي نظام المكافأة يتراجع فقدان المتعة الشديد وتعود المكافآت اليومية، مثل الطعام والتواصل والإنجاز، إلى الشعور بأنها مُرضية.\n\nإشارة التعافي\nبعد شهرين يتحسن المزاج ويصبح النوم أكثر استقرارًا بينما يواصل نظام الدوبامين والقشرة الجبهية التعافي. وتُظهر دراسات على الرئيسيات أن التغيرات المرتبطة بالكوكايين في مستقبلات D1 والناقلات تتحرك نحو مستويات المجموعة الضابطة مع استمرار الامتناع.';

  @override
  String get cocaineReferenceDay90 =>
      'ثلاثة أشهر من دون كوكايين: تعافي مؤشرات الدوبامين\n\nالمصدر: \"Recovering from Cocaine: Insights from Clinical and Preclinical Investigations\"، Neuroscience & Biobehavioral Reviews (2013)، على PubMed Central\n\nلماذا تمثل 90 يومًا علامة مهمة\nيسلط الاستعراض الضوء على نقطة الثلاثة أشهر بوصفها ذات دلالة بيولوجية. ففي الرئيسيات غير البشرية، أظهرت مستقبلات الدوبامين D1 والناقلات التي زادها الكوكايين دلائل على عودة نحو مستويات المجموعة الضابطة بعد نحو 90 يومًا من الامتناع. وهذا دليل مباشر على أن نظام المكافأة يمكنه إعادة التكيف بعد توقف المخدر.\n\nالجزء الأمامي من الدماغ\nيشدد المؤلفون على تعافي الجزء الأمامي من الدماغ بوصفه من أهم علامات الامتناع الممتد. يدعم هذا الجزء التحكم في الاندفاع واتخاذ القرار وضبط النفس، وتتحسن هذه القدرات مع تعافيه.\n\nما الذي تُظهره 90 يومًا\nبعد 90 يومًا، وجدت دراسات الرئيسيات أن كثافات مستقبلات D1 وD2 وناقلات الدوبامين لم تعد تختلف بصورة ملحوظة عن المجموعة الضابطة غير المعرضة للمخدر. وحتى بعد التعرض الطويل، يظهر قدر كبير من تعافي نظام الدوبامين بحلول هذه النقطة ويستمر مع الامتناع.';

  @override
  String get cocaineReferenceDay180 =>
      'ستة أشهر من دون كوكايين: تفكير أوضح\n\nالمصدر: \"Structural and Functional Brain Recovery in Individuals with Substance Use Disorders During Abstinence: A Review of Longitudinal Neuroimaging Studies\"، على PubMed Central\n\nتعافٍ يمكن رؤيته بالتصوير\nيجمع هذا الاستعراض دراسات تصوير دماغ طولية تفحص الأشخاص أنفسهم مرارًا مع زيادة مدة امتناعهم. وبالنسبة إلى الكوكايين، يفيد بأن النشاط الوظيفي يتعافى بصورة قابلة للقياس مع استمرار الامتناع.\n\nأدلة تصوير الدماغ\nتابعت دراستان بالرنين المغناطيسي الوظيفي مستخدمي الكوكايين عبر الزمن، ووجدتا تحسنًا في تنشيط الدماغ المتوسط والمهاد مع زيادة مدة الامتناع. وفي إحداهما كان نمط تنشيط الدماغ بعد نحو ستة أشهر من الامتناع مشابهًا لنمط مجموعة ضابطة من أشخاص أصحاء غير مدمنين. وعبر مواد مختلفة، يشير الاستعراض إلى أن نتائج التصوير النووي تدعم وجود تعافٍ دوباميني مع الامتناع.\n\nما معنى ذلك بعد ستة أشهر\nتتوافق هذه المكاسب الوظيفية مع التحسينات التي يبلغ عنها الناس في الحياة اليومية في هذه المرحلة:\n• انتباه وذاكرة عاملة أفضل\n• اتخاذ قرار أدق وتحكم أفضل في الاندفاع\n• مزاج أكثر استقرارًا وتنظيم أفضل للمشاعر\n\nإشارة التعافي\nبعد نحو ستة أشهر، أظهرت إحدى مجموعات المتابعة الطولية بالرنين المغناطيسي الوظيفي نمط تنشيط مشابهًا لمجموعة ضابطة من أشخاص أصحاء غير مدمنين، بينما تحسن تنشيط الدماغ المتوسط والمناطق العميقة مع طول مدة الامتناع. وهذا تعافٍ وظيفي للدماغ ظهر مباشرة في التصوير.';

  @override
  String get cocaineReferenceDay365 =>
      'عام واحد من دون كوكايين: زوال الإجهاد القلبي الوعائي المتكرر\n\nالمصدر: \"Cocaine Toxicity\"، StatPearls (NCBI Bookshelf)، المكتبة الوطنية الأمريكية للطب\n\nلماذا يحتل القلب موقعًا محوريًا\nتحدد StatPearls السمية القلبية الوعائية بوصفها أخطر آثار الكوكايين. فكل استخدام يرفع معدل ضربات القلب وضغط الدم وطلب عضلة القلب على الأكسجين، ويسبب تشنج الشرايين التاجية ويعزز تكوّن الجلطات. ويزيد هذا المزيج خطر النوبة القلبية واضطراب النظم والسكتة الدماغية حتى لدى الشباب.\n\nما الذي يزيله عام من الامتناع\nكل يوم من دون كوكايين هو يوم من دون هذه الأضرار الحادة. وعلى امتداد عام، تختفي الارتفاعات المتكررة في ضغط الدم ومعدل ضربات القلب الناتجة عن الاستخدام، ويزول خطر التشنج التاجي والاحتشاء الحاد الناتجين عن جرعات جديدة، ولا يعود القلب يُدفع مرارًا إلى عدم التوازن بين حاجته إلى الأكسجين وما يصله منه.\n\nإشارة التعافي\nيوقف التوقف عن الكوكايين التشنج التاجي المتكرر وتسارع القلب وارتفاع ضغط الدم وتعزيز التخثر وعدم توازن الأكسجين التي تقود إلى أذية قلبية حادة. وقد يبقى التليف أو التهاب عضلة القلب الموجود سابقًا مشكلة طبية، لكن الأذى المتكرر الذي يسببه الكوكايين يتوقف.\n\nتعافي الدماغ أيضًا\nبعد عام، تكون أنظمة المكافأة وضبط النفس قد حصلت على وقت ممتد للتعافي، ما يدعم تحكمًا أفضل في الاندفاع ومزاجًا أكثر استقرارًا واستجابة أقوى للمكافآت اليومية.';

  @override
  String get cocaineReferenceDay730 =>
      'عامان من دون كوكايين: تعافٍ مستمر\n\nالمصدر: \"Recovering from Cocaine: Insights from Clinical and Preclinical Investigations\"، Neuroscience & Biobehavioral Reviews (2013)، على PubMed Central\n\nنظرة بعيدة المدى\nيجمع هذا الاستعراض ما توصلت إليه الدراسات البشرية والحيوانية بشأن الامتناع المطول عن الكوكايين. وتتمثل خلاصته الأساسية في أن الحفاظ على وظيفة القشرة الجبهية وتعافيها من أهم مؤشرات الامتناع طويل الأمد؛ فقد أظهر الأشخاص الممتنعون لمدة طويلة (أكثر من 10 أشهر) نشاطًا أكبر في القشرة الجبهية مقارنة بمن كانت مدة امتناعهم أقصر.\n\nما الذي يواصل التعافي\n• تستمر مؤشرات الدوبامين التي غيّرها الكوكايين في الاقتراب من المستويات الطبيعية مع استمرار الامتناع\n• قد يتحسن الانخفاض في سلامة المادة الرمادية والبيضاء الذي لوحظ لدى المستخدمين النشطين ومن هم في بدايات الامتناع مع فترات امتناع أطول، وربما يرتبط ذلك باستمرار نضج الميالين\n• تتقوى دوائر التحكم الجبهية، بما يشمل التحكم في الاندفاع والحكم وتنظيم المشاعر\n\nإشارة التعافي\nيشير المؤلفون إلى تحفظ علمي مهم: قد تعكس بعض الفروق لدى الممتنعين لفترات طويلة \"تأثير الناجين\"؛ أي إن الأشخاص الذين كانت سلامة أدمغتهم أفضل في البداية ربما يكون من الأسهل عليهم الحفاظ على الامتناع، وليس أن تكون كل الفروق ناتجة عن التعافي وحده. الواضح أن عامين من دون كوكايين يدعمان دماغًا يعمل بصورة أقرب بكثير إلى دماغ غير المستخدم، وحياة لم تعد مجرد امتناع بل أعيد بناؤها بدرجة كبيرة.';

  @override
  String get cocaineReferenceDay1095 =>
      'ثلاث سنوات بلا كوكايين: أساس أقوى\n\nالمصدر: SAMHSA، Treatment of Stimulant Use Disorders\n\nيتناول دليل SAMHSA المبني على الأدلة الكوكايين صراحةً ويركز على ممارسات تدعم التعافي طويل الأمد. ولا يحدد موعداً بيولوجياً عاماً عند ثلاث سنوات.\n\nثلاث سنوات إنجاز ثابت بحد ذاته. حافظ على العادات والدعم والاستراتيجيات التي تجعل التعافي مستداماً.';

  @override
  String get cocaineReferenceDay1460 =>
      'أربع سنوات بلا كوكايين: زخم مستمر\n\nالمصدر: SAMHSA، Treatment of Stimulant Use Disorders\n\nتصف SAMHSA أساليب مبنية على الأدلة لاضطرابات استخدام المنشطات، ومنها الكوكايين، وتركز على دعم التعافي طويل الأمد. ولا تحدد نهاية طبية عامة عند أربع سنوات.\n\nأربع سنوات تظهر تغييراً استمر في الأيام العادية والفترات الصعبة والمحطات المهمة.';

  @override
  String get cocaineReferenceDay1825 =>
      'خمس سنوات بلا كوكايين: تغيير راسخ\n\nالمصدر: SAMHSA، Treatment of Stimulant Use Disorders\n\nيدعم دليل SAMHSA رعاية مبنية على الأدلة تهدف إلى التعافي طويل الأمد من اضطرابات استخدام المنشطات، ومنها الكوكايين. ولا يقدم خمس سنوات كخط نهاية بيولوجي.\n\nخمس سنوات تعني نصف عقد من التغيير المستمر. هذا الثبات والحياة التي بُنيت حوله هما المحطة الحقيقية.';

  @override
  String get ghbReferenceDay1 =>
      'انسحاب GHB: الساعات الأولى\n\nالمصدر: “Characterization of the GHB Withdrawal Syndrome”، PubMed Central\n\n⚠ هذه حالة طبية طارئة\nيُعد انسحاب GHB من أخطر أنواع انسحاب المواد، وقد يضاهي في شدته انسحاب الكحول أو البنزوديازيبينات الشديد. من دون علاج قد يتطور إلى هذيان في أكثر من نصف الحالات، مع تقلبات خطيرة في معدل ضربات القلب وضغط الدم ونوبات تشنج. ينبغي لمن يعتمد على GHB أو GBL أو 1,4-butanediol أن يطلب إزالة سموم داخل المستشفى تحت الإشراف بدلًا من التوقف بمفرده.\n\nلماذا يبدأ بهذه السرعة\nلا يتجاوز عمر النصف لـ GHB نحو 30–60 دقيقة، وغالبًا ما يحتاج الشخص المعتمد عليه إلى إعادة الجرعة كل 2–3 ساعات فقط لتجنب الانسحاب، أي بوتيرة أسرع بكثير من الكحول أو البنزوديازيبينات. تفسر هذه الحرائك الدوائية السريعة ظهور الأعراض أبكر بكثير من انسحاب المهدئات والمنومات الأخرى.\n\nالأعراض المبكرة\nالقلق، الأرق، الرعشة، التعرق، تسارع ضربات القلب وارتفاع ضغط الدم.';

  @override
  String get ghbReferenceDay3 =>
      'انسحاب GHB: أصعب الأيام\n\nالمصدر: “Characterization of the GHB Withdrawal Syndrome”، PubMed Central\n\nأصعب فترة\nوجدت الدراسة أن عدة أعراض أساسية للانسحاب — آلام العضلات، ونفضات العضلات، والشعور بالتوتر والإجهاد، وتسارع ضربات القلب، وتقلصات البطن — بلغت أشدها خلال الأيام الثلاثة الأولى، وانخفضت شدة كثير من الأعراض بأكثر من 70٪ بحلول اليوم الرابع. تمثل هذه الفترة المبكرة عادةً أعلى درجات الخطر، إذ يكون الانسحاب غير المعالج أكثر قابلية للتفاقم إلى هذيان أو نوبات أو تقلبات خطيرة في معدل ضربات القلب وضغط الدم.\n\nأعراض شديدة\n• هياج وقلق شديدان\n• هلوسات سمعية وبصرية وارتياب\n• رعشة وتعرق وتسارع القلب وارتفاع ضغط الدم\n• خطر النوبات\n\nالتدبير\nتصف الدراسة التخفيض التدريجي للبنزوديازيبينات والتخفيض التدريجي لـ GHB الدوائي بوصفهما طريقتين شائعتين لإزالة السموم، وتشير إلى بعض الأدلة على أن تخفيض GHB تدريجيًا قد يسيطر على الأعراض بصورة أفضل من البنزوديازيبينات وحدها. كلا النهجين يحتاج إلى مراقبة دقيقة — ولا يُعد تدبير ذلك في المنزل آمنًا.';

  @override
  String get ghbReferenceDay7 =>
      'أسبوع من دون GHB\n\nالمصدر: “Characterization of the GHB Withdrawal Syndrome”، PubMed Central\n\nمعظم الأعراض تتراجع\nانخفضت شدة أو شيوع عدة أعراض أساسية للانسحاب بأكثر من 70٪ خلال الأيام الأربعة الأولى. مع التخفيض التدريجي تحت الإشراف استمرت مرحلة خفض الجرعة نفسها 11 يومًا في المتوسط، ثم تبعتها مرحلة تعافٍ بنحو ستة أيام. لذلك يكون كثير من الناس بعد أسبوع قد دخلوا بوضوح في مرحلة التحسن، حتى إن لم تكن العملية قد اكتملت بعد.\n\nما الذي قد يستمر\n• التعرق والرعشة وارتجاف اليدين\n• النوم كثيرًا أو، على العكس، الأرق والتململ\n• الرغبة في استخدام GHB\n\nوجدت الدراسة أن هذه الأعراض المحددة تغيرت قليلًا نسبيًا حتى اليوم 11، لذلك ليس غريبًا أن تستمر بعد أسبوع. تبقى المراقبة الطبية مهمة حتى تهدأ المتلازمة بوضوح.';

  @override
  String get ghbReferenceDay14 =>
      'أسبوعان من دون GHB\n\nالمصدر: “Characterization of the GHB Withdrawal Syndrome”، PubMed Central\n\nتجاوز المرحلة الحادة\nبعد أسبوعين تكون المتلازمة الجسدية الحادة الموصوفة في الدراسة قد انحسرت عادةً أو قاربت على الانتهاء. استغرقت مرحلتا التخفيض والتعافي معًا نحو 17 يومًا في المتوسط تحت العلاج الخاضع للإشراف. ينبغي أن يتجه معدل ضربات القلب وضغط الدم ومعظم الأعراض الجسدية نحو الاستقرار.\n\nما الذي قد يبقى\nتشير الدراسة تحديدًا إلى أن بعض المرضى ظل لديهم اشتهاء وأرق عند الخروج من المستشفى، وأن ذلك قد يسهم في خطر الانتكاس. يبقى الدعم والروتين المنظم مهمين حتى بعد تجاوز المرحلة المبكرة الخطيرة.';

  @override
  String get ghbReferenceDay30 =>
      'شهر من دون GHB\n\nالمصدر: “Characterization of the GHB Withdrawal Syndrome”، PubMed Central\n\nموقع الشهر في مسار التعافي\nبعد شهر تكون المرحلة الحادة الخطيرة الموصوفة في الدراسة قد مضت منذ وقت طويل. تركزت أخطر الفترة في الأيام الأولى، ثم تلتها فترة تخفيض وتعافٍ تحت الإشراف استمرت في المتوسط نحو أسبوعين ونصف. كان الاشتهاء والأرق أبرز مخاطر الانتكاس المتبقية التي رُصدت عند الخروج.\n\nلماذا يظل الدعم مفيدًا\nإذا استمر الاشتهاء أو انخفاض المزاج أو مشكلات النوم بعد شهر، فهذا ينسجم مع عوامل خطر الانتكاس التي أشار إليها مؤلفو الدراسة. ولهذا يظل الدعم المستمر والروتين المنظم مهمين.';

  @override
  String get ghbReferenceDay90 =>
      'ثلاثة أشهر من دون GHB\n\nالمصدر: “Characterization of the GHB Withdrawal Syndrome”، PubMed Central\n\nثلاثة أشهر من التعافي\nبعد ثلاثة أشهر تكون متلازمة انسحاب GHB الحادة قد انتهت منذ وقت طويل. كانت المخاطر المتبقية عند الخروج هي الاشتهاء والأرق، لذلك تمنح ثلاثة أشهر من الامتناع النوم واستقرار الجهاز العصبي الذاتي وروتين الوقاية من الانتكاس وقتًا كافيًا للتثبت.\n\nما الذي يبلّغ عنه الناس عادةً\n• مزاج يومي أكثر هدوءًا\n• نوم أكثر انتظامًا\n• تفكير أوضح واشتهاء أقل\n\nإذا ظل القلق أو الأرق أو انخفاض المزاج بارزًا بعد ثلاثة أشهر، فمن الأفضل مناقشة ذلك مع مختص طبي بدل افتراض أنه سيزول وحده.';

  @override
  String get ghbReferenceDay180 =>
      'ستة أشهر من دون GHB\n\nالمصدر: “Characterization of the GHB Withdrawal Syndrome”، PubMed Central\n\nبعد نصف عام\nبعد ستة أشهر تكون متلازمة انسحاب GHB الحادة قد انتهت منذ وقت طويل، ويتحول التعافي بالكامل من إزالة السموم إلى تثبيت النوم وإدارة الاشتهاء والوقاية من الانتكاس. أما مرحلة اضطراب الجهاز العصبي الذاتي وخطر الهذيان فتخص الأيام والأسابيع الأولى، لا هذه المرحلة.\n\nالصورة الأكبر\nاجتياز انسحاب GHB بأمان والبقاء من دونه نصف عام إنجاز كبير بالنظر إلى خطورة المرحلة المبكرة وإلى واقعية خطر الانتكاس، الذي قد تسهم فيه الرغبة المستمرة والأرق. الروتين والدعم اللذان أوصلاك إلى هنا يستحقان الحفاظ عليهما.';

  @override
  String get inhalantsReferenceDay1 =>
      'التوقف عن استخدام المستنشقات: اليوم الأول\n\nالمصدر: Radparvar، \"The Clinical Assessment and Treatment of Inhalant Abuse\"، The Permanente Journal (2023)، عبر PubMed Central\n\nلماذا يحدث الانسحاب\nيؤدي الاستخدام المزمن للمستنشقات إلى تكيف عصبي، إذ يعتاد الجهاز العصبي وجود المادة. تؤثر مستنشقات كثيرة في دوائر دماغية مشابهة لتلك التي يؤثر فيها الكحول، لذلك قد يترك التوقف الدماغ في حالة اختلال مؤقت. تغادر المواد الكيميائية الدم بسرعة لكنها قد تُخزَّن في دهون الجسم، ما يجعل توقيت الانسحاب أقل قابلية للتنبؤ.\n\nالأعراض المبكرة\nتصف هذه المراجعة انسحاب المستنشقات بأنه شبيه بانسحاب الكحول أو البنزوديازيبينات، وتشمل الأعراض المبلغ عنها:\n• الغثيان والقيء والتعرق\n• الرعاش وتسارع ضربات القلب\n• الأرق واضطراب النوم\n• القلق والتهيج\n\nملاحظة للسلامة\nفي الحالات الأشد تذكر المراجعة أيضًا الهلوسة والأوهام والنوبات ضمن الأعراض المبلغ عنها، لكنها لا تقدم جدولًا زمنيًا دقيقًا يومًا بيوم. تعامل معها كأعراض قد تحدث، لا كمسار ثابت. يُستحسن الإشراف الطبي أثناء إزالة السموم، خصوصًا لدى من استخدموا المستنشقات بكثافة أو لفترة طويلة.';

  @override
  String get inhalantsReferenceDay7 =>
      'أسبوع واحد دون مستنشقات\n\nالمصدر: Radparvar، \"The Clinical Assessment and Treatment of Inhalant Abuse\"، The Permanente Journal (2023)، عبر PubMed Central\n\nالفترة الحادة\nتصف الأدبيات السريرية انسحاب المستنشقات بأنه شبيه بانسحاب الكحول أو البنزوديازيبينات، لكنه يُعد أقصر عمومًا. بحلول نهاية الأسبوع الأول تكون الأعراض الجسدية الحادة، مثل الغثيان والرعاش والتعرق والأرق، قد بدأت تنحسر لدى معظم الناس.\n\nما قد يبقى\n• التعب وضبابية التفكير\n• انخفاض المزاج أو تقلبه\n• الرغبة الشديدة في التعاطي\n\nملاحظة حول الامتناع المبكر\nضبابية التفكير في هذه المرحلة لا تعني ضررًا دائمًا، فالدماغ لا يزال يعيد التكيف. وتتناول المحطات اللاحقة الأبحاث حول كيفية تعافي التفكير والذاكرة تحديدًا خلال الأسابيع والأشهر التالية.';

  @override
  String get inhalantsReferenceDay14 =>
      'أسبوعان دون مستنشقات\n\nالمصدر: Radparvar، \"The Clinical Assessment and Treatment of Inhalant Abuse\"، The Permanente Journal (2023)، عبر PubMed Central\n\nتجاوز المرحلة الحادة\nتصف المراجعات السريرية انسحاب المستنشقات بأنه شبيه بانسحاب الكحول أو البنزوديازيبينات لكنه أقصر. بحلول أسبوعين يكون الغثيان والرعاش والأرق والقلق قد هدأ عادةً.\n\nالطريق إلى الأمام\nيتعافى الانتباه والذاكرة والحركة والتناسق بصورة أكثر تدريجية خلال الأشهر التالية. يمنح استمرار الامتناع هذه الأنظمة وقتًا للتحسن. كما تهيئ التغذية الجيدة، إذ قد يؤدي استخدام المستنشقات إلى نقص فيتامين B12، والامتناع المستمر ظروفًا أفضل للتعافي.';

  @override
  String get inhalantsReferenceDay30 =>
      'شهر واحد دون مستنشقات\n\nالمصدر: Dingwall وآخرون، \"Cognitive recovery during and after treatment for volatile solvent abuse\"، Drug and Alcohol Dependence (2011)، عبر PubMed\n\nموقع الشهر الأول في مسار التعافي\nأصبحت فترة الانسحاب المبكر خلفك. في هذه الدراسة تحسنت بعض مهارات التعلم خلال ستة أسابيع، بينما تحسن التناسق البصري والذاكرة والتخطيط واتخاذ القرار بصورة أكثر تدريجية خلال الأشهر التالية.\n\nما الذي قد يتحسن\n• الانتباه وبعض مهام التعلم\n• المزاج والنوم مع استقرار الجسم\n• السرعة الحركية بصورة تدريجية\n\nإشارة التعافي\nخلاصة الدراسة واضحة: تتحسن الذاكرة والتخطيط واتخاذ القرار تدريجيًا على مدى أشهر إلى سنوات من الامتناع. ويظل استمرار الامتناع العامل الأقوى الداعم لهذا التعافي.';

  @override
  String get inhalantsReferenceDay90 =>
      'ثلاثة أشهر دون مستنشقات\n\nالمصدر: Dingwall وآخرون، \"Cognitive recovery during and after treatment for volatile solvent abuse\"، Drug and Alcohol Dependence (2011)، عبر PubMed\n\nعملية أطول وغير متساوية\nتابعت هذه الدراسة أشخاصًا بعد برنامج علاجي استمر ثمانية أسابيع، وأعادت تقييم بعضهم بعد نحو عام. تحسنت بعض مهارات التعلم خلال ستة أسابيع، بينما واصل التناسق البصري والذاكرة والتخطيط واتخاذ القرار التحسن على مدى فترة أطول.\n\nالاستمرار في المسار\nتوضح الدراسة أن المهارات الأبطأ في التعافي تتحسن تدريجيًا على مدى أشهر إلى سنوات. عند ثلاثة أشهر، يظل استمرار الامتناع أقوى وسيلة لإضافة مزيد من التعافي شهرًا بعد شهر.';

  @override
  String get inhalantsReferenceDay365 =>
      'عام واحد دون مستنشقات\n\nالمصدر: \"A prospective study of neurocognitive changes 15 years after chronic inhalant abuse\"، عبر PubMed\n\nتعافٍ حقيقي قابل للقياس\nوجدت دراسة طويلة الأمد تعافيًا ملحوظًا من المشكلات الدماغية والمعرفية المرتبطة بالاستخدام المزمن للمستنشقات بعد عامين من الامتناع. بعد عام واحد تكون قد قطعت شوطًا مهمًا على هذا المسار.\n\nماذا يعني ذلك\nتستمر الذاكرة والانتباه والوظائف الحركية في التحسن. ويتيح الامتناع طويل الأمد تعافيًا حقيقيًا للدماغ: فبحلول عامين عادت معظم مقاييس الدماغ والذاكرة والتفكير إلى النطاق الطبيعي لدى المستخدمين المزمنين الذين لم يكن لديهم تلف دماغي بسبب الرصاص.';

  @override
  String get inhalantsReferenceDay730 =>
      'عامان دون مستنشقات\n\nالمصدر: \"A prospective study of neurocognitive changes 15 years after chronic inhalant abuse\"، عبر PubMed\n\nعلامة العامين\nهذه هي المحطة الأساسية في البحث: أظهرت أوجه القصور التي تعكس تلف الدماغ الناتج عن الاستخدام الطويل للمذيبات تعافيًا ملحوظًا بعد عامين من الامتناع. وخلص الباحثون إلى أن الامتناع طويل الأمد قد يسمح باستعادة وظائف الدماغ الطبيعية في غياب تلف الدماغ الناجم عن البنزين المحتوي على الرصاص.\n\nإشارة التعافي\nالاستثناء الرئيسي هو الضرر الناتج عن إساءة استخدام البنزين المحتوي على الرصاص، إذ قد يسبب عجزًا مستمرًا. وبخلاف ذلك يمثل عامان من الامتناع أفضل فرصة موثقة للدماغ كي يتعافى، إلى جانب حياة أُعيد بناؤها حول هذا التقدم.';

  @override
  String get ketamineReferenceDay1 =>
      'التوقف عن الكيتامين: اليوم الأول\n\nالمصدر: «التهاب المثانة الناجم عن الكيتامين: مراجعة شاملة للتأثيرات البولية لهذا العقار ذي التأثير النفسي»، على PubMed Central\n\nالانسحاب نفسي في المقام الأول\nعلى خلاف المواد الأفيونية أو الكحول، نادرًا ما يسبب الكيتامين انسحابًا جسديًا شديدًا. يكون التوقف عنه آمنًا عمومًا؛ وغالبًا ما يواجه الناس الرغبة الشديدة والاعتماد النفسي أكثر من المرض الجسدي.\n\nما قد تشعر به\n• تقلبات المزاج وانخفاضه\n• رغبة شديدة في التعاطي\n• تعرّق أو خفقان أحيانًا\n\nالخطوة الأهم\nلمن لديهم أعراض في المثانة، يُعد التوقف الفوري والكامل نقطة البداية الضرورية للتعافي — لذلك فإن قرار اليوم الأول هو الأهم.';

  @override
  String get ketamineReferenceDay7 =>
      'أسبوع واحد من دون كيتامين\n\nالمصدر: «التهاب المثانة الناجم عن الكيتامين: مراجعة شاملة»، على PubMed Central\n\nالمرحلة النفسية\nالتحدي الأساسي في بداية التوقف عن الكيتامين نفسي: رغبة شديدة في التعاطي، وتقلب المزاج أو انخفاضه، وبعض ضباب الدماغ. ويكون الانسحاب الجسدي، إن ظهر، خفيفًا عادةً.\n\nضباب الدماغ شائع في هذه المرحلة — قد يتطلب التركيز جهدًا أكبر، ويبطؤ زمن الاستجابة، وقد تبدو الذاكرة قصيرة المدى أقل موثوقية. تتحسن هذه التأثيرات في التفكير والذاكرة مع الامتناع عن الكيتامين: فقد وجدت دراسة طولية شملت 114 مستخدمًا للكيتامين تحسنًا ملحوظًا في الذاكرة اللفظية والبصرية وسرعة المعالجة والتخطيط والتركيز واتخاذ القرار بعد 12 أسبوعًا من دون كيتامين.\n\nأعراض المثانة\nإذا كنت تعاني التهاب المثانة الناجم عن الكيتامين (إلحاح أو تكرار التبول، أو ألم، أو دم في البول)، فإن التوقف الآن يمنح المثانة أفضل فرصة للتعافي. وقد يدفع الألم بعض الناس للعودة إلى الكيتامين للتداوي الذاتي — وهي دائرة من الأفضل كسرها بالحصول على دعم مناسب لتسكين الألم.';

  @override
  String get ketamineReferenceDay14 =>
      'أسبوعان من دون كيتامين\n\nالمصدر: «التهاب المثانة الناجم عن الكيتامين: مراجعة شاملة»، على PubMed Central\n\nتفكير أوضح\nبعد خروج الدواء بالكامل، يبدأ ضباب الذهن والتفكير المنفصل المرتبطان بالاستخدام المنتظم للكيتامين في الانحسار. تتحسن الذاكرة والتركيز ويستقر المزاج.\n\nبداية تعافي المثانة\nفي حالات التهاب المثانة المبكرة، تؤكد المراجعة أن مجرد التوقف عن الكيتامين هو أهم خطوة لعكس الأعراض، وأن التوقف المبكر يمنح أفضل فرصة للتعافي قبل أن يصبح الضرر دائمًا. أسبوعان من الامتناع عن الكيتامين هما بداية هذه العملية.';

  @override
  String get ketamineReferenceDay30 =>
      'شهر واحد من دون كيتامين\n\nالمصدر: «انتشار الأعراض البولية وتاريخها الطبيعي لدى مستخدمي الكيتامين لأغراض ترفيهية»، وينستوك وآخرون، BJU International (2012)\n\nتعافي المثانة\nأهم علاج منفرد لالتهاب المثانة الناجم عن الكيتامين هو التوقف عن الكيتامين. وجدت هذه الدراسة على مستخدمي الكيتامين لأغراض ترفيهية أن 51% ممن لديهم أعراض بولية أفادوا بتحسن بعد التوقف، بينما ساءت حالة أقل من 4%. وكلما كان التوقف أبكر، كانت النتيجة أفضل.\n\nالعقل والمزاج\nيستمر الإدراك والمزاج في التحسن بعد شهر. ويزيد الدعم النفسي والاجتماعي بصورة ملموسة فرصة الاستمرار في التوقف — فالتوقف ينجح على نحو أفضل مع وجود الدعم.';

  @override
  String get ketamineReferenceDay90 =>
      'ثلاثة أشهر من دون كيتامين\n\nالمصدر: «التهاب المثانة الناجم عن الكيتامين: مراجعة شاملة»، على PubMed Central\n\nاستمرار التعافي\nغالبًا ما يكون تعافي المثانة بعد الكيتامين تدريجيًا؛ وتصف المراجعة تحسن شدة الأعراض بعد التوقف، مع احتمال أن يكون التعافي طويلًا ومتفاوتًا. تمنح ثلاثة أشهر المسالك البولية وقتًا متواصلًا للتعافي في الحالات التي تستجيب للتوقف.\n\nالعقل\nيصبح التفكير والمزاج أوضح بكثير مما كانا عليه في بداية الامتناع عن الكيتامين، وتقل الرغبة الشديدة في التعاطي. وينبغي أن يقيّم طبيب مسالك بولية أعراض المثانة المستمرة أو الشديدة.';

  @override
  String get ketamineReferenceDay180 =>
      'ستة أشهر من دون كيتامين\n\nالمصدر: «التهاب المثانة الناجم عن الكيتامين: مراجعة شاملة»، على PubMed Central\n\nبعد نصف عام\nمع الاستمرار في الامتناع عن الكيتامين، تواصل أعراض المثانة التحسن في الحالات التي تستجيب للتوقف، ويستقر التفكير والذاكرة والمزاج. كما تضعف الرغبة القهرية في الاستخدام بدرجة كبيرة.\n\nإشارة إلى التعافي\nقد يكون التعافي من تلف المثانة القائم غير كامل، ولهذا يكتسب التوقف المبكر أهمية كبيرة. ومهما كانت المرحلة التي توقفت فيها، فإن الاستمرار من دون كيتامين يمنح المثانة أفضل نتيجة ممكنة.';

  @override
  String get ketamineReferenceDay365 =>
      'عام من دون كيتامين\n\nالمصدر: «التهاب المثانة الناجم عن الكيتامين: مراجعة شاملة»، على PubMed Central\n\nبعد عام\nتمنح اثنا عشر شهرًا من الامتناع عن الكيتامين المثانة، في الحالات المكتشفة مبكرًا، أكبر فرصة للتعافي، مع استقرار ووضوح التفكير والذاكرة والمزاج. كما يكون الاعتماد النفسي الذي جعل التوقف صعبًا قد تراجع بدرجة كبيرة.\n\nالصورة الأوسع\nعام من دون كيتامين يمثل تغيرًا عميقًا في الصحة الجسدية والوضوح والقدرة على توجيه الذات. والحفاظ على الدعم الذي أوصلك إلى هنا يساعد على حماية هذا التقدم.';

  @override
  String get ketamineReferenceDay730 =>
      'عامان من دون الكيتامين\n\nالمصدر: مراجعة شاملة لالتهاب المثانة الناجم عن الكيتامين عام 2022 (PubMed Central).\n\nتوصي المراجعة بشدة بالتوقف عن الكيتامين، وتشير إلى أن الحالات المبكرة تتحسن غالبًا بعد التوقف، بينما قد يكون التعافي غير كامل عند وجود إصابة متقدمة. لا تحدد المراجعة نهاية بيولوجية عامة عند عامين؛ فهذه محطة للاحتفاء بالتقدم المستدام من دون وعد بنتيجة طبية واحدة للجميع.';

  @override
  String get ketamineReferenceDay1095 =>
      'ثلاثة أعوام من دون الكيتامين\n\nالمصدر: مراجعة شاملة لالتهاب المثانة الناجم عن الكيتامين عام 2022 (PubMed Central).\n\nتوصي المراجعة بشدة بالتوقف عن الكيتامين، وتشير إلى أن الحالات المبكرة تتحسن غالبًا بعد التوقف، بينما قد يكون التعافي غير كامل عند وجود إصابة متقدمة. لا تحدد المراجعة عتبة تعافٍ خاصة عند ثلاثة أعوام؛ بل تمثل هذه المدة تقدمًا راسخًا مع بقاء النتائج فردية.';

  @override
  String get ketamineReferenceDay1460 =>
      'أربعة أعوام من دون الكيتامين\n\nالمصدر: مراجعة شاملة لالتهاب المثانة الناجم عن الكيتامين عام 2022 (PubMed Central).\n\nتوصي المراجعة بشدة بالتوقف عن الكيتامين، وتشير إلى أن الحالات المبكرة تتحسن غالبًا بعد التوقف، بينما قد يكون التعافي غير كامل عند وجود إصابة متقدمة. لا تربط المراجعة السنة الرابعة بحدث بيولوجي محدد؛ فهي محطة لأساس تعافٍ قوي وليست وعدًا طبيًا.';

  @override
  String get ketamineReferenceDay1825 =>
      'خمسة أعوام من دون الكيتامين\n\nالمصدر: مراجعة شاملة لالتهاب المثانة الناجم عن الكيتامين عام 2022 (PubMed Central).\n\nتوصي المراجعة بشدة بالتوقف عن الكيتامين، وتشير إلى أن الحالات المبكرة تتحسن غالبًا بعد التوقف، بينما قد يكون التعافي غير كامل عند وجود إصابة متقدمة. لا تعد المراجعة خمسة أعوام نهاية بيولوجية عامة؛ فالمحطة تحتفي بتقدم مستدام كبير من دون ادعاء شفاء مضمون.';

  @override
  String get kratomReferenceDay1 =>
      'انسحاب الكراتوم: اليوم الأول\n\nالمصدر: Swogger وآخرون (2022)، «Understanding Kratom Use: A Guide for Healthcare Providers»، Frontiers in Pharmacology\n\nلماذا تحدث أعراض الانسحاب\nتؤثر المركبات النشطة في الكراتوم في المستقبلات الأفيونية نفسها التي تؤثر فيها المواد الأفيونية التقليدية. ومع الاستخدام المنتظم يتكيف الجسم، لذلك قد يؤدي التوقف إلى أعراض انسحاب شبيهة بانسحاب الأفيونات. يصف هذا الدليل السريري الاعتماد وأعراض الانسحاب بوصفهما من المخاطر المعروفة للاستخدام المنتظم للكراتوم.\n\nما الذي تُظهره الأدلة عن البداية\nتشير الدراسات الحيوانية المذكورة في الدليل إلى ظهور علامات جسدية للانسحاب خلال نحو 12 ساعة، مع آثار شبيهة بالقلق خلال 24 ساعة. أما التوقيت الدقيق لبداية الأعراض لدى البشر فهو أقل وضوحًا، لكن الأعراض المبكرة الشائعة تشمل:\n• التململ والقلق وسرعة الانفعال\n• آلام العضلات وسيلان الأنف\n• التعرق ودموع العينين\n• الرغبة الملحّة في الاستخدام\n\nملاحظة عن الشدة\nيشير الدليل إلى أن طول مدة الاستخدام والجرعات الأعلى يرتبطان بانسحاب أشد وأطول. وقد يكون طلب دعم طبي تحت إشراف مناسبًا، ولا سيما إذا استُخدم الكراتوم بجرعات عالية أو مع مواد أفيونية.';

  @override
  String get kratomReferenceDay3 =>
      'انسحاب الكراتوم: أصعب الأيام\n\nالمصدر: Singh وآخرون (2014)، Drug and Alcohol Dependence — دراسة شملت 293 مستخدمًا منتظمًا للكراتوم في ماليزيا\n\nما الذي تُظهره الأدلة\nبدلًا من وجود «يوم ذروة» واحد محدد، وجدت الدراسة أن شدة الانسحاب ترتبط بكمية الاستخدام ومدته: كان لدى من يشربون ثلاثة أكواب أو أكثر من الكراتوم يوميًا احتمال أعلى بكثير للاعتماد الشديد وانسحاب أصعب. وبالنسبة لمعظم الناس تكون الأيام القليلة الأولى بعد التوقف هي الأصعب.\n\nالأعراض الشائعة\n• آلام العضلات والمفاصل وتململ الساقين\n• الأرق رغم الإرهاق\n• الغثيان وتقلصات المعدة والإسهال\n• القلق وانخفاض المزاج وسرعة الانفعال\n• رغبة ملحّة قوية\n\nتجاوز هذه المرحلة\nيساعد شرب السوائل والراحة وعلاج الأعراض. إذا كان الانسحاب شديدًا حتى الآن، فهذا يتوافق أكثر مع استخدام أثقل أو أطول مدة، وليس بالضرورة علامة على أن هناك شيئًا غير طبيعي، وعادةً ما تبدأ الأعراض بالتراجع من هنا.';

  @override
  String get kratomReferenceDay7 =>
      'أسبوع بلا كراتوم\n\nالمصدر: Swogger وآخرون (2022)، «Understanding Kratom Use: A Guide for Healthcare Providers»، Frontiers in Pharmacology\n\nبعد المرحلة الحادة\nتشير بيانات التقارير الذاتية البشرية المذكورة في الدليل إلى أن أعراض الانسحاب تختفي خلال نحو يوم إلى ثلاثة أيام لدى معظم من يتوقفون. وبحلول أسبوع تكون الأعراض الجسدية الحادة — مثل آلام العضلات والتعرق والغثيان — قد هدأت عادةً لدى الغالبية. وما قد يبقى يكون أكثر نفسية: التعب واضطراب النوم وانخفاض المزاج، بينما تتكيف المستقبلات الأفيونية التي كان الكراتوم ينشطها مجددًا مع إشارات الجسم الطبيعية.\n\nخطر حقيقي\nيشير الدليل أيضًا إلى أن عددًا صغيرًا من الناس يجدون الإقلاع عن الكراتوم صعبًا جدًا، مع انسحاب أشد وأطول لدى المستخدمين الأثقل والأطول مدة. هذا الأسبوع نقطة شائعة للعودة إلى الاستخدام، وتنخفض القدرة على تحمّل الجرعة بسرعة. لذلك فإن العودة إلى جرعة سابقة، ولا سيما مع وجود مواد أفيونية أخرى، قد تكون خطرة بالفعل.';

  @override
  String get kratomReferenceDay14 =>
      'أسبوعان بلا كراتوم\n\nالمصدر: المعهد الوطني لتعاطي المخدرات (NIDA)، «Kratom»\n\nما بعد الفترة المدروسة\nتغطي البيانات البشرية المضبوطة عن توقيت انسحاب الكراتوم الأيام القليلة الأولى فقط في الغالب، لذلك لا توجد أبحاث راسخة تحدد «الأسبوعين» كنقطة تعافٍ محددة. الموثق هو النمط الأوسع: يؤثر الكراتوم في المستقبلات الأفيونية نفسها التي تؤثر فيها المواد الأفيونية التقليدية، ومع توقف الاستخدام المنتظم تستعيد هذه المستقبلات تدريجيًا حساسيتها لإشارات الجسم الطبيعية.\n\nما يبلّغ عنه الناس عادةً\n• تتحسن الشهية والطاقة غالبًا\n• يصبح النوم أكثر انتظامًا\n• يصبح المزاج أكثر استقرارًا عادةً، مع بقاء بعض التقلب\n\nقد تستمر الرغبة الملحّة في الظهور مع التوتر والمحفزات المألوفة، لذلك تظل خطة التعامل معها مفيدة.';

  @override
  String get kratomReferenceDay30 =>
      'شهر بلا كراتوم\n\nالمصدر: المعهد الوطني لتعاطي المخدرات (NIDA)، «Kratom»\n\nتعافي نظام المكافأة\nيصف NIDA الكراتوم بأنه يؤثر في مستقبلات الأفيون في الدماغ، ويعد الاعتماد والانسحاب من المخاطر المعروفة للاستخدام المنتظم. لا توجد دراسة محددة تثبت أن الشهر يمثل نقطة تعافٍ بعينها، لكن النمط العام للاعتماد المرتبط بالمستقبلات الأفيونية هو أن استجابة الدماغ للمتع اليومية تعود تدريجيًا نحو طبيعتها مع استمرار الامتناع.\n\nما الذي يمكن أن يبنيه شهر بلا كراتوم\nشهر من دون كراتوم يعني شهرًا من النوم والوجبات والروتين المنتظم بدل الوقت والجهد اللذين كان يتطلبهما الاستخدام. تميل الرغبة الملحّة إلى الحدوث بوتيرة أقل وتصبح أسهل في التعامل، مع بقاء لحظات الضغط الشديد الأكثر هشاشة.';

  @override
  String get kratomReferenceDay90 =>
      'ثلاثة أشهر بلا كراتوم\n\nالمصدر: المعهد الوطني لتعاطي المخدرات (NIDA)، «Kratom»\n\nحالة يومية أكثر استقرارًا\nيؤثر الكراتوم في المستقبلات الأفيونية، لذا تمنح ثلاثة أشهر من دونه أنظمة المكافأة والتوتر في الدماغ وقتًا مستمرًا للاستقرار. يذكر كثيرون وضوحًا أكبر في التفكير ودافعًا أكثر ثباتًا كلما ابتعدوا عن الاستخدام النشط.\n\nلماذا يهم ذلك\nكلما ابتعد الاستخدام في الزمن، تراجعت عادةً جاذبية الكراتوم اليومية، ما يجعل هذه المحطة أساسًا متينًا لتعافٍ طويل الأمد.';

  @override
  String get kratomReferenceDay365 =>
      'عام بلا كراتوم\n\nالمصدر: المعهد الوطني لتعاطي المخدرات (NIDA)، «Kratom»\n\nبعد زمن طويل من الانسحاب الحاد\nلا ينشر NIDA جدولًا زمنيًا محددًا للتعافي من الكراتوم خلال عام، لكن عامًا من الامتناع المستمر يتجاوز بكثير نافذة الانسحاب الحاد والمبكر النفسي الموثقة في أبحاث الكراتوم. وبالنسبة لمعظم من يصلون إلى هذه المرحلة تصبح الرغبة الملحّة نادرة وأسهل بكثير في التعامل.\n\nالصورة الأوسع\nيمثل عام من الامتناع تغيرًا كبيرًا في الصحة والمال والقدرة على توجيه الحياة. ويساعد البقاء على اتصال بالدعم على حماية هذا التقدم.';

  @override
  String get kratomReferenceDay730 =>
      'عامان من دون الكراتوم\n\nالمصدر: Stanciu et al. (2021)، “Pharmacotherapy for Management of \'Kratom Use Disorder\': A Systematic Literature Review With Survey of Experts.”\n\nما تقوله الأدلة\nتصف المراجعة اعتماد الكراتوم وخطر الانتكاس وأساليب التدبير طويل الأمد، وتذكر أيضًا عدم وجود إرشادات راسخة للحفاظ على الامتناع طويل الأمد عن الكراتوم. ولا تحدد هذه الذكرى كنقطة تعافٍ بيولوجية.\n\nمعنى هذه المحطة\nالأفضل اعتبار هذه الذكرى احتفاءً بتغيير مستمر، لا موعدًا طبيًا نهائيًا. العادات والدعم والقرارات التي استمرت عبر هذه السنوات إنجازات مهمة بحد ذاتها.';

  @override
  String get kratomReferenceDay1095 =>
      'ثلاث سنوات من دون الكراتوم\n\nالمصدر: Stanciu et al. (2021)، “Pharmacotherapy for Management of \'Kratom Use Disorder\': A Systematic Literature Review With Survey of Experts.”\n\nما تقوله الأدلة\nتصف المراجعة اعتماد الكراتوم وخطر الانتكاس وأساليب التدبير طويل الأمد، وتذكر أيضًا عدم وجود إرشادات راسخة للحفاظ على الامتناع طويل الأمد عن الكراتوم. ولا تحدد هذه الذكرى كنقطة تعافٍ بيولوجية.\n\nمعنى هذه المحطة\nالأفضل اعتبار هذه الذكرى احتفاءً بتغيير مستمر، لا موعدًا طبيًا نهائيًا. العادات والدعم والقرارات التي استمرت عبر هذه السنوات إنجازات مهمة بحد ذاتها.';

  @override
  String get kratomReferenceDay1460 =>
      'أربع سنوات من دون الكراتوم\n\nالمصدر: Stanciu et al. (2021)، “Pharmacotherapy for Management of \'Kratom Use Disorder\': A Systematic Literature Review With Survey of Experts.”\n\nما تقوله الأدلة\nتصف المراجعة اعتماد الكراتوم وخطر الانتكاس وأساليب التدبير طويل الأمد، وتذكر أيضًا عدم وجود إرشادات راسخة للحفاظ على الامتناع طويل الأمد عن الكراتوم. ولا تحدد هذه الذكرى كنقطة تعافٍ بيولوجية.\n\nمعنى هذه المحطة\nالأفضل اعتبار هذه الذكرى احتفاءً بتغيير مستمر، لا موعدًا طبيًا نهائيًا. العادات والدعم والقرارات التي استمرت عبر هذه السنوات إنجازات مهمة بحد ذاتها.';

  @override
  String get kratomReferenceDay1825 =>
      'خمس سنوات من دون الكراتوم\n\nالمصدر: Stanciu et al. (2021)، “Pharmacotherapy for Management of \'Kratom Use Disorder\': A Systematic Literature Review With Survey of Experts.”\n\nما تقوله الأدلة\nتصف المراجعة اعتماد الكراتوم وخطر الانتكاس وأساليب التدبير طويل الأمد، وتذكر أيضًا عدم وجود إرشادات راسخة للحفاظ على الامتناع طويل الأمد عن الكراتوم. ولا تحدد هذه الذكرى كنقطة تعافٍ بيولوجية.\n\nمعنى هذه المحطة\nالأفضل اعتبار هذه الذكرى احتفاءً بتغيير مستمر، لا موعدًا طبيًا نهائيًا. العادات والدعم والقرارات التي استمرت عبر هذه السنوات إنجازات مهمة بحد ذاتها.';

  @override
  String get maoiReferenceDay3 =>
      'توقف MAOI: المرحلة الأعلى خطورة\n\nالمصدر: Dilsaver (1988)، بحث حول تفاعلات انسحاب MAOI\n\nتحذير السلامة الحرجة\nتحمل مثبطات MAOIs أخطر مخاطر التوقف عن تناول أي فئة من مضادات الاكتئاب. يمكن أن يؤدي التوقف المفاجئ — خاصة عن الفينيلزين والترانيلسيبرومين — إلى حدوث تفاعلات حادة تشمل:\n• القلق الشديد والانفعالات\n• الكلام المضغوط والأرق\n• الأرق أو النعاس\n• الهلوسة\n• الهذيان والذهان المصحوب بجنون العظمة\n\nإذا كنت تعاني من هذه الأعراض، فاطلب العناية الطبية الفورية.\n\nكيف تعمل MAOIs\nتعمل مثبطات MAOI عن طريق الارتباط بشكل لا رجعة فيه بإنزيمات أوكسيديز أحادي الأمين (MAO-A وMAO-B) وتعطيلها. تقوم هذه الإنزيمات عادةً بتكسير السيروتونين والنورإبينفرين والدوبامين والتيرامين في الدماغ والأمعاء. نظرًا لأن الإنزيم نفسه يتم تدميره بدلاً من إيقافه فقط، فإن التعافي يعتمد على إنتاج الجسم لإنزيم جديد وليس على مدى سرعة تصفية الدواء لمجرى الدم.';

  @override
  String get maoiReferenceDay7 =>
      'أسبوع واحد بعد MAOIs: تصنيع إنزيم MAO جاري\n\nالمصدر: \"مثبطات أوكسيديز أحادي الأمين (MAOIs)\" (StatPearls، NCBI Bookshelf)\n\nعملية استعادة الانزيم\nعلى عكس مثبطات استرداد السيروتونين الانتقائية، ومثبطات استرداد السيروتونين الانتقائية، ومضادات الاكتئاب ثلاثية الحلقات - التي تمنع إعادة امتصاص المواد الكيميائية في الدماغ بشكل عكسي - فإن مثبطات MAO التي لا رجعة فيها (فينيلزين، ترانيلسيبرومين) تدمر بشكل دائم جزيئات إنزيم أوكسيديز أحادي الأمين. ولذلك فإن الغسل السريري محكوم بمدى سرعة الجسم في تصنيع إنزيم جديد تمامًا - حوالي أسبوعين - وليس بمدى سرعة تصفية الدواء نفسه لمجرى الدم.\n\nماذا يحدث في أسبوع واحد\n• يجري تصنيع إنزيم MAO-A وMAO-B بشكل جيد، تقريبًا في منتصف فترة إعادة التركيب التي تستغرق أسبوعين تقريبًا\n• تمر مرحلة الخطر الحاد الموصوفة في اليوم الثالث، على الرغم من أن الإشراف الطبي الدقيق يظل مهمًا\n\nالتحذيرات الغذائية\nيتطلب علاج MAOI اتباع نظام غذائي منخفض التيرامين، حيث أن هذه الإنزيمات عادة ما تقوم بتكسير التيرامين وتمنعه من إثارة أزمة ارتفاع ضغط الدم. التوجيه هو الاستمرار في مراقبة القيود الغذائية من خلال نافذة إعادة التركيب هذه - وسينصحك الطبيب عندما يكون من الآمن تخفيفها.';

  @override
  String get maoiReferenceDay14 =>
      'بعد أسبوعين من مثبطات MAOI: تم استعادة نشاط إنزيم MAO بشكل كبير\n\nالمصدر: فريتز وآخرون. (1983)، الطب النفسي البيولوجي\n\nعلامة الأسبوعين الحاسمة\nأسبوعين هو الإطار الزمني القياسي للشفاء السريري لاستعادة إنزيم MAO بعد التوقف عن MAOI الذي لا رجعة فيه مثل ترانيلسيبرومين أو فينيلزين. من خلال دراسة ترانيلسيبرومين، وجد هذا البحث أن النشاط التحفيزي للصفائح الدموية MAO-B - الذي انخفض بشكل حاد خلال يوم واحد من الجرعات - يعود إلى طبيعته في غضون أسبوعين تقريبًا، حيث يستبدل الجسم الصفائح الدموية المتضررة من الدواء بصفائح جديدة تحمل إنزيمًا نشطًا، على الرغم من أن إجمالي مستويات بروتين MAO-B لم تتغير أبدًا.\n\nاستعادة إنزيم MAO\n• تعافى نشاط الصفائح الدموية MAO-B بشكل كبير عند هذه النقطة\n• تم أيضًا استعادة إنزيما MAO-A وMAO-B في الدماغ، اللذين يتبعان جدولًا زمنيًا مشابهًا إلى حد كبير لإعادة التركيب، إلى حد كبير\n• يتم إعادة استقلاب التيرامين إلى طبيعته - يمكن عادة تخفيف القيود الغذائية لـ MAOI بالتشاور مع الطبيب الذي يصف لك الدواء\n\nعودة التوازن الكيميائي للدماغ\nمع استعادة نشاط إنزيم MAO، بدأت الأنظمة الكيميائية في الدماغ التي تؤثر عليها مثبطات MAO تخضع للتنظيم الطبيعي:\n• لم تعد مستويات السيروتونين والنورادرينالين والدوبامين مرتفعة بسبب تثبيط MAO\n• بدأت الحساسية المفرطة لمستقبلات أحادي الأمين (الناجمة عن ارتفاع المستويات الكيميائية الدماغية المزمنة لـ MAOI) في التلاشي\n• عودة تنظيم المزاج الطبيعي والطاقة';

  @override
  String get maoiReferenceDay30 =>
      'شهر واحد بعد MAOIs: إعادة توازن أنظمة الدماغ الكيميائية\n\nالمصدر: \"مثبطات أوكسيديز أحادي الأمين (MAOIs)\" (StatPearls، NCBI Bookshelf)\n\nالتقييم لمدة شهر واحد\nبعد مرور شهر واحد على إيقاف MAOI، يكون قد تجاوز فترة إعادة تكوين إنزيم MAO التي تبلغ أسبوعين تقريبًا الموصوفة في هذا المصدر، لذلك بحلول هذه المرحلة يكون نشاط إنزيم MAO قد تعافى تمامًا وتكون الأنظمة الكيميائية في الدماغ تحت تنظيم طبيعي تمامًا.\n\nما تم استعادته خلال شهر واحد\n• استكمال نشاط إنزيم MAO: كل من MAO-A وMAO-B يعملان بكامل طاقتهما\n• حل القيود الغذائية: اتباع نظام غذائي عادي دون قيود التيرامين\n• تحلل السيروتونين الطبيعي: يتم استعادة دورة دوران السيروتونين الطبيعية في الدماغ\n• تنظيم الكاتيكولامينات الطبيعية: يتم تنظيم مستويات الدوبامين والنورإبينفرين من خلال نشاط MAO الطبيعي\n\nيحذر التفاعل الدوائي\nترتبط مثبطات MAOI بتفاعلات مهددة للحياة مع أدوية السيروتونين. تم حل مخاطر التفاعل هذه عند علامة شهر واحد. ومع ذلك، أبلغ دائمًا واصف الدواء والصيدلي باستخدام MAOI السابق عند وصف أي دواء جديد.';

  @override
  String get maoiReferenceDay90 =>
      'بعد ثلاثة أشهر من مثبطات MAO: تجاوز المرحلة الحادة للانسحاب\n\nالمصدر: \"Antidepressant Withdrawal Syndrome\"، Therapeutics Letter 112 (2018)، Therapeutics Initiative، على NCBI Bookshelf\n\nالانسحاب عبر فئات مضادات الاكتئاب\nتتعامل مراجعة الأدلة هذه مع انسحاب مضادات الاكتئاب بوصفه ظاهرة حقيقية مرتبطة بالتحمل والاعتماد. تركز الأدلة التفصيلية أساساً على SSRIs وSNRIs، لكن تفاعلات الانسحاب معترف بها عبر فئات مضادات الاكتئاب، بما في ذلك بعد إيقاف مثبطات MAO. تظهر الأعراض \"عادة خلال بضعة أيام من التوقف\"، و\"تزول معظمها… خلال أسبوعين\"، مع أنها قد تستمر مدة أطول لدى بعض الأشخاص.\n\nموضع الأشهر الثلاثة\nبعد ثلاثة أشهر تكون مرحلة الانسحاب الحاد قد مضت لدى الغالبية العظمى من الناس، ويكون الجسم قد تأقلم منذ وقت طويل مع تنظيم أحاديات الأمين من دون تثبيط MAO.\n\nإشارة التعافي و\"إعادة تحسس المستقبلات\"\nالجزم بأن مستقبلات السيروتونين والنورإبينفرين والدوبامين قد \"أعيد تحسسها بالكامل خلال ثلاثة أشهر\" يتجاوز ما تثبته الأدلة. ما يمكن الاعتماد عليه هو أن مرحلة الانسحاب تكون قد انتهت عادة، وأن المزاج والطاقة والمدى العاطفي لدى معظم الناس يستقر مع عودة الإشارات الدماغية الطبيعية ذاتية التنظيم.\n\nالانسحاب أم الانتكاس\nتشدد الرسالة على التفريق بين الانسحاب والعودة الحقيقية للحالة الأساسية. إذا استمرت الأعراض بعد ثلاثة أشهر، فراجعها مع الطبيب بدلاً من افتراض أنها مجرد أعراض انسحاب.';

  @override
  String get maoiReferenceDay180 =>
      'ستة أشهر بعد MAOIs: التعافي على المدى الطويل\n\nالمصدر: زويبل وفيغيرا (2022)، مجلة كليفلاند كلينيك الطبية\n\nتقييم الستة أشهر\nتشرح هذه المراجعة أن مضادات الاكتئاب تعمل جزئيًا عن طريق التسبب في تقليل تنظيم مستقبلات أحادي الأمين بمرور الوقت، وأن هذا التنظيم يتطلب أسابيع إلى أشهر لعكسه بمجرد توقف الدواء - وهي عملية أبطأ من إعادة تكوين إنزيم MAO نفسه لمدة أسبوعين تقريبًا.\n\nحيث يجلس ستة أشهر\nستة أشهر تقع بشكل مريح بعد نافذة إعادة ضبط المستقبلات من أسابيع إلى أشهر بالنسبة للغالبية العظمى من الناس، إلى جانب نشاط الإنزيم الذي تم تطبيعه بالكامل خلال الشهر الأول. إشارة التعافي: لم يتم تحديد جداول زمنية دقيقة لإعادة حساسية مستقبلات السيروتونين والنورإبينفرين والدوبامين بشكل مؤكد يومًا بعد يوم في الأدبيات الطبية - ما يمكن الاعتماد عليه هو أنه بحلول ستة أشهر، يعمل معظم الناس وفقًا لإشارات الدماغ الطبيعية ذاتية التنظيم.\n\nملاحظة على فينيثيلامين\nكما تمنع مثبطات MAOIs تحلل الفينيثيلامين (PEA)، وهو أمين أمين مرتبط بالمزاج والطاقة. من المتوقع أن يعود التمثيل الغذائي إلى طبيعته جنبًا إلى جنب مع التعافي العام لإنزيم MAO، على الرغم من أنه - كما هو الحال مع إعادة حساسية المستقبل - لم يتم تحديد جدول زمني محدد خاص بـ PEA في الأدبيات البحثية.';

  @override
  String get maoiReferenceDay365 =>
      'بعد عام من مثبطات MAO: عام من التعافي\n\nالمصدر: \"Monoamine Oxidase Inhibitors (MAOIs)\" (StatPearls، NCBI Bookshelf)\n\nعام واحد: إنجاز مهم\nإكمال عام كامل بعد إيقاف مثبطات MAO يمثل محطة مهمة حقاً. ويتطلب إيقاف هذه الأدوية عناية خاصة بسبب آليتها غير القابلة للعكس، والنظام الغذائي الصارم منخفض التيرامين، واحتياطات التداخلات الدوائية التي تميزها عن فئات أخرى من مضادات الاكتئاب.\n\nما الذي يمثله هذا العام\n• عام كامل من نشاط أوكسيداز أحادي الأمين الطبيعي والمنظم ذاتياً، بعد اكتمال إعادة تصنيع الإنزيم خلال الشهر الأول\n• قدرة مثبتة على الحفاظ على العافية من دون تثبيط MAO الدوائي\n• مدة كافية للثقة بأن مخاطر التوقف الحادة المرتبطة باليوم الثالث أصبحت وراءك بوضوح\n\nملاحظة حول مثبطات MAO\nتظل مثبطات MAO فعالة بشكل مميز في بعض حالات الاكتئاب المقاوم للعلاج والاكتئاب اللانمطي. لا يقلل التوقف الناجح من قيمتها كأدوية؛ بل يعكس قدرة الدماغ على التعافي وقدرة المريض على اجتياز عملية طبية صعبة. احتياط دائم واحد: واصل إبلاغ أي طبيب جديد أو طبيب تخدير عن استخدامك السابق لمثبطات MAO، لأن بعض مخاطر التداخلات الدوائية تستحق التنبيه إليها على المدى الطويل.';

  @override
  String get marijuanaReferenceDay1 =>
      'انسحاب الماريجوانا: اليوم الأول\n\nالمصدر: \"متلازمة انسحاب القنب: الرؤى الحالية،\" تعاطي المخدرات وإعادة التأهيل (2017)، على PubMed Central\n\nانسحاب القنب حقيقي\nتثبت هذه المراجعة التي تمت مراجعتها من قبل النظراء أن متلازمة انسحاب القنب (CWS) هي حالة سريرية تم التحقق منها جيدًا، وتحدث في حوالي 90٪ من الأشخاص الذين تم تشخيص إدمانهم للقنب بعد توقفهم. متوسط ​​​​شدة الذروة يمكن مقارنته بمتلازمة انسحاب التبغ.\n\nلماذا يحدث الانسحاب\nيعمل THC على نظام الإندوكانابينويد - مستقبلات CB1 المشاركة في المزاج والشهية والنوم والذاكرة والتوتر. ومع الاستخدام المزمن، يقوم الدماغ بخفض تنظيم هذا النظام؛ عندما يتوقف الحشيش، يصبح خاملاً مؤقتًا. تشير المراجعة إلى عودة مستقبلات CB1 إلى عملها الطبيعي خلال حوالي أربعة أسابيع من الامتناع عن القنب.\n\nالبداية في اليوم الأول\nتوثق المراجعة أن الأعراض الجسدية تميل إلى الظهور أولاً - خلال 1-3 أيام من آخر استخدام - بينما تظهر الأعراض النفسية خلال 2-10 أيام. تشمل الأعراض المبكرة ما يلي:\n• التهيج والقلق والأرق\n• صعوبة في النوم\n• انخفاض الشهية\n• التوتر الجسدي، والتعرق، أو قشعريرة\n• مزاج مكتئب\n\nالشدة\nإن متلازمة CWS ليست خطيرة من الناحية الطبية وعادة ما تكون الأعراض خفيفة إلى معتدلة، لكن المراجعة تشير إلى أنها يمكن أن تكون مؤلمة بدرجة كافية لتحفيز الانتكاس - ولهذا السبب فإن فهم الجدول الزمني مهم.';

  @override
  String get marijuanaReferenceDay3 =>
      'الجدول الزمني لسحب القنب: الأيام الأولى\n\nالمصدر: \"الدورة الزمنية لأعراض انسحاب القنب DSM-5 لدى متعاطي المواد المتعددة،\" BMC للطب النفسي (2013)، في PubMed Central\n\nدورة زمنية محسوبة\nتتبعت هذه الدراسة أعراض انسحاب القنب DSM-5 لدى 90 مريضًا على مدار أربعة أسابيع، مما أدى إلى إنتاج واحدة من أوضح الصور لكيفية ارتفاع الأعراض وانخفاضها. اتبعت الخطورة الإجمالية منحنى: ارتفاع، ثم انخفاض خلال الأسابيع التالية.\n\nما الذروة في وقت مبكر\nتصل العديد من الأعراض الأكثر إزعاجًا جسديًا خلال الأيام القليلة الأولى من التوقف:\n• الأرق — يصل إلى ذروته في اليوم الأول تقريبًا\n• العصبية — تبلغ ذروتها في اليوم الرابع تقريبًا\n• مزاج مكتئب وأعراض جسدية — تبلغ ذروتها في اليوم الخامس تقريبًا\n• الأرق — يصل إلى ذروته في اليوم السادس تقريبًا\n\nما قمم في وقت لاحق\nووجدت الدراسة أن بعض الأعراض تظهر وتصل ذروتها في وقت لاحق من الأسبوع الأول:\n• أحلام حية وغير سارة - تبلغ ذروتها في اليوم الحادي عشر تقريبًا\n• التهيج والغضب — يصل إلى ذروته في اليوم الرابع عشر تقريبًا\n\nالنوم والحشيش\nتعكس الأحلام الحية المتأخرة ارتداد حركة العين السريعة: يثبط الحشيش نوم حركة العين السريعة أثناء الاستخدام، ويعوض الدماغ بشكل مفرط بمجرد توقفه. ويرى المؤلفون أن هذا العرض شائع بما يكفي ليندرج ضمن معايير الانسحاب الرسمية.\n\nخلاصة اليوم الثالث\nبحلول اليوم الثالث، تكون في ذروة الذروة الجسدية المبكرة - حيث يكون الأرق والعصبية والأرق في أسوأ حالاتهم. إن المنحنى الثابت الذي يمكن التنبؤ به هو في حد ذاته مطمئن: فهذه الأعراض لها مسار معروف وتتراجع من هنا.';

  @override
  String get marijuanaReferenceDay7 =>
      'أسبوع واحد بدون القنب: من خلال الأسوأ\n\nالمصدر: \"متلازمة انسحاب القنب: الرؤى الحالية،\" تعاطي المخدرات وإعادة التأهيل (2017)، على PubMed Central\n\nحيث يجلس أسبوع واحد في المتلازمة\nتوثق هذه المراجعة أن متلازمة انسحاب القنب عادة ما تستمر لمدة تصل إلى ثلاثة أسابيع تقريبًا، وتقع الفترة الأكثر إزعاجًا بين الأسبوع الأول والثالث. في غضون أسبوع واحد، عادة ما تكون الأعراض الجسدية المبكرة - الأرق، وفقدان الشهية، والأرق - قد تجاوزت ذروتها وبدأت في التراجع.\n\nما الذي لا يزال يستقر\nتميز المراجعة بين الأعراض الجسدية التي تبلغ ذروتها مبكرًا والأعراض النفسية التي تصل إلى ذروتها لاحقًا. في أسبوع واحد:\n• يتحسن الانزعاج الجسدي والشهية إلى حد كبير\n• لا يزال النوم متقطعًا بالنسبة للكثيرين، وغالبًا ما تصل الأحلام الواضحة (ارتداد حركة العين السريعة) إلى ذروتها الآن\n• يمكن أن يظل التهيج والمزاج مرتفعين، حيث يميل هذان إلى الوصول إلى الذروة في وقت لاحق خلال الأسبوعين الأولين\n\nالبيولوجيا العصبية للشفاء\nوفي ظل هذه التغييرات، تشير المراجعة إلى أن مستقبلات CB1 ذات التنظيم المنخفض تعود إلى الأداء الطبيعي في غضون أربعة أسابيع تقريبًا من الامتناع عن القنب. وبعد مرور أسبوع، تجري عملية إعادة التنظيم هذه على قدم وساق، حيث يتعافى النظام حتى مع استمرار بعض الأعراض.\n\nالخلاصة\nإن الوصول إلى أسبوع واحد يعني أن الذروة الجسدية الحادة قد أصبحت خلفك. تعد أعراض النوم والمزاج المتبقية جزءًا من متلازمة ذات مسار محدد ومعروف يستمر في حله خلال الأسبوعين المقبلين.';

  @override
  String get marijuanaReferenceDay14 =>
      'أسبوعين بدون القنب: انتهاء الانسحاب الحاد\n\nالمصدر: بودني، AJ وآخرون. (2003) - دراسة تمت مراجعتها من قبل النظراء حول دورة زمنية لسحب القنب\n\nنتائج البحث\nوثقت هذه الدراسة الخاضعة لاستعراض الأقران بشكل منهجي المسار الزمني لأعراض انسحاب القنب لدى المستخدمين العاديين. أظهرت النتائج أن متلازمة الانسحاب الحاد تبلغ ذروتها خلال الأسبوع الأول وتختفي إلى حد كبير خلال أسبوعين من التوقف عن معظم الأعراض.\n\nما يحل لمدة 2 أسابيع\nوقد وثقت الدراسة أنه بحلول 14 يومًا، تم حل الأعراض التالية إلى حد كبير لدى المشاركين في الدراسة:\n• الانزعاج الجسدي والأعراض الجسدية\n• اضطراب الشهية\n• معظم اضطرابات النوم\n• ذروة التهيج والقلق\n\nما قد يستمر بعد أسبوعين\nحدد البحث أيضًا الأعراض التي استمرت بعد فترة الأسبوعين لدى بعض المستخدمين:\n• مزاج مكتئب\n• صعوبات في التركيز\n• جودة النوم (على الرغم من التحسن)\n\nأهمية علامة الأسبوعين\nيعد اجتياز علامة الأسبوعين أمرًا مهمًا لأنه يعني أن متلازمة الانسحاب الحاد قد اكتملت إلى حد كبير. ترتبط التحديات التي تتجاوز هذه النقطة في المقام الأول بتعافي الدماغ على المدى الطويل وإدارة الأسباب الكامنة وراء تعاطي القنب، بدلاً من الاستجابة الفسيولوجية الحادة للتوقف.';

  @override
  String get marijuanaReferenceDay30 =>
      'شهر واحد بدون الحشيش: تتحسن وظيفة الذاكرة\n\nالمصدر: البابا وآخرون. (2001)، أرشيف الطب النفسي العام\n\nالقنب والذاكرة: المشكلة\nتابعت هذه الدراسة مستخدمي القنب الثقيل على المدى الطويل خلال 28 يومًا من الامتناع المؤكد عن ممارسة الجنس وقارنت نتائج اختبار التفكير والذاكرة مع المستخدمين الخفيفين وغير المستخدمين. في بداية الامتناع عن القنب، ومرة ​​أخرى في اليوم الأول والسابع، كان أداء المستخدمين المفرطين أسوأ من الضوابط فيما يتعلق باستدعاء قوائم الكلمات - وهو العجز الذي تم تتبعه من خلال مستويات مستقلب رباعي هيدروكانابينول (THC) في البول، مما يعكس التعرض الأخير للمخدرات بدلاً من الاستخدام مدى الحياة.\n\nالأخبار الجيدة: التعافي بحلول اليوم الثامن والعشرين\nبحلول اليوم 28، كان أداء المستخدمين الثقيلين والمستخدمين الخفيفين وغير المستخدمين هو نفسه تقريبًا في اختبارات التفكير والذاكرة الخاصة بالدراسة. لم تكن هناك أيضًا علاقة ذات دلالة إحصائية بين إجمالي استخدام القنب مدى الحياة وأداء الاختبار في تلك المرحلة.\n\nماذا يعني هذا في 30 يوما\n• عاد التعلم اللفظي والتذكر إلى مستويات المجموعة الضابطة\n• تم حل العجز المتبقي الذي شهدناه في الأسبوع الأول\n• كان العجز المتبقي في وقت سابق مرتبطا بالتعرض الأخير، وليس بالضرر الدائم\n\nما تظهره الأدلة\nبحلول اليوم 28، لم يكن من الممكن تقريبًا تمييز المستخدمين الثقيلين عن المستخدمين الخفيفين وغير المستخدمين عبر المجموعة الكاملة من اختبارات التفكير والذاكرة الخاصة بالدراسة. وقد تعافى العجز في التعلم اللفظي والتذكر الذي شوهد في الأسبوع الأول إلى مستويات المجموعة الضابطة.';

  @override
  String get marijuanaReferenceDay60 =>
      'شهرين بدون القنب: التركيز يشحذ\n\nالمصدر: روتين وآخرون. (2015)، سلوكيات الإدمان\n\nسؤال البحث\nتتبعت دراسة الإقلاع عن تعاطي القنب لدى الشباب نتائج اختبارات الذاكرة والتفكير إلى جانب اختبارات البول على مدار شهرين تقريبًا، ومقارنة المستخدمين المستمرين بالأشخاص الذين توقفوا مؤخرًا أو ظلوا ممتنعين عن التدخين.\n\nالنتائج الرئيسية\nارتبط الامتناع المستمر عن ممارسة الجنس بتحسن كبير في:\n• درجة الذاكرة المركبة\n• الذاكرة اللفظية على وجه التحديد — المجال الأكثر تأثرًا\n• أداء الحركة وسرعة رد الفعل\n\nفي شهرين\nوبعد ما يقرب من ثمانية أسابيع من الامتناع المستمر عن ممارسة الجنس، ارتفعت درجات أداء الذاكرة والحركة وسرعة رد الفعل بشكل ملموس فوق المكان الذي كانت عليه أثناء الاستخدام النشط، وتتبعت عن كثب عدم الاستخدام المؤكد بدلاً من الوقت وحده.\n\nما تظهره الدراسة\nفي المراهقين والشباب الذين يعانون من إدمان القنب، أنتج الامتناع المستمر عن ممارسة الجنس مكاسب كبيرة في الذاكرة المركبة، والذاكرة اللفظية، وأداء الحركة وسرعة رد الفعل عبر نافذة العلاج التي استمرت شهرين تقريبًا.';

  @override
  String get marijuanaReferenceDay90 =>
      'ثلاثة أشهر بدون القنب: عودة استقرار الحالة المزاجية\n\nالمصدر: كونور وآخرون. (2022)، الإدمان – مراجعة سريرية لانسحاب القنب\n\nكيف يبدو الجدول الزمني للانسحاب في الواقع؟\nتصف هذه المراجعة أعراض انسحاب القنب التي تبدأ عادة بعد 24-48 ساعة من التوقف وتبلغ ذروتها في الأيام 2-6. يمكن أن يظهر الغضب والعدوان والمزاج المكتئب في وقت مبكر يصل إلى أسبوع واحد ولكنه عادةً ما يصل إلى ذروته بعد حوالي أسبوعين من الامتناع عن القنب. يمكن أن يستمر اضطراب النوم على وجه الخصوص لفترة أطول من الأعراض الأخرى.\n\nحيث يجلس ثلاثة أشهر\nبحلول ثلاثة أشهر، تكون قد تجاوزت دورة الانسحاب الموثقة: تبدأ الأعراض عادةً خلال 24-48 ساعة، وتصل إلى ذروتها في الأيام 2-6، وحتى تباطؤ المزاج وأعراض النوم تبلغ ذروتها خلال الأسابيع التالية. تسعون يومًا تمنح تلك التأثيرات المزاجية والنومية التي يحركها الانسحاب أشهرًا حتى تستقر.\n\nملاحظة عن نظام الإندوكانابينويد\nتُظهر أبحاث انسحاب القنب أيضًا أن مستقبلات CB1 ذات التنظيم المنخفض تعود إلى الأداء الطبيعي في غضون أربعة أسابيع تقريبًا من الامتناع عن القنب. بعد 90 يومًا، تكون قد تجاوزت فترة استرداد المستقبل.\n\nالتطلع إلى الأمام\nوتناقش المراجعة أيضًا تشخيص ما بعد إزالة السموم والوقاية من الانتكاسات، مع التأكيد على أن الدعم المستمر واستراتيجيات المواجهة لها أهمية تتجاوز نافذة الانسحاب الحاد.';

  @override
  String get marijuanaReferenceDay180 =>
      'ستة أشهر بدون القنب: تعافي التخطيط وصنع القرار\n\nالمصدر: كرين وكرين وماسون (2011)، مجلة طب الإدمان\n\nالتخطيط وصنع القرار بعد القنب\nفحصت هذه المراجعة الانتباه، وصنع القرار، وضبط النفس، والذاكرة العاملة، والطلاقة اللفظية من الساعات الأولى بعد الاستخدام وحتى الامتناع عن القنب على المدى الطويل. بحلول ستة أشهر، تكون قد تجاوزت التأثيرات قصيرة المدى بكثير ودخلت في فترة تعافي عميقة.\n\nما وجده البحث\nالعديد من المشاكل المرتبطة بالاستخدام المكثف تنحسر مع الامتناع المستمر عن ممارسة الجنس، حيث وجدت بعض الدراسات التعافي خلال 28 يومًا. تشمل المناطق الأبطأ للتعافي بعد الاستخدام المكثف والمبكر ما يلي:\n• اتخاذ القرار وتحمل المخاطر - تم تحديدها على وجه التحديد على أنها مجالات يمكن أن يستمر فيها العجز على المدى الطويل لدى المستخدمين المزمنين بكثرة\n• التفكير المجرد والمهارات اللفظية — تضعف بشكل خاص لدى البالغين الذين بدأوا التعاطي قبل سن 17 عامًا\n\nالتعافي المبكر\nستة أشهر هي أبعد بكثير من التأثيرات قصيرة المدى في هذه المراجعة. يستمر التخطيط وصنع القرار والتفكير في التحسن مع الامتناع المستمر، مما يجعل الامتناع المستمر أقوى طريق لمزيد من التعافي.\n\nالصورة الأوسع\nبالنسبة للاستخدام الخفيف عند البالغين، تكون التوقعات أكثر ملاءمة - حيث يبلغ العديد من الأشخاص في عمر الستة أشهر عن تفكير أكثر وضوحًا، واتخاذ قرارات أكثر ثباتًا، وإحساس أقوى بالتوجيه الذاتي. أكبر المكاسب تأتي من الامتناع عن القنب، خاصة بعد الاستخدام المكثف أو المبكر.';

  @override
  String get marijuanaReferenceDay365 =>
      'سنة واحدة بدون القنب: يتعافى هيكل الدماغ\n\nالمصدر: \"أضرار الحصين والحماية والتعافي بعد الاستخدام المنتظم للقنب\"، الطب النفسي الانتقالي (2016)، في PubMed Central\n\nالتغييرات الهيكلية من القنب\nقامت دراسة مسح الدماغ هذه بفحص الحصين، وهي منطقة دماغية مركزية للذاكرة، لدى المستخدمين الحاليين، والمستخدمين السابقين، وغير المستخدمين. المستخدمون الحاليون الذين لم يتعرضوا لاتفاقية التنوع البيولوجي كان لديهم قرن آمون أصغر بنسبة 11٪ تقريبًا وعلامة صحة خلايا الدماغ أقل بحوالي 15٪ من مجموعة التحكم.\n\nالنتيجة الرئيسية: التعافي مع الامتناع عن القنب\nدعمت التحليلات الملائمة للمنحنى نموذج \"الحماية والاسترداد\". ومن الأهمية بمكان أن المستخدمين السابقين - الممتنعين عن ممارسة الجنس لمدة متوسطها حوالي 29 شهرًا - لم يختلفوا عن غير المستخدمين للضوابط في أي إجراء من تدابير النزاهة. استنتج المؤلفون أن الأضرار المرتبطة بمنطقة الذاكرة المرتبطة بـ THC \"يمكن استردادها مع فترات طويلة من الامتناع عن القنب\".\n\nتعافي الدماغ على مدى عام وما بعده\nبعد عام واحد من عدم تعاطي القنب، يكون نظام الذاكرة في الدماغ في مرحلة التعافي: حجم الحصين وصحة خلايا الدماغ يعودان إلى الوضع الطبيعي، مما يدعم الذاكرة والتحكم العاطفي.\n\nإشارة الاسترداد\nالمستخدمون السابقون الممتنعون عن ممارسة الجنس لمدة 29 شهرًا تقريبًا يطابقون غير المستخدمين في المقاييس الصحية للحصين في الدراسة. وبعد عام واحد، يتحرك نظام الذاكرة بالفعل على طول مسار الاسترداد الموثق نحو الوضع الطبيعي.';

  @override
  String get mdmaReferenceDay1 =>
      'بعد MDMA: مرحلة الهبوط\n\nالمصدر: Meyer (2013), \"3,4-Methylenedioxymethamphetamine (MDMA): Current Perspectives,\" Substance Abuse and Rehabilitation\n\nلماذا ينخفض المزاج\nيعمل MDMA عبر إطلاق كمية كبيرة من السيروتونين، إلى جانب بعض الدوبامين. بعد ذلك ينخفض السيروتونين المتاح في الدماغ مؤقتًا. تصف هذه المراجعة انخفاضًا في المزاج، يُسمى أحيانًا “midweek blues”، قِيس لدى المستخدمين الجدد وذوي الخبرة بعد 2–5 أيام من الاستخدام.\n\nما يساعد\n• شرب الماء وتناول غذاء مغذٍ\n• النوم\n• الصبر — هذا الانخفاض مؤقت وليس حالة دائمة\n\nتختلف مرحلة الهبوط بعد استخدام واحد عن الانسحاب المرتبط بالاعتماد. وتصف المراجعة نفسها الاعتماد بأنه قد يتضمن رغبة في الاستخدام، ولكن من دون أعراض جسدية بارزة.';

  @override
  String get mdmaReferenceDay3 =>
      'بعد بضعة أيام من MDMA\n\nالمصدر: Meyer (2013), \"3,4-Methylenedioxymethamphetamine (MDMA): Current Perspectives,\" Substance Abuse and Rehabilitation\n\n“Midweek blues”\nهذه تقريبًا الفترة التي تصفها المراجعة عند مناقشة “midweek blues”: انخفاض في المزاج قِيس بعد 2–5 أيام من الاستخدام لدى المستخدمين الجدد وذوي الخبرة، ويرتبط بانخفاض قصير الأمد في السيروتونين لا بتغير دائم.\n\nما يبدأ بالتحسن\n• يبدأ المزاج عادةً بالصعود من أدنى نقطة\n• تعود الطاقة تدريجيًا\n• يبدأ النوم بالعودة إلى طبيعته';

  @override
  String get mdmaReferenceDay7 =>
      'أسبوع واحد بعد MDMA\n\nالمصدر: Meyer (2013), \"3,4-Methylenedioxymethamphetamine (MDMA): Current Perspectives,\" Substance Abuse and Rehabilitation\n\nبعد مرحلة “midweek blues”\nبالنسبة لمعظم الناس يكون الأسبوع قد تجاوز نافذة 2–5 أيام التي تربطها المراجعة بالهبوط الحاد، لذلك يُفترض أن يكون المزاج قد عاد نحو الطبيعي. وتذكر المراجعة أن الرغبة في الاستخدام قد تستمر لدى من يستخدمون بكثافة أو بصورة متكررة كجزء من نمط الاعتماد، لكنها لا تصف انسحابًا جسديًا شديدًا.\n\nمتى تطلب المساعدة\nإذا استمر انخفاض المزاج أو القلق أو مشكلات النوم بعد أسبوع، فقد يكون الأمر أكثر من مجرد هبوط عابر، ومن المفيد التحدث إلى مختص.';

  @override
  String get mdmaReferenceDay14 =>
      'أسبوعان من دون MDMA\n\nالمصدر: Meyer (2013), \"3,4-Methylenedioxymethamphetamine (MDMA): Current Perspectives,\" Substance Abuse and Rehabilitation\n\nمسار التعافي\nبعد استخدام واحد يكون الأسبوعان أبعد بكثير من فترة الانخفاض التي توثقها المراجعة بين 2 و5 أيام، لذا ينبغي أن يكون المزاج والنوم والتركيز أكثر استقرارًا. بعد الاستخدام الأثقل أو المتكرر يستمر التعافي لما بعد مرحلة الهبوط، وتُظهر دراسات التصوير لدى الممتنعين أن قدرة إعادة امتصاص السيروتونين تتحسن مع استمرار الامتناع.\n\nماذا يعني ذلك لك\nإذا كان الاستخدام عرضيًا فمن المرجح أنك تجاوزت أصعب مرحلة. وإذا كان متكررًا أو كثيفًا فأعطِ نفسك وقتًا — التعافي الكامل لإشارات السيروتونين يستغرق أكثر من أسبوعين، وتتناوله المراحل التالية.';

  @override
  String get mdmaReferenceDay30 =>
      'شهر من دون MDMA\n\nالمصدر: \"Serotonin transporter availability, neurocognitive function and their correlation in abstinent MDMA users,\" PubMed\n\nأين يقع الشهر في مسار التعافي\nأصبحت مرحلة الهبوط الحاد وأعراض الانسحاب المبكرة وراءك، وصار المزاج والتفكير والذاكرة أكثر استقرارًا. تُظهر أبحاث التصوير أن MDMA يقلل قدرة الدماغ على معالجة السيروتونين، وأن هذه القدرة تتحسن مع الامتناع المستمر.\n\nإشارة التعافي\nتُظهر الأبحاث نفسها تحسن قدرة إعادة امتصاص السيروتونين مع استمرار الامتناع. يتحسن المزاج ووظيفة السيروتونين أولًا، بينما تسير الذاكرة وفق وتيرتها الخاصة — والاستمرار من دون MDMA يدعم المسارين.';

  @override
  String get mdmaReferenceDay90 =>
      'ثلاثة أشهر من دون MDMA\n\nالمصدر: \"Serotonin transporter availability, neurocognitive function and their correlation in abstinent MDMA users,\" PubMed\n\nاستمرار التعافي\nمع الامتناع المستمر يواصل نظام السيروتونين في الدماغ التعافي، خصوصًا في المناطق الأعمق. ويكون المزاج والنوم عادةً أكثر استقرارًا في هذه المرحلة.\n\nإشارة التعافي\nيدعم الامتناع المستمر تعافي ناقلات السيروتونين عبر مناطق الدماغ، مع بقاء المزاج والنوم مستقرين واستمرار تحسن التفكير والذاكرة.';

  @override
  String get mdmaReferenceDay365 =>
      'عام من دون MDMA\n\nالمصدر: \"Serotonin transporter availability, neurocognitive function and their correlation in abstinent MDMA users,\" PubMed\n\nبعد عام\nيمنح عام من الامتناع الدماغ وقتًا طويلًا لتعافي معالجة السيروتونين، ويكون المزاج عادةً مستقرًا.\n\nإشارة التعافي\nيوفر عام كامل من الامتناع نافذة طويلة لتعافي نظام السيروتونين. وتُظهر أبحاث التصوير أن قدرة إعادة امتصاص السيروتونين تزداد مع الامتناع، ما يجعل التعافي الملحوظ لهذا النظام أبرز إشارة بيولوجية في هذه المرحلة.';

  @override
  String get methReferenceDay1 =>
      'انسحاب الميثامفيتامين: أول 24 ساعة\n\nالمصدر: McGregor et al., \"The nature, time course and severity of methamphetamine withdrawal,\" Addiction (2005)، PubMed\n\nمرحلة الانهيار\nيدفع الميثامفيتامين الدماغ إلى إفراز كميات كبيرة من الدوبامين؛ وعند التوقف عن التعاطي يصبح هذا النظام مستنزفًا. تابعت هذه الدراسة أعراض الانسحاب يوميًا خلال الأسابيع الثلاثة الأولى من الامتناع، ووجدت أن الشدة الإجمالية بلغت أقصاها خلال 24 ساعة من آخر تعاطٍ — وهي مرحلة «الانهيار»، أي التحول المفاجئ من التحفيز الشديد إلى الإرهاق الجسدي والنفسي.\n\nأعراض اليوم الأول\nوثقت الدراسة الأعراض التي تكون أشد في هذه المرحلة:\n• إرهاق شديد وزيادة النوم (فرط النوم)\n• زيادة الشهية، لأن الميثامفيتامين يثبطها بشدة\n• مزاج مكتئب وفقدان المتعة\n• رغبة قوية في التعاطي\n• قلق وتهيّج\n\nالسلامة الجسدية\nلا تكون متلازمة انسحاب الميثامفيتامين مهددة للحياة عادةً، لكن الأعراض المرتبطة بالاكتئاب التي قاستها الدراسة قد تكون شديدة في البداية وقد تشمل أفكارًا انتحارية. يُنصح بشدة بالإشراف الطبي، خاصةً عند الاستخدام الكثيف.\n\nيبدأ التحسن\nالنتيجة المشجعة هي أن الشدة تكون في أعلى مستوياتها في البداية ثم تنخفض. ومن ذروة الساعات الأربع والعشرين تبدأ الأعراض في التراجع تدريجيًا خلال الأيام التالية — أصعب نقطة هي البداية.';

  @override
  String get methReferenceDay3 =>
      'انسحاب الميثامفيتامين: اليوم الثالث — ما زلت في المرحلة الحادة\n\nالمصدر: McGregor et al., \"The nature, time course and severity of methamphetamine withdrawal,\" Addiction (2005)، PubMed\n\nالابتعاد عن الذروة\nوجدت الدراسة أن الشدة الإجمالية للانسحاب تبلغ ذروتها خلال أول 24 ساعة ثم تنخفض بنمط شبه خطي خلال المرحلة الحادة، التي تستمر نحو 7–10 أيام. في اليوم الثالث تكون قد تجاوزت أعلى نقطة، لكنك ما زلت بوضوح في المرحلة الحادة، وتظل الأعراض ملحوظة رغم أن الاتجاه العام نحو التحسن.\n\nأعراض اليوم الثالث\nالأعراض التي تابعتها الدراسة وما تزال مهمة الآن:\n• الاكتئاب وفقدان المتعة\n• رغبة قوية في التعاطي\n• صعوبة التركيز والتفكير بوضوح\n• اضطراب النوم، مع تناوب الأرق وفرط النوم\n• استمرار الإرهاق\n\nلماذا تشعر بهذا\nتعكس شدة الانسحاب حجم الاضطراب في نظام الدوبامين بعد التوقف عن الميثامفيتامين. وتكون الأعراض المرتبطة بالاكتئاب أوضح في هذه الأيام الأولى. والأهم أن الدراسة وجدت أن الشدة الإجمالية «تنخفض إلى مستويات قريبة من مجموعة الضبط بحلول نهاية الأسبوع الأول من الامتناع».\n\nهذا سيمر\nالأيام الأولى هي الأصعب، وتُظهر البيانات تراجعًا ثابتًا بعدها. إن فهم هذه الحالة بوصفها تأثيرًا مؤقتًا في الدماغ والجهاز العصبي، لا حالة دائمة، قد يساعد على تجاوزها.';

  @override
  String get methReferenceDay7 =>
      'أسبوع من دون ميثامفيتامين: نهاية المرحلة الحادة\n\nالمصدر: McGregor et al., \"The nature, time course and severity of methamphetamine withdrawal,\" Addiction (2005)، PubMed\n\nنهاية المرحلة الحادة\nهذه من أكثر نتائج البحث تشجيعًا. أفادت الدراسة بأن الشدة الإجمالية للانسحاب، بما فيها الأعراض المرتبطة بالاكتئاب، «انخفضت إلى مستويات قريبة من مجموعة الضبط بحلول نهاية الأسبوع الأول من الامتناع»، ما يشير إلى نهاية المرحلة الحادة. لقد تجاوزت الجزء الأشد انحدارًا.\n\nمرحلتان للانسحاب\nوصف الباحثون انسحاب الميثامفيتامين بأنه يتكون من:\n• مرحلة حادة تستمر نحو 7–10 أيام، تنخفض خلالها شدة الأعراض تدريجيًا من الذروة المبكرة\n• مرحلة تحت حادة تستمر أسبوعين إضافيين على الأقل، بأعراض أخف لكنها قد تستمر\n\nما يبقى في اليوم السابع\nعند دخول المرحلة تحت الحادة تصبح التحديات الغالبة نفسية أكثر من كونها جزءًا من الانهيار الحاد:\n• مزاج منخفض، لكنه أفضل بكثير من الأيام الأولى\n• رغبة في التعاطي، خاصةً عند التعرض للمثيرات\n• استمرار تعافي التركيز والذاكرة\n• استمرار انتظام النوم تدريجيًا\n\nالتعافي الجسدي مستمر\nمع انتهاء المرحلة الحادة تعود الشهية وتزداد الطاقة تدريجيًا بينما يتعافى الجسم من آثار الميثامفيتامين في النوم والتغذية والجهاز القلبي الوعائي.';

  @override
  String get methReferenceDay30 =>
      'شهر من دون ميثامفيتامين: المزاج يتحسن والرغبة ما تزال موجودة\n\nالمصدر: Zorick et al., \"Withdrawal symptoms in abstinent methamphetamine-dependent subjects,\" Addiction (2010)، PubMed Central\n\nمتابعة الأسابيع الخمسة الأولى\nتابعت هذه الدراسة أشخاصًا يعتمدون على الميثامفيتامين واستمروا في الامتناع حتى خمسة أسابيع، وقارنتهم بأشخاص أصحاء، ما أعطى صورة واضحة نسبيًا عما يحدث عند علامة الشهر.\n\nما الذي تحسن خلال شهر\n• «انخفضت أعراض الاكتئاب بدرجة كبيرة خلال أول أسبوعين من الامتناع إلى مستويات منخفضة ومستقرة»، وبحلول نهاية الأسبوع الرابع اقتربت من مستويات مجموعة الضبط الصحية، وإن لم تتطابق معها إحصائيًا\n• وصلت الأعراض النفسية والأعراض الشبيهة بالذهان إلى مستوى منخفض بحلول نهاية الأسبوع الثاني\nلذلك، بعد 30 يومًا يكون الاكتئاب الشديد المرتبط بالانسحاب المبكر قد تراجع إلى حد كبير — وهو تحسن حقيقي قابل للقياس.\n\nما الذي يبقى\nكانت الدراسة واضحة في أن عرضًا واحدًا يدوم أطول من غيره: الرغبة في التعاطي «استمرت عند مستوى أقل طوال خمسة أسابيع من الامتناع». تكون الرغبة أضعف مما كانت عليه في الأسبوع الأول لكنها لم تختفِ، ولذلك يبقى الشهر الأول فترة تحتاج إلى دعم مستمر.\n\nالخلاصة\nبعد شهر يكون الدماغ قد تعافى بما يكفي ليتحسن المزاج اليومي كثيرًا مقارنة ببداية الانسحاب. واستمرار بعض الرغبة في التعاطي جزء طبيعي من هذه المرحلة، وليس علامة على الفشل.';

  @override
  String get methReferenceDay90 =>
      'ثلاثة أشهر من دون ميثامفيتامين: بدأ التعافي — تحلَّ بالصبر\n\nالمصدر: Volkow et al., \"Loss of Dopamine Transporters in Methamphetamine Abusers Recovers with Protracted Abstinence,\" Journal of Neuroscience (2001)\n\nعن هذه الدراسة\nتابعت هذه الدراسة المهمة لتصوير الدماغ مستخدمي الميثامفيتامين مرتين — بعد نحو ثلاثة أشهر من التوقف ثم بعد نحو 14 شهرًا — لمعرفة كيف يتعافى نظام الدوبامين.\n\nموقع علامة الثلاثة أشهر\nبعد ثلاثة أشهر تكون مرحلة الانسحاب المبكر قد انتهت منذ مدة، ويكون تعافٍ أعمق لنظام الدوبامين جاريًا. ووجدت الدراسة نفسها لاحقًا أن البروتينات التي تعيد تدوير الدوبامين في مناطق المكافأة والحركة زادت بنحو 16% إلى 19% بعد 12–17 شهرًا من التوقف.\n\nماذا يعني ذلك لك\nبعد 90 يومًا يكون الانسحاب الحاد بعيدًا خلفك، ويتحسن المزاج والنوم، وقد يصبح الانخراط في العلاج أكثر فاعلية. لكن التعافي الأعمق لنظام الدوبامين يستمر خلال العام التالي. فإذا بقيت الدافعية والمتعة منخفضتين في الشهر الثالث، فهذا ينسجم مع مسار التعافي في الدراسة وليس علامة على الفشل.\n\nلماذا يستحق الانتظار\nأظهرت الدراسة نفسها أن الحفاظ على الامتناع يدعم التعافي: كلما طال الامتناع زاد تعافي ناقلات الدوبامين المقاس. ثلاثة أشهر هي الأساس، والتحسن يمكن أن يستمر بعدها.';

  @override
  String get methReferenceDay180 =>
      'ستة أشهر من دون ميثامفيتامين: يمكن للقلب أن يتعافى\n\nالمصدر: \"Stopping Drug Abuse Can Reverse Related Heart Damage,\" American College of Cardiology (2017)، تقرير عن دراسة في JACC: Heart Failure\n\nالميثامفيتامين والقلب\nالميثامفيتامين من أكثر المواد الترفيهية سمية للقلب. وقد يسبب ارتفاعًا شديدًا في ضغط الدم واضطرابات النظم، ومع الوقت قد يؤدي إلى اعتلال عضلة القلب المرتبط بالميثامفيتامين — أي ضعف عضلة القلب الذي قد ينتهي بفشل القلب.\n\nما الذي وجدته الدراسة\nأفادت الكلية الأمريكية لأمراض القلب عن مرضى لديهم اعتلال عضلة القلب المرتبط بالميثامفيتامين، وكانت قدرة القلب على الضخ منخفضة بدرجة كبيرة لدى الجميع. وكانت النتيجة المشجعة الأساسية أن التوقف «يمكن أن يعكس الضرر الذي يسببه العقار للقلب ويحسن وظيفة القلب». وحقق من توقفوا نتائج أفضل بوضوح من الذين استمروا في التعاطي، وشدد الباحثون على أن الاكتشاف المبكر «قد يمنع مزيدًا من تدهور اعتلال عضلة القلب».\n\nلماذا تهم ستة أشهر\nكل شهر من دون ميثامفيتامين يزيل التعرض السام المتكرر عن القلب ويمنح العضلة فرصة للتعافي. وبعد ستة أشهر يكون الجهاز القلبي الوعائي قد حصل على فترة طويلة ومتواصلة بعيدًا عن هذا الضرر — وهي الحالة التي ارتبطت بالتحسن في الدراسة.\n\nإشارة التعافي\nالنتيجة المدعومة بالأدلة واضحة: التوقف عن الميثامفيتامين قد يعكس بعض أذية القلب المرتبطة به ويحسن وظيفة القلب. وستة أشهر من دون التعرض المتكرر للمنبه تمنح القلب نافذة مهمة للتعافي.';

  @override
  String get methReferenceDay365 =>
      'عام من دون ميثامفيتامين: تعافٍ قابل للقياس في الدماغ\n\nالمصدر: Wang et al., \"Partial Recovery of Brain Metabolism in Methamphetamine Abusers After Protracted Abstinence,\" American Journal of Psychiatry (2004)، PubMed\n\nما الذي تظهره الصور\nفحصت دراسة تصوير الدماغ هذه مستخدمي الميثامفيتامين في بداية الامتناع ثم بعد 12–17 شهرًا. ووجدت تعافيًا حقيقيًا في الدماغ، مع اختلاف سرعة التعافي بين المناطق.\n\nالخبر الجيد: تعافي المناطق العميقة والتفكير\nبدأ المهاد، وهو مركز ترحيل عميق في الدماغ، يستخدم الطاقة بصورة أقرب إلى الطبيعي مع الامتناع الطويل. وارتبط هذا التعافي بتحسن الحركة والذاكرة اللفظية، لذلك انعكس التحسن في الصور على وظائف التفكير والذاكرة.\n\nدوائر المكافأة تتعافى ببطء أكبر\nبعد 12–17 شهرًا أظهر مركز الترحيل العميق تعافيًا واضحًا ارتبط بحركة وذاكرة لفظية أفضل. كما واصلت أنظمة المكافأة والدافعية التحسن، لتصبح صورة العام الأول صورة تعافٍ كبير في التفكير والذاكرة.\n\nماذا يعني ذلك عند عام\nبعد عام يمكن أن يكون التفكير والذاكرة أفضل بكثير من بداية التعافي — تحسنًا واضحًا قابلًا للقياس. وإذا بقيت الدافعية أو القدرة على الشعور بالمتعة متأخرة أحيانًا، فهذا ينسجم مع نتائج الدراسة وليس فشلًا شخصيًا: قد تتعافى دوائر المكافأة ببطء أكبر وتبقى بعض الفروق بعد أكثر من عام.';

  @override
  String get methReferenceDay420 =>
      '14 شهرًا من دون ميثامفيتامين: تحسن مؤشر الدوبامين\n\nالمصدر: Volkow et al., \"Loss of Dopamine Transporters in Methamphetamine Abusers Recovers with Protracted Abstinence,\" Journal of Neuroscience (2001)\n\nالنتيجة الرئيسية\nفحصت هذه الدراسة المهمة لتصوير الدماغ مستخدمي الميثامفيتامين في بداية الامتناع ثم بعد نحو 12–17 شهرًا. وزادت البروتينات التي تعيد تدوير الدوبامين بنحو 16% إلى 19% في مناطق المكافأة والحركة، ووصلت إلى مستويات لم تعد تختلف بدرجة مهمة عن الأصحاء. وارتبط الامتناع الأطول بتعافٍ أكبر.\n\nلماذا تهم ناقلات الدوبامين\nتعيد هذه البروتينات تدوير الدوبامين بعد إفرازه. ويستنزف الميثامفيتامين هذه البروتينات، ما يضعف تنظيم نظام الدوبامين. وعودتها للارتفاع بعد نحو 14 شهرًا علامة حقيقية قابلة للقياس على التعافي.\n\nإشارة التعافي\nبعد 12–17 شهرًا زادت بروتينات إعادة تدوير الدوبامين في مناطق المكافأة والحركة بنحو 16% إلى 19% ووصلت إلى مستويات مجموعة الضبط الصحية. أي أن نظام الدوبامين أظهر تعافيًا قابلًا للقياس نحو الطبيعي، مع استمرار تحسن التفكير والذاكرة والحركة.\n\nماذا يعني ذلك عند 14 شهرًا\nيتحرك نظام الدوبامين بصورة قابلة للقياس نحو الحالة الطبيعية — وهذا سبب حقيقي للتفاؤل. لكن التعافي الوظيفي الكامل، مثل الذاكرة والدافعية والتحكم الحركي الدقيق، قد يتأخر عن نتائج التصوير ويستمر في التحسن مع استمرار الامتناع.';

  @override
  String get methReferenceDay730 =>
      'عامان من دون ميثامفيتامين: التفكير والمزاج يواصلان التحسن\n\nالمصدر: Iudicello et al., \"Longer Term Improvement in Neurocognitive Functioning and Affective Distress Among Methamphetamine Users Who Achieve Stable Abstinence,\" Journal of Clinical and Experimental Neuropsychology (2010)، PubMed Central\n\nتعافٍ يستمر بعد العام الأول\nتابعت هذه الدراسة مستخدمي الميثامفيتامين لنحو 13 شهرًا وقارنت من حافظوا على الامتناع بمن استمروا في التعاطي وبمجموعة ضبط صحية. أدى الامتناع المستقر إلى تحسن الأداء المعرفي العام وانخفاض الضيق العاطفي، مع استمرار المكاسب بعد العام الأول.\n\nما الذي يتحسن\n• وصل الأداء المعرفي العام لدى من حافظوا على الامتناع إلى مستوى مجموعة الضبط الصحية، بينما ظل من استمروا في التعاطي يعانون من قصور واضح\n• كانت أكبر المكاسب في سرعة المعالجة والقدرة الحركية، خاصةً لدى من كانت لديهم أكبر صعوبات في البداية\n• تحسن المزاج بوضوح: فقط من حافظوا على الامتناع أظهروا تحسنًا مهمًا في الاكتئاب والمزاج العام\n\nإشارة التعافي\nلحق من حافظوا على الامتناع بمجموعة الضبط الصحية في الأداء المعرفي العام وأبلغوا عن ضيق عاطفي أقل. ويمكن أن يستمر تحسن التعلم اللفظي والذاكرة العاملة والتخطيط والتركيز بعد العام الأول، لذلك يواصل مسار التعافي امتداده إلى العام الثاني.\n\nبعد عامين\nالرسالة المدعومة بالأدلة: استمرار الامتناع يواصل تحقيق فوائد بعد العام الأول بوقت طويل — تفكير أوضح، مزاج أفضل، ووظائف تتحسن تدريجيًا — حتى إن احتاجت بعض المجالات وقتًا أطول للتعافي.';

  @override
  String get methMilestone1095Title => 'ثلاث سنوات - تعافٍ راسخ';

  @override
  String get methMilestone1095Description =>
      'ثلاث سنوات من دون الميثامفيتامين تعني تغييرًا مستمرًا يُقاس بالسنوات لا بالأسابيع. الإنجاز هنا هو الاستمرار نفسه، فقد أتيحت لروتين التعافي ودعمه سنة كاملة إضافية ليترسخا.';

  @override
  String get methReferenceDay1095 =>
      'ثلاث سنوات - تعافٍ راسخ\n\nالمصدر: Cao et al., \"Magnitude and Abstinence Trajectories of Neurocognitive Deficits in Methamphetamine Use Disorder: A Systematic Review and Meta-analysis,\" Journal of Addiction Medicine (2026), PubMed\n\nجمعت مراجعة منهجية وتحليل تلوي نُشرا عام 2026 نتائج 68 دراسة مستقلة شملت 9,045 مشاركًا. لم تتجاوز فترات الامتناع المستخدمة في تحليلات المسار 280 يومًا، وصُنفت درجة اليقين في الأدلة بأنها منخفضة جدًا. لذلك لا يمكن لهذه الأدلة تحديد موعد بيولوجي للتعافي عند هذه الذكرى.\n\nثلاث سنوات من دون الميثامفيتامين تعني تغييرًا مستمرًا يُقاس بالسنوات لا بالأسابيع. الإنجاز هنا هو الاستمرار نفسه، فقد أتيحت لروتين التعافي ودعمه سنة كاملة إضافية ليترسخا.';

  @override
  String get methMilestone1460Title => 'أربع سنوات - أسس راسخة';

  @override
  String get methMilestone1460Description =>
      'أربع سنوات مدة راسخة من التغيير. لا تحدد الأبحاث نقطة نهائية لتعافي الدماغ عند أربع سنوات، لذلك يحتفي هذا الإنجاز بسنة أخرى كاملة من حماية ما بنيته.';

  @override
  String get methReferenceDay1460 =>
      'أربع سنوات - أسس راسخة\n\nالمصدر: Cao et al., \"Magnitude and Abstinence Trajectories of Neurocognitive Deficits in Methamphetamine Use Disorder: A Systematic Review and Meta-analysis,\" Journal of Addiction Medicine (2026), PubMed\n\nجمعت مراجعة منهجية وتحليل تلوي نُشرا عام 2026 نتائج 68 دراسة مستقلة شملت 9,045 مشاركًا. لم تتجاوز فترات الامتناع المستخدمة في تحليلات المسار 280 يومًا، وصُنفت درجة اليقين في الأدلة بأنها منخفضة جدًا. لذلك لا يمكن لهذه الأدلة تحديد موعد بيولوجي للتعافي عند هذه الذكرى.\n\nأربع سنوات مدة راسخة من التغيير. لا تحدد الأبحاث نقطة نهائية لتعافي الدماغ عند أربع سنوات، لذلك يحتفي هذا الإنجاز بسنة أخرى كاملة من حماية ما بنيته.';

  @override
  String get methMilestone1825Title => 'خمس سنوات - تغيير دائم';

  @override
  String get methMilestone1825Description =>
      'خمس سنوات من دون الميثامفيتامين إنجاز كبير طويل الأمد. لا يستطيع العلم أن يَعِد بنقطة بيولوجية نهائية عند خمس سنوات؛ المؤكد هو خمس سنوات من التغيير المستمر الجدير بالاحتفاء.';

  @override
  String get methReferenceDay1825 =>
      'خمس سنوات - تغيير دائم\n\nالمصدر: Cao et al., \"Magnitude and Abstinence Trajectories of Neurocognitive Deficits in Methamphetamine Use Disorder: A Systematic Review and Meta-analysis,\" Journal of Addiction Medicine (2026), PubMed\n\nجمعت مراجعة منهجية وتحليل تلوي نُشرا عام 2026 نتائج 68 دراسة مستقلة شملت 9,045 مشاركًا. لم تتجاوز فترات الامتناع المستخدمة في تحليلات المسار 280 يومًا، وصُنفت درجة اليقين في الأدلة بأنها منخفضة جدًا. لذلك لا يمكن لهذه الأدلة تحديد موعد بيولوجي للتعافي عند هذه الذكرى.\n\nخمس سنوات من دون الميثامفيتامين إنجاز كبير طويل الأمد. لا يستطيع العلم أن يَعِد بنقطة بيولوجية نهائية عند خمس سنوات؛ المؤكد هو خمس سنوات من التغيير المستمر الجدير بالاحتفاء.';

  @override
  String get nitrousOxideReferenceDay1 =>
      'اليوم الأول: انتهى الغاز، لكن شاهد B12\n\nالمصدر: كنوف ومعاني، \"أكسيد النيتروز\"، StatPearls (NCBI Bookshelf)\n\nمدى سرعة مسحه\nيبدأ مفعول أكسيد النيتروز سريعًا - من 2 إلى 5 دقائق - ويخرج من الجسم بنفس السرعة بمجرد التوقف عن استنشاقه. بحلول اليوم، لن يبقى أي من الغاز نفسه في نظامك.\n\nالخطر الحقيقي ليس الغاز\nما يهم بعد التوقف هو ما قد يحدثه التعرض المتكرر بالفعل. يقوم أكسيد النيتروز بتعطيل إنزيم الميثيونين سينسيز، وهو إنزيم يعتمد على فيتامين ب12. تشير StatPearls إلى أن التعرض المتكرر - سواء كان مهنيًا أو ترفيهيًا - يمكن أن يؤدي إلى فقر الدم الضخم الأرومات وخلل في المخ والأعصاب، وفي حالات نادرة، انحطاط الحبل الشوكي.\n\nإذا كنت تستخدم بكثرة أو في كثير من الأحيان\nلم يتم توثيق أن أكسيد النيتروز يسبب متلازمة الانسحاب الجسدي كما تفعل المواد الأفيونية أو الكحول، لذا فإن اليوم الأول لا يتعلق بطلب جسمك للدواء. يتعلق الأمر بالبدء في الانتباه إلى الأعراض المرتبطة بـ B12 - والتي سيتم تناولها في المعالم القليلة التالية - والتحقق من ظهورها في حالة ظهورها.';

  @override
  String get nitrousOxideReferenceDay3 =>
      '72 ساعة: لا يوجد انسحاب جسدي، ولكن انتبه للأعراض العصبية\n\nالمصدر: كنوف ومعاني، ستات بيرلز؛ تيكاريا وآخرون. (2026)، كيوريوس\n\nعلى عكس المواد الأفيونية أو الكحول، لم يتم توثيق أن أكسيد النيتروز يسبب متلازمة الانسحاب الجسدي. الحوافز في هذه المرحلة هي العادة والرغبة، وليس الجسم الذي يطلب الدواء ليقوم بوظيفته.\n\nانتبه لهذه\nوجدت مراجعة منهجية لـ 1809 حالة من حالات أكسيد النيتروز الترفيهية (Tikaria et al., 2026) أن أعراض الدماغ والأعصاب - وخاصة الوخز أو التنميل (تنمل الحس) - كانت العلامة الأكثر شيوعًا للضرر المرتبط بـ B12، وغالبًا ما تظهر حتى عندما تبدو اختبارات الدم القياسية طبيعية. كما تم الإبلاغ عن مشاكل في المشي والضعف.\n\nإذا لاحظت أيًا من هذه\nاطلب المراجعة الطبية. وجدت نفس المراجعة أن اختبارات الدم القياسية (الهيموجلوبين، المصل B12) غابت عن حصة كبيرة من المرضى المتأثرين - اختبارات حمض الميثيل مالونيك (MMA) والهوموسيستين أكثر حساسية ويجب طلبها على وجه التحديد إذا كشفت عن استخدام أكسيد النيتروز.';

  @override
  String get nitrousOxideReferenceDay7 =>
      'أسبوع واحد: قم بإجراء الاختبار إذا كنت تستخدمه بكثرة\n\nالمصدر: تيكاريا وآخرون. (2026)، “الإرث السام لاستخدام أكسيد النيتروز الترفيهي”، كوريوس\n\nما تظهره الأدلة\nوجدت هذه المراجعة المنهجية أن نقص فيتامين ب12 الناتج عن أكسيد النيتروز غالبًا ما يكون \"وظيفيًا\" - حيث بدا مصل B12 طبيعيًا في ما يقرب من نصف المرضى المصابين، حتى عندما كان لديهم تلف حقيقي في الدماغ والأعصاب. كان الهوموسيستين وMMA غير طبيعيين في كثير من الأحيان (84% و73% من المرضى الذين تم اختبارهم على التوالي) وهما العلامات الأكثر موثوقية.\n\nماذا تفعل\nإذا كان استخدامك كثيفًا أو متكررًا، فإن التوقف لمدة أسبوع هو وقت معقول لرؤية الطبيب وطلب اختبار الهوموسيستين وMMA على وجه التحديد - وليس فقط مستوى B12 القياسي - خاصة إذا كان لديك أي وخز، أو خدر، أو مشاكل في التوازن، أو ضعف غير مبرر.\n\nيعد تعافي الدماغ أمرًا شائعًا بعد التوقف عن النيتروز وعلاج فيتامين ب 12: تشير سلسلة سريرية كبيرة إلى تحسن جزئي أو كامل في معظم المرضى الذين تتم متابعتهم، مع استمرار التعافي خلال الأشهر الأولى بعد العلاج.';

  @override
  String get nitrousOxideReferenceDay14 =>
      'أسبوعين: أعراض الدماغ والأعصاب تستحق المتابعة\n\nالمصدر: تيكاريا وآخرون. (2026)، كيوريوس؛ كنوف ومعاني، ستات بيرلز\n\nما تم الإبلاغ عنه\nتقارير الحالة والمسلسلات التي استعرضها Tikaria et al. وصف تلف الأعصاب المرتبط بأكسيد النيتروز والذي يظهر على شكل فقدان حسي، وترنح المشي، وأحيانًا ضعف يؤثر على المشي - وهي نتائج يمكن أن تشبه حالات الدماغ والأعصاب الأخرى، ويتم تفويتها أحيانًا إذا لم يتم ذكر استخدام أكسيد النيتروز للطبيب.\n\nإشارة الاسترداد على الجداول الزمنية\nولم يذكر أي من المصدر المدة التي يستغرقها التعافي عادةً بمجرد توقف الاستخدام ومعالجة أي نقص. تصف تقارير الحالة نطاقًا واسعًا من النتائج — بدءًا من التعافي الكامل وحتى العجز الدائم — اعتمادًا إلى حد كبير على مقدار الضرر الذي حدث قبل التشخيص. الأمر الثابت عبر الأدبيات هو أن العلاج المبكر يؤدي إلى نتائج أفضل.\n\nإذا لم يتم فحصك\nلا تزال فترة الراحة لمدة أسبوعين هي الوقت المناسب لإجراء فحوصات الدم، حتى بدون ظهور أعراض - وخاصة الهوموسيستين وMMA بدلاً من مصل B12 وحده.';

  @override
  String get nitrousOxideReferenceDay30 =>
      'شهر واحد: العادة والرغبة، وليس الاعتماد الجسدي\n\nالمصدر: كنوف ومعاني، \"أكسيد النيتروز\"، StatPearls (NCBI Bookshelf)\n\nأين تقف\nلا تصف StatPearls أكسيد النيتروز بأنه ينتج متلازمة الاعتماد الجسدي، لذا فإن التوقف لمدة شهر يعني أن أي حوافز باقية تتعلق بالعادة أو السياق الاجتماعي أو الملل وليس الجسم الذي لا يزال يتكيف مع غياب الدواء.\n\nسؤال B12\nإذا تم اختبارك وعلاجك من نقص فيتامين B12، فإن شهرًا واحدًا يعد نقطة معقولة لطبيبك للتحقق مما إذا كانت مستوياتك – وأي أعراض – قد استجابت. إذا لم يتم اختبارك واستخدامك بكثرة، فلا يزال الأمر يستحق السؤال.\n\nما هو محمي\nكل شهر لا تستخدمه هو شهر لا تضيفه إلى أي تعطيل موجود لسينثاز الميثيونين أو خطر الدماغ والأعصاب الذي يأتي معه.';

  @override
  String get nitrousOxideReferenceDay90 =>
      'ثلاثة أشهر: حان وقت إعادة الفحص، إذا لم تقم بذلك\n\nالمصدر: تيكاريا وآخرون. (2026)، “الإرث السام لاستخدام أكسيد النيتروز الترفيهي”، كوريوس\n\nما نعرفه - ولا نعرفه\nتم بناء قاعدة البحث هذه من تقارير الحالات وسلاسل الحالات، وليس من دراسات التعافي الخاضعة للرقابة، لذلك لا يوجد جدول زمني منشور موثوق لكيفية حل الأعراض خلال ثلاثة أشهر على وجه التحديد. ما تظهره الأدلة هو أن النتائج تختلف على نطاق واسع - فبعض المرضى الذين يعانون من نقص خفيف تم اكتشافه مبكرًا يتعافون تمامًا، في حين أن أولئك الذين يعانون من تأخر التشخيص أو تلف الأعصاب الشديد يمكن أن يعانون من عجز دائم.\n\nالجزء القابل للتنفيذ\nإذا كنت تعاني من أي أعراض في الدماغ والأعصاب ولم تقم بإجراء متابعة للدم أو مراجعة متخصصة، فإن التوقف لمدة ثلاثة أشهر يعد نقطة معقولة للقيام بذلك. إذا تم علاجك وتحسنت، فهذا وقت معقول للتأكد من استمرار هذا الاتجاه مع طبيبك.\n\nالابتعاد عن الأمور الأكثر أهمية\nتتفق المراجعة حول شيء واحد: التعرض المستمر يحافظ على تعطيل فيتامين B12 ويزيد من المخاطر. عدم الاستخدام هو العامل الأكبر لصالحك.';

  @override
  String get nitrousOxideReferenceDay365 =>
      'سنة واحدة: أفضل حماية هي الاستمرار في عدم الاستخدام\n\nالمصدر: Knuf & Maani، StatPearls؛ Tikaria et al. (2026)، Cureus\n\nإلى أين تصل الأدلة فعلاً\nلا يَعِد أي من المصدرين بجدول زمني محدد للتعافي. فالأدبيات حول أكسيد النيتروز ونقص فيتامين B12 مبنية تقريباً بالكامل على تقارير حالات فردية، لا على دراسات متابعة طويلة الأمد. أما الآلية فمعروفة جيداً: أكسيد النيتروز يعطّل فيتامين B12 في كل مرة يُستخدم فيها، والتوقف يزيل هذا الضرر المستمر الناتج عن التعرض.\n\nإذا كانت لديك أعراض مرتبطة بالنقص\nتصف تقارير الحالات نتائج متفاوتة جداً، من التعافي الكامل إلى استمرار الأعراض العصبية، ويرتبط ذلك بدرجة كبيرة بحجم الضرر ومدى سرعة بدء العلاج. إذا استمرت الأعراض بعد سنة، فهذا سبب لمواصلة المتابعة مع طبيب أعصاب، وليس دليلاً على أن التحسن لم يعد ممكناً؛ فقد يستمر تعافي الأعصاب فترة طويلة.\n\nما هو مؤكد\nسنة من دون أكسيد النيتروز هي سنة من دون مزيد من تعطيل إنزيم ميثيونين سينثاز. وهذه هي النقطة التي يدعمها المصدران بوضوح.';

  @override
  String get opioidReferenceDay1 =>
      'انسحاب المواد الأفيونية: اليوم الأول\n\nالمصدر: \"المبادئ التوجيهية السريرية لإدارة الانسحاب وعلاج الاعتماد على المخدرات في الأماكن المغلقة\"، منظمة الصحة العالمية (2009)، على رف كتب NCBI\n\n⚠ ملاحظة السلامة\nنادرًا ما يكون انسحاب المواد الأفيونية مميتًا لدى الأفراد الأصحاء، ولكنه يسبب ضائقة جسدية شديدة وينطوي على خطر كبير للانتكاس. يعد الانتكاس بعد فترة من الامتناع خطيرًا بشكل خاص لأن التحمل ينخفض ​​بسرعة - باستخدام نفس الجرعة كما كان قبل الامتناع عن استخدام المواد الأفيونية يمكن أن يسبب جرعة زائدة مميتة. يوصى بشدة بالإشراف الطبي والعلاج الناهض للمواد الأفيونية.\n\nعندما يبدأ الانسحاب\nيحدد الجدول الزمني للانسحاب من منظمة الصحة العالمية التوقيت حسب نوع المواد الأفيونية:\n• المواد الأفيونية قصيرة المفعول (الهيروين والأوكسيكودون): يبدأ ظهورها بعد 8 إلى 24 ساعة من آخر استخدام، وتستمر من 4 إلى 10 أيام\n• المواد الأفيونية طويلة المفعول (الميثادون): تبدأ من 12 إلى 48 ساعة، وتستمر من 10 إلى 20 يومًا\n\nأعراض اليوم الأول\nتسرد إرشادات منظمة الصحة العالمية السمات المبكرة لانسحاب المواد الأفيونية:\n• القلق والانفعالات\n• تشنجات وأوجاع في العضلات\n• إفرازات مائية من العين والأنف\n• التثاؤب والتعرق\n• الأرق، مع الهبات الساخنة والباردة\n• الغثيان المبكر\n\nلماذا تشعر بالسوء؟\nينظم النظام الأفيوني الألم والتوتر والرفاهية العاطفية والراحة الأساسية. يؤدي استخدام المواد الأفيونية على المدى الطويل إلى تثبيط إنتاج المواد الأفيونية في الجسم (الإندورفين). عندما تتم إزالة المواد الأفيونية، يُترك الجسم بدون نظام الراحة الطبيعي، حيث يعاني من الألم والقلق والضيق بمستوى يعكس عمق هذا الكبت. تنصح إرشادات منظمة الصحة العالمية بالرعاية الداعمة، بما في ذلك شرب 2-3 لتر من الماء يوميًا والمراقبة 3-4 مرات يوميًا.';

  @override
  String get opioidReferenceDay7 =>
      'التوقف عن تناول المواد الأفيونية لمدة أسبوع: انخفاض أعراض الذروة\n\nالمصدر: \"المبادئ التوجيهية السريرية لإدارة الانسحاب وعلاج الاعتماد على المخدرات في الأماكن المغلقة\"، منظمة الصحة العالمية (2009)، على رف كتب NCBI\n\nالذروة والانحدار\nيحدد الجدول الزمني لمنظمة الصحة العالمية فترة انسحاب المواد الأفيونية قصيرة المفعول خلال 4 إلى 10 أيام، مع ظهور الأعراض مبكرًا ثم تتراجع خلال تلك الفترة. بنهاية الأسبوع الأول:\n• يتم حل مشكلة القيء والإسهال إلى حد كبير\n• تشنجات العضلات أقل حدة\n• يتم تقليل الضائقة الجسدية بشكل ملموس\n\nما تبقى في اليوم السابع\nفي حين أن الأعراض الجسدية الحادة آخذة في التحسن، إلا أن هناك تحديات كبيرة لا تزال قائمة:\n• الأرق — يعد اضطراب النوم أحد أكثر أعراض انسحاب المواد الأفيونية استمرارًا\n• المزاج المكتئب والتسطح العاطفي\n• التعب والضعف\n• الرغبة الشديدة\n• القلق\n\nالانسحاب بعد الحاد\nبعد فترة الانسحاب الأولى، يمكن أن تستمر مشاكل النوم وتغير المزاج وموجات الرغبة الشديدة لمدة أسابيع أو أشهر. الدعم المستمر هو الأكثر أهمية خلال مرحلة التعافي الأطول هذه.\n\nالعلاج بالناهضات الأفيونية\nتصف إرشادات منظمة الصحة العالمية الميثادون والبوبرينورفين كعلاجات فعالة تقلل من شدة الانسحاب وتدعم التعافي. تعمل هذه الأدوية أيضًا على تقليل الوفيات الناجمة عن اضطراب استخدام المواد الأفيونية، ويستخدمها العديد من الأشخاص في مرحلة التعافي الناجحة على المدى الطويل طوال مرحلة التعافي المبكر.';

  @override
  String get opioidReferenceDay14 =>
      'توقف عن تناول المواد الأفيونية لمدة أسبوعين: بدأت أنماط النوم في التحسن\n\nالمصدر: أبحاث الصيدلة التي راجعها النظراء حول المواد الأفيونية والنوم\n\nاتصال المواد الأفيونية بالنوم\nتتناول هذه الورقة البحثية العلاقة ثنائية الاتجاه بين استخدام المواد الأفيونية واضطراب النوم. توثق النتائج أن المواد الأفيونية تعطل بشدة بنية النوم الطبيعية من خلال آليات متعددة:\n• قمع الموجة البطيئة (العميقة) من النوم\n• اضطراب نوم حركة العين السريعة\n• التسبب في اضطراب التنفس أثناء النوم (انقطاع التنفس المركزي أثناء النوم)\n• تعطيل تنظيم إيقاع الساعة البيولوجية\n\nحلقة مفرغة\nيسلط البحث الضوء على الطبيعة الثنائية الاتجاه للمشكلة: استخدام المواد الأفيونية يعطل النوم، وقلة النوم تزيد من حساسية الألم وشدة الرغبة، مما يؤدي إلى المزيد من استخدام المواد الأفيونية. إن التخلص من الاعتماد على المواد الأفيونية يعني أيضًا كسر دورة اضطراب النوم هذه.\n\nالنوم في أسبوعين\nبحلول 14 يومًا من الامتناع عن تناول المواد الأفيونية، يبدأ النوم في العودة إلى طبيعته:\n• انقطاع التنفس المركزي أثناء النوم (إن وجد) يختفي خلال أيام\n• بدأ النوم العميق ذو الموجة البطيئة في التعافي\n• يعود نوم حركة العين السريعة إلى النسبة الطبيعية\n• أصبحت بداية النوم أكثر موثوقية\n\nيظل النوم تحديًا كبيرًا للعديد من الأشخاص خلال أسبوعين، لكن المسار يتحسن بشكل واضح. النوم الأفضل يحسن المزاج بشكل مباشر، ويقلل الرغبة الشديدة، ويدعم التفكير الواضح اللازم للتعافي.';

  @override
  String get opioidReferenceDay30 =>
      'التوقف عن تناول المواد الأفيونية لمدة شهر: يبدأ التفكير والذاكرة في التعافي\n\nالمصدر: مايو كلينك\n\nفهم اضطراب استخدام المواد الأفيونية\nتوضح مايو كلينيك أن المواد الأفيونية ترتبط بمستقبلات في جميع أنحاء الدماغ والجسم، مما يؤدي إلى تخفيف الألم والنشوة والنعاس. ومع الاستخدام المتكرر، يستجيب الدماغ بقوة أقل وينتج عددًا أقل من المواد الكيميائية الشبيهة بالمواد الأفيونية. وهذا يخلق الاعتماد الجسدي.\n\nالتفكير والذاكرة في شهر واحد\nوبعد 30 يومًا، حدث تعافي ملموس في التفكير والذاكرة. لقد انقشع أسوأ ضباب في الدماغ، وبدأ الجزء الأمامي من الدماغ - الذي يتولى التخطيط وضبط النفس - في التعافي:\n• عملية صنع القرار آخذة في التحسن\n• الذاكرة العاملة تتعافى\n• زيادة سرعة المعالجة\n• التركيز أكثر موثوقية\n\nنظام الاندورفين\nوبعد مرور شهر واحد، يتعافى نظام الإندورفين الطبيعي في الدماغ بشكل نشط: فهو ينتج المزيد من المواد الكيميائية الشبيهة بالمواد الأفيونية الخاصة به ويستجيب بشكل طبيعي مرة أخرى. يستمر التسطيح العاطفي وانخفاض تحمل الألم في التحسن مع استمرار هذا التعافي.\n\nمنع الانتكاس\nتؤكد Mayo Clinic أن شهرًا واحدًا من الرصانة لا يعني أن خطر الانتكاس قد انتهى، بل يظل مرتفعًا. لقد انخفض التسامح بشكل ملحوظ، مما يعني أن الانتكاس باستخدام الجرعات السابقة ينطوي على مخاطر خطيرة لجرعة زائدة.';

  @override
  String get opioidReferenceDay60 =>
      'توقف عن تناول المواد الأفيونية لمدة شهرين: تبدأ دوائر التوتر في الدماغ بالاستقرار\n\nالمصدر: \"المرونة العصبية لللوزة الدماغية الممتدة في انسحاب المواد الأفيونية والامتناع عن تناول المواد الأفيونية لفترة طويلة،\" الحدود في علم الصيدلة (2023)\n\nمن أين تأتي المشاعر السلبية\nتوضح هذه المراجعة كيف أن استخدام المواد الأفيونية على المدى الطويل يغير دوائر التوتر والخوف في الدماغ. أثناء الانسحاب، تصبح هذه الدوائر مفرطة النشاط بينما تنخفض إشارات الدوبامين في دوائر المكافأة. يساعد هذا المزيج في تفسير القلق، وانخفاض الحالة المزاجية، والرغبة الشديدة في التعافي المبكر.\n\nلماذا شهرين يجلب الإغاثة\nومن الأهمية بمكان أن توثق المراجعة أن بعض هذه التغييرات يمكن عكسها. في النماذج الحيوانية، يوصف فقدان كثافة العمود الفقري في القشرة المتكئة بأنه \"انخفاض دائم ولكن قابل للعكس\"، ويعود إلى قيم ما قبل الدواء على مدار أسبوعين. مع إعادة تنظيم دوائر التوتر والمكافأة هذه، يخف الأساس الميكانيكي للاضطراب العاطفي في مرحلة التعافي المبكر - بما يتوافق مع انخفاض التفاعل والمزاج الأكثر ثباتًا الذي أبلغ عنه العديد من الأشخاص بعد حوالي شهرين.\n\nإشارة التعافي\nتُظهِر التغيرات العكسية في كثافة العمود الفقري ودائرة الإجهاد الموثقة في هذه الأدبيات عملية انتعاش بيولوجية حقيقية: فالدوائر التي تحرك الحالة العاطفية السلبية للاعتماد تعود إلى حالتها السابقة للمخدرات أثناء الامتناع عن استخدام المواد الأفيونية.';

  @override
  String get opioidReferenceDay90 =>
      'ثلاثة أشهر من التوقف عن المواد الأفيونية: مكافأة الكيمياء بدأت في التعافي\n\nالمصدر: \"التعافي الهيكلي والوظيفي للدماغ لدى الأفراد الذين يعانون من اضطرابات تعاطي المخدرات أثناء الامتناع عن استخدام المواد الأفيونية: مراجعة لدراسات التصوير العصبي الطولية،\" الاعتماد على المخدرات والكحول (2022)، في PubMed Central\n\nالدوبامين والمواد الأفيونية\nتعمل المواد الأفيونية على تحفيز إطلاق الدوبامين في نظام المكافأة في الدماغ. الاستخدام طويل الأمد يترك هذا النظام مستنزفًا: في إحدى دراسات مسح الدماغ، كانت البروتينات التي تعيد تدوير الدوبامين أقل بحوالي 30٪ من المستويات الصحية في البداية. ويساعد ذلك في تفسير فقدان المتعة الذي يظهر في اضطراب استخدام المواد الأفيونية والشفاء المبكر.\n\nالتعافي تدريجي\nجمعت هذه المراجعة الدراسات الطولية التي أعادت فحص نفس الأشخاص بشأن الامتناع عن استخدام المواد الأفيونية. تعافى العجز في ناقل الدوبامين بنسبة 20% تقريبًا خلال 6-12 شهرًا من الامتناع عن استخدام المواد الأفيونية، وبعض تشوهات المادة الرمادية الأمامية والمادة البيضاء التي شوهدت في الانسحاب المبكر لم تعد قابلة للاكتشاف بعد حوالي شهر. بعد مرور ثلاثة أشهر، تكون قد وصلت مبكرًا إلى منحنى التعافي: حيث يتم إصلاح أنظمة المكافأة والجبهة بشكل ملموس، ولكنها لم تنته بعد.\n\nما تجربة الناس\nومع تعافي هذه الدوائر، يلاحظ العديد من الأشخاص في حوالي 90 يومًا ما يلي:\n• المزيد من الاستمتاع الحقيقي بالأنشطة والطعام والعلاقات\n• انخفاض الرغبة الشديدة مقارنة بالشفاء المبكر\n• تفكير أكثر وضوحا واتخاذ قرارات أفضل\n\nإشارة التعافي\nيُظهر التصوير البشري الطولي ارتفاع توافر ناقل الدوبامين خلال فترة تتراوح من 6 إلى 12 شهرًا من الامتناع عن استخدام المواد الأفيونية، في حين تبدأ التشوهات الأمامية في المادة الرمادية والبيضاء في العودة إلى طبيعتها قبل ذلك بكثير. وبعد 90 يومًا، يتم بالفعل تحقيق تعافي دماغي قابل للقياس.';

  @override
  String get opioidReferenceDay180 =>
      'ستة أشهر من التوقف عن تناول المواد الأفيونية: يبدأ الجهاز المناعي في التعافي\n\nالمصدر: \"آثار تحمل المواد الأفيونية والانسحاب منها على الجهاز المناعي،\" مجلة علم الأدوية المناعي العصبي (2006)، على PubMed\n\nالمواد الأفيونية والجهاز المناعي\nتوضح هذه المراجعة أن استخدام المواد الأفيونية على المدى الطويل يضعف جهاز المناعة بعدة طرق:\n• التأثير الأفيوني المباشر على الخلايا المناعية (الخلايا التائية، والخلايا القاتلة الطبيعية، والبلاعم)\n• تعطل المواد الكيميائية الإشارات المناعية\n• خلل في محور الوطاء-النخامى-الكظر (HPA)\n• زيادة القابلية للإصابة بالعدوى\n\nإشارة التعافي\nتعمل المواد الأفيونية على المدى الطويل على تثبيط عدة أجزاء من الجهاز المناعي. وبعد ستة أشهر من التوقف عن تناول المواد الأفيونية، يكون هذا القمع المستمر قد اختفى لمدة نصف عام وتتم إعادة بناء الوظيفة المناعية بشكل نشط نحو وضعها الطبيعي.\n\nماذا تعني ستة أشهر\nستة أشهر بدون استخدام المواد الأفيونية تمنح الخلايا المناعية، والإشارات المناعية، ونظام الإجهاد في الجسم وقتًا مستدامًا للتعافي نحو الوضع الطبيعي.\n\nلماذا لا يزال هذا مهمًا؟\nوينطبق هذا بشكل خاص على الأشخاص الذين حقنوا المواد الأفيونية، والذين واجهوا مخاطر عدوى إضافية مثل فيروس نقص المناعة البشرية والتهاب الكبد الوبائي سي. إن إزالة المواد الأفيونية، وتحسين التغذية، والحفاظ على الامتناع عن استخدام المواد الأفيونية، يمنح الجهاز المناعي الظروف التي يحتاجها لمواصلة التعافي.';

  @override
  String get opioidReferenceDay365 =>
      'سنة واحدة من المواد الأفيونية: بنية الدماغ واستعادة الكيمياء\n\nالمصدر: \"التعافي الهيكلي والوظيفي للدماغ لدى الأفراد الذين يعانون من اضطرابات تعاطي المخدرات أثناء الامتناع عن استخدام المواد الأفيونية: مراجعة لدراسات التصوير العصبي الطولية،\" الاعتماد على المخدرات والكحول (2022)، في PubMed Central\n\nما يظهره التصوير البشري\nجمعت هذه المراجعة الدراسات التي قامت بفحص نفس الأشخاص الذين يعانون من اضطراب استخدام المواد الأفيونية أكثر من مرة عبر الامتناع عن استخدام المواد الأفيونية. تشير النتائج باستمرار نحو التعافي:\n• ارتفعت بروتينات إعادة تدوير الدوبامين في مناطق المكافأة والحركة، بحوالي 30% أقل من المعدل الطبيعي في البداية، بنسبة 20% تقريبًا على مدار 6 إلى 12 شهرًا بعد تناول المواد الأفيونية\n• لم يعد من الممكن اكتشاف تشوهات المادة الرمادية الأمامية الموجودة في الانسحاب المبكر بعد حوالي شهر من الامتناع عن استخدام المواد الأفيونية\n• بدأت المادة البيضاء (الجبهية والحزامية) والنشاط الجبهي في حالة الراحة أيضًا في العودة إلى طبيعتها خلال الشهر الأول\n\nحيث يجلس سنة واحدة\nبحلول اثني عشر شهرًا، تكون قد وصلت إلى أطول فترة تم قياسها في هذه الدراسات أو تجاوزتها. لقد حظي نظام الدوبامين بمعظم الوقت للتعافي، وكانت الدوائر الأمامية التي تدعم ضبط النفس والحكم تتحسن منذ أشهر - النظير البيولوجي للتفكير الأكثر وضوحًا، والرغبة الشديدة الأضعف، والمزاج الأكثر ثباتًا الذي يصفه الناس خلال عام.\n\nإشارة التعافي\nبعد عام واحد، تكون إشارة التصوير البشري موجهة نحو التعافي بقوة: فقد ارتفع توفر ناقل الدوبامين خلال فترة تتراوح بين 6 و12 شهرًا، في حين استغرقت التشوهات الهيكلية والوظيفية الأمامية عدة أشهر حتى تعود إلى طبيعتها.';

  @override
  String get opioidReferenceDay730 =>
      'سنتان من التوقف عن تناول المواد الأفيونية: أساس مستقر\n\nالمصدر: \"علاج اضطراب استخدام المواد الأفيونية\"، مراكز السيطرة على الأمراض والوقاية منها (CDC)\n\nحالة مزمنة، تتم إدارتها بشكل جيد\nيصف مركز السيطرة على الأمراض اضطراب استخدام المواد الأفيونية بأنه “مرض مزمن يمكن أن يؤثر على أي شخص” – “حالة طبية، وليس فشل أخلاقي”. إن الوصول إلى عامين من التعافي المستدام يعني أنك تمكنت من إدارة هذه الحالة بنجاح خلال إحدى الفترات الأكثر ضعفًا.\n\nما يقوله مركز السيطرة على الأمراض يعمل\nتركز إرشادات مركز السيطرة على الأمراض على العلاجات التي تحافظ على استقرار التعافي على المدى الطويل:\n• أدوية اضطراب استخدام المواد الأفيونية — البوبرينورفين، والميثادون، والنالتريكسون — والتي تصفها بأنها فعالة بشكل خاص\n• الجمع بين الدواء والعلاج السلوكي والاستشارة\n• العلاج الذي يستمر لفترات زمنية متفاوتة، ومصمم خصيصًا للشخص\nيشير مركز السيطرة على الأمراض إلى أن هذه الأدوية تساعد على \"تطبيع كيمياء الدماغ\" وتخفيف الرغبة الشديدة - فالكيمياء التي تم اختطافها في الإدمان النشط تعمل معك مرة أخرى.\n\nالبقاء بأمان\nيحث مركز السيطرة على الأمراض الأشخاص في مرحلة التعافي على سؤال طبيبهم عن خطر العودة إلى الاستخدام والجرعة الزائدة، والحفاظ على النالوكسون في متناول اليد. ينخفض ​​التسامح أثناء الامتناع عن تناول المواد الأفيونية، لذا فإن العودة إلى تناول المواد الأفيونية بعد هذه المدة أمر خطير بشكل خاص - مع العلم أن ذلك جزء من حماية ما قمت ببنائه.\n\nعامين في\nيوضح مركز السيطرة على الأمراض أن التعافي غالبًا ما يكون عملية طويلة الأمد وليس خط النهاية. إن عامين ليسا نهاية الرحلة، بل هما أساس مستقر وصحي ودليل قوي على نجاح النهج الذي تستخدمه.';

  @override
  String get opioidReferenceDay1095 =>
      'ثلاث سنوات - تعافٍ راسخ\n\nالمصدر: مراكز السيطرة على الأمراض والوقاية منها (CDC)، «علاج اضطراب استخدام المواد الأفيونية»\n\nتصف الإرشادات اضطراب استخدام المواد الأفيونية بأنه حالة مزمنة قابلة للعلاج، وأن العلاج قد يأخذ أشكالًا ومددًا مختلفة، بما في ذلك العلاج الدوائي المبني على الدليل.\n\nلا تحدد الإرشادات نقطة تعافٍ بيولوجية عند ثلاث سنوات. تحتفل هذه المحطة بـ1095 يومًا من التعافي المستمر.';

  @override
  String get opioidReferenceDay1460 =>
      'أربع سنوات - أساس قوي\n\nالمصدر: مراكز السيطرة على الأمراض والوقاية منها (CDC)، «علاج اضطراب استخدام المواد الأفيونية»\n\nتؤكد الإرشادات أن التعافي ممكن وأن العلاج يجب أن يلائم احتياجات كل شخص، من دون جدول زمني واحد للجميع.\n\nلا توجد نهاية بيولوجية محددة عند أربع سنوات. هذه المحطة تحتفل بأربع سنوات من التغيير الثابت وحماية ما تم بناؤه.';

  @override
  String get opioidReferenceDay1825 =>
      'خمس سنوات - نصف عقد\n\nالمصدر: مراكز السيطرة على الأمراض والوقاية منها (CDC)، «علاج اضطراب استخدام المواد الأفيونية»\n\nتعامل الإرشادات التعافي كمسار فردي ولا تحدد ذكرى سنوية يجب عندها إنهاء العلاج أو اعتبار التعافي مكتملًا بيولوجيًا.\n\nخمس سنوات هي نصف عقد من التغيير المستمر، وهو إنجاز يستحق الاحتفال بحد ذاته.';

  @override
  String get pornographyReferenceDay1 =>
      'اليوم الأول: استعادة السيطرة\n\nالمصدر: كراوس وآخرون، اضطراب السلوك الجنسي القهري في الإصدار الحادي عشر من التصنيف الدولي للأمراض، الطب النفسي العالمي (2018).\n\nالمشكلة المهمة سريريًا ليست استخدام المواد الإباحية في حد ذاتها. يتم تعريف اضطراب السلوك الجنسي القهري حول الصعوبة المستمرة في التحكم في السلوك الجنسي المتكرر عندما يسبب هذا النمط ضائقة أو ضعفًا كبيرًا. يمكن أن يكون استخدام المواد الإباحية الإشكالي عرضًا لهذه المشكلة الأوسع.\n\nوهذا يجعل اليوم الأول ملموسًا وليس غامضًا: لقد قمت بمقاطعة سلوك قررت أنه خارج عن السيطرة. يوم واحد مكتمل لا يثبت إعادة ضبط الدماغ والأعصاب، لكنه يمنحك أول ملاحظة حقيقية عن متى تظهر الحوافز، وما هي المواقف التي تثيرها، وما يمكنك فعله بدلاً من ذلك.\n\nإذا لم يكن استخدامك مزعجًا أو معطلًا أو يصعب التحكم فيه، فقد لا ينطبق إطار عمل CSBD السريري عليك. تستهدف هذه المعالم الأشخاص الذين يغيرون الاستخدام الإشكالي أو القهري عمدًا.';

  @override
  String get pornographyReferenceDay3 =>
      'اليوم الثالث: تعرف على الشكل الذي يمكن أن تبدو عليه الرغبة الملحة\n\nالمصدر: Lewczuk وآخرون، الانسحاب والتسامح فيما يتعلق باضطراب السلوك الجنسي القهري واستخدام المواد الإباحية الإشكالي، مجلة الإدمان السلوكي (2022).\n\nفي عينة بولندية تمثيلية مسجلة مسبقًا على المستوى الوطني مكونة من 1,541 شخصًا بالغًا، ارتبطت التجارب الشبيهة بالانسحاب الأقوى المبلغ عنها ذاتيًا بزيادة CSBD وشدة استخدام المواد الإباحية الإشكالية. من بين المشاركين الذين يعانون من استخدام المواد الإباحية، تضمنت التجارب الشائعة التي تم الإبلاغ عنها أفكارًا جنسية يصعب إيقافها، ورغبة يصعب التحكم فيها، وزيادة الإثارة، والتهيج، وتغيرات المزاج، ومشاكل النوم.\n\nتم توثيق القلق والأفكار الجنسية المتطفلة والحوافز القوية والتهيج لدى الأشخاص الذين يعانون من استخدام أكثر خطورة. إذا ظهرت في اليوم الثالث تقريبًا، تعامل معها كنمط حقيقي يشبه الانسحاب وقم بالتعامل مع المحفزات.\n\nاكتب ما هي الحوافز التي تحدث بالفعل، وما الذي سبقها، وما هي الاستجابة التي ساعدت. تصبح عملية التعافي أسهل عندما يتم تسمية المحفز بدلاً من التعامل معه على أنه حدث دماغي غامض.';

  @override
  String get pornographyReferenceDay7 =>
      'أسبوع واحد: ما وجدته دراسة عشوائية للامتناع\n\nالمصدر: Effects of a 7-Day Pornography Abstinence Period on Withdrawal-Related Symptoms in Regular Pornography Users, Archives of Sexual Behavior (2023).\n\nوزّع الباحثون 176 من مستخدمي المواد الإباحية المنتظمين عشوائيًا بين محاولة الامتناع عن المشاهدة لمدة سبعة أيام والاستمرار كالمعتاد. وعلى مستوى العينة كاملة، لم يؤدِ الامتناع إلى زيادة عامة ذات دلالة في الرغبة أو المزاج السلبي أو أعراض شبيهة بالانسحاب.\n\nأظهر تحليل استكشافي زيادة في الرغبة لدى من جمعوا بين درجات مرتفعة للاستخدام الإشكالي والمشاهدة اليومية قبل الدراسة. وتحتاج هذه النتيجة إلى التكرار، لكنها مفيدة: قد يكون الأسبوع الأول صعبًا لدى بعض ذوي الاستخدام الإشكالي الأشد، بينما لا تدعم هذه التجربة وجود متلازمة انسحاب عامة من المواد الإباحية.\n\nإذا أكملت أسبوعًا، فلديك الآن معلومات أفضل عن نمطك الشخصي مما يمكن أن يقدمه أي جدول زمني عام على الإنترنت.';

  @override
  String get pornographyReferenceDay14 =>
      'أسبوعين: رسم خريطة للمحفزات المهمة بالفعل\n\nالمصدر: المحددات البيولوجية النفسية الاجتماعية لاستخدام المواد الإباحية الإشكالية: مراجعة منهجية (2023).\n\nجمعت هذه المراجعة 66 دراسة ووجدت أن استخدام المواد الإباحية الإشكالي يرتبط بمزيج من العوامل بدلاً من آلية الدوبامين البسيطة. وتشمل العوامل النفسية والاجتماعية التي تم تحديدها بشكل متكرر الرغبة الشديدة، والإجهاد، والتجنب، والشعور بالوحدة، واحترام الذات، والمعتقدات السلبية، وأسلوب التكيف.\n\nيمنحك أسبوعان التعرض المتكرر لأيام الأسبوع، وعطلات نهاية الأسبوع، والملل، والتوتر، والخصوصية، والأجهزة، وغيرها من السياقات التي ربما تكون قد أشارت إلى السلوك القديم. استخدم تلك البيانات. إذا كان التوتر هو المحفز، قم بتصميم استجابة للضغط. إذا كانت الوحدة هي المحفز، أضف جهة اتصال. إذا كان الوصول السهل هو الدافع، قم بتغيير البيئة.\n\nتدعم الأدلة العمل على دوافع الاستخدام الإشكالي؛ ولا يتطلب الأمر التظاهر بأن كل شخص يتبع نفس العد التنازلي البيولوجي.';

  @override
  String get pornographyReferenceDay30 =>
      'شهر واحد: التحكم مهم أكثر من مجرد إحصاء بسيط للترددات\n\nالمصدر: Bőthe وآخرون، هل ترتبط مشاكل الأداء الجنسي بالاستخدام المتكرر للمواد الإباحية و/أو استخدام المواد الإباحية الإشكالي؟، سلوكيات الإدمان (2021).\n\nفي عينة مجتمعية مكونة من 14.581 شخصًا بالغًا، كان لاستخدام المواد الإباحية الإشكالية علاقة إيجابية معتدلة بمشاكل الأداء الجنسي لدى كل من الرجال والنساء. أظهر تكرار استخدام المواد الإباحية في حد ذاته ارتباطًا سلبيًا ضعيفًا بهذه المشكلات.\n\nهذا التمييز مهم. لا تدعم الأدلة إخبار كل مستخدمي المواد الإباحية أن تكرار المشاهدة وحده يضر بالوظيفة الجنسية. الهدف الأكثر أهمية من الناحية السريرية هو فقدان السيطرة والمشاكل المحيطة بهذا النمط.\n\nبعد مرور شهر واحد، قارن حياتك الآن بما بدأته: الانشغال، والوقت الضائع، والقدرة على التوقف، والأداء الجنسي، وصراع العلاقات، والضيق. هذه التغييرات مهمة أكثر من انتظار إعادة ضبط الدماغ الأسطورية لمدة 30 يومًا.';

  @override
  String get pornographyReferenceDay90 =>
      'ثلاثة أشهر: التغيير الدائم ممكن\n\nالمصدر: كروسبي وتويج، علاج القبول والالتزام لاستخدام المواد الإباحية على الإنترنت الإشكالي: تجربة عشوائية، العلاج السلوكي (2016).\n\nقارنت هذه التجربة العشوائية الصغيرة برنامج ACT المكون من 12 جلسة مع قائمة انتظار تضم 28 رجلاً بالغًا. انخفضت مشاهدة المواد الإباحية أكثر بكثير في مجموعة ACT في نهاية العلاج، وظلت التخفيضات الكبيرة في المتابعة لمدة ثلاثة أشهر.\n\nولا تثبت الدراسة أن 90 يوما من الامتناع وحدها تؤدي إلى نفس النتيجة، وكانت عينتها صغيرة وضيقة ديمغرافيا. ما يوضحه هذا الأمر مهم: استخدام المواد الإباحية الإشكالي قابل للتعديل، والمهارات المنظمة يمكن أن تنتج تغييرات تستمر إلى ما بعد فترة العلاج المباشرة.\n\nإذا كان تقدمك لا يزال يعتمد في الغالب على الصعوبات، فإن ثلاثة أشهر هي نقطة جيدة لتعزيز النظام من حوله: خطط التحفيز، وقبول الحوافز دون التصرف، والاحتكاك البيئي، والمساءلة، والعلاج عند الحاجة.';

  @override
  String get pornographyReferenceDay180 =>
      'ستة أشهر: يمكن السيطرة على الأعراض على المدى الطويل\n\nالمصدر: هالبيرج وآخرون، دراسة عشوائية محكومة للعلاج السلوكي المعرفي الذي تديره المجموعة لاضطراب فرط الجنس لدى الرجال، مجلة الطب الجنسي (2019).\n\nفي 137 رجلاً يعانون من سلوك جنسي خارج عن السيطرة، أدت سبعة أسابيع من العلاج السلوكي المعرفي إلى انخفاض أكبر في أعراض فرط النشاط الجنسي والقسر الجنسي مقارنة بقائمة الانتظار، إلى جانب تحسن الحالة النفسية. ظلت مكاسب العلاج مستقرة في كل من المتابعة لمدة ثلاثة وستة أشهر.\n\nغطت هذه الدراسة اضطراب فرط النشاط الجنسي على نطاق أوسع بدلاً من الامتناع عن مشاهدة المواد الإباحية وحدها، لذلك لا ينبغي تحويلها إلى ادعاء بأن كل شخص يتعافى بيولوجيًا بعد ستة أشهر. إنه يدعم عبارة أقوى وأكثر فائدة: التحسن المستمر في السلوك الجنسي القهري يمكن أن يظل ثابتًا على مدار هذه الفترة الزمنية.\n\nوبالتالي فإن ستة أشهر تعتبر علامة فارقة في الصيانة. حافظ على الإجراءات الروتينية التي جعلت التحكم أسهل بدلاً من اعتبار التاريخ بمثابة إذن لتفكيكها.';

  @override
  String get pornographyReferenceDay365 =>
      'سنة واحدة: دليل على تغيير السلوك الدائم\n\nالمصدر: آثار المتابعة لمدة عام للعلاج القائم على القبول لفرط الرغبة الجنسية (2026).\n\nفي متابعة لمدة عام واحد، لم يعد المشاركون في هذه الدراسة العلاجية القائمة على القبول إلى مستويات فرط الرغبة الجنسية لديهم قبل العلاج. وصف المؤلفون النتائج بأنها دليل أولي على فوائد دائمة ذات معنى سريريًا، مع التحكم الملحوظ في الرغبة الشديدة بين العمليات التي يتم اتباعها مع مرور الوقت.\n\nهذا دليل متابعة العلاج، وليس دليلاً على إعادة ضبط الدماغ لمدة عام واحد. إن الادعاء الهادف هو الأفضل على أية حال: فالتحكم ذو الصلة سريريًا من الممكن أن يستمر لمدة عام بدلاً من أن يختفي بمجرد انتهاء التدخل الأولي.\n\nيعد عام من التغيير الذي حافظت عليه بمثابة مجموعة بيانات شخصية كبيرة أيضًا. قارن السيطرة الحالية، والضيق، والأداء، والعلاقات، واستخدام الوقت مع المكان الذي بدأت فيه؛ تلك هي النتائج التي تهم سريريا.';

  @override
  String get pornographyReferenceDay730 =>
      'عامان: سيطرة مستقرة\n\nالمصدر: Ince وآخرون (2026)، مراجعة حول اضطراب السلوك الجنسي القهري والاستخدام الإشكالي للمواد الإباحية.\n\nتصف الأبحاث هذه المشكلات بأنها معقدة وتختلف بين الأشخاص، وتركز على السيطرة والضيق والأداء والسياق. ولا تحدد عتبة بيولوجية عامة عند عامين.\n\nلذلك يمثل عامان استمراراً راسخاً للتغيير السلوكي. وتعد السيطرة المستمرة وتحسن الأداء نتيجتين مهمتين بحد ذاتهما.';

  @override
  String get pornographyReferenceDay1095 =>
      'ثلاثة أعوام: تغيير راسخ\n\nالمصدر: Ince وآخرون (2026)، مراجعة حول اضطراب السلوك الجنسي القهري والاستخدام الإشكالي للمواد الإباحية.\n\nلا تحدد الأدلة الحالية نقطة نهاية بيولوجية عند ثلاثة أعوام. ويظل التقييم السريري مركزاً على السيطرة والضيق والاختلال والسياق والأداء اليومي.\n\nتشهد ثلاثة أعوام على متانة التغيير. والتغيير الذي يستمر رغم تبدل الروتين والظروف يستحق الحماية والاستمرار.';

  @override
  String get pornographyReferenceDay1460 =>
      'أربعة أعوام: تغيير دائم\n\nالمصدر: Ince وآخرون (2026)، مراجعة حول اضطراب السلوك الجنسي القهري والاستخدام الإشكالي للمواد الإباحية.\n\nتؤكد الأدلة الفروق الفردية والسياق ولا تدعم نقطة عامة يكتمل عندها التعافي البيولوجي بعد أربعة أعوام.\n\nومع ذلك يمكن لأربعة أعوام أن تُظهر ثباتاً عميقاً. إذا لم يعد النمط القديم يهيمن على القرارات أو يعطل العلاقات والأداء، فهذه نتيجة طويلة الأمد وذات معنى.';

  @override
  String get pornographyReferenceDay1825 =>
      'خمس سنوات: السيطرة على المدى الطويل هي النتيجة\n\nالمصدر: اضطراب السلوك الجنسي القهري واستخدام المواد الإباحية الإشكالية: مراجعة شاملة متعددة التخصصات ومستنيرة من الخبراء (2026).\n\nتتعامل المراجعات الحديثة مع CSBD واستخدام المواد الإباحية الإشكالية على أنها مشاكل معقدة تنطوي على التحكم والضيق والأداء والسياق والفروق الفردية. لا توجد عتبة مؤكدة لإعادة ضبط الدماغ والأعصاب لمدة خمس سنوات.\n\nلكن خمس سنوات ليست علامة فارقة فارغة. إنها 1825 يومًا من الحفاظ على الاتجاه السلوكي الذي اخترته. نظرًا لأن المشكلة السريرية تتمثل في فقدان السيطرة المستمر مع الضيق أو الضعف، فإن السيطرة المستمرة واستعادة الأداء على مر السنين هي نتائج ذات معنى في حد ذاتها.\n\nفي هذه المرحلة، لم يعد السؤال المفيد هو ما إذا كان دماغك قد وصل إلى نسبة خيالية من إعادة توصيل الأسلاك. بل هو ما إذا كان النمط القديم لا يزال يتحكم في اختياراتك أو يعطل الحياة التي تريدها. وإذا لم يحدث ذلك، فهذا نجاح كبير على المدى الطويل.';

  @override
  String get smokingReferenceDay1 =>
      'اليوم الأول: الفوائد تبدأ الآن\n\nالمصدر: NHS صحة أفضل\n\nتبدأ الفوائد في غضون دقائق – وليس أيامًا. يبدأ الجسم في العودة إلى طبيعته بمجرد توقف الدخان.\n\nماذا يحدث اليوم\n• 20 دقيقة: يبدأ معدل النبض بالعودة إلى طبيعته\n• 8 ساعات: ينخفض مستوى أول أكسيد الكربون في الدم إلى النصف. مستويات الأكسجين تتعافى\n• 48 ساعة: انخفض مستوى أول أكسيد الكربون إلى مستوى غير المدخن\n\nيرتبط أول أكسيد الكربون بخلايا الدم الحمراء بقوة أكبر من الأكسجين، مما يؤدي إلى إزاحته من الدم. كان كل عضو يحصل على كمية أقل من الأكسجين مما ينبغي. وهذا ينعكس خلال يومين.\n\nيبدأ الانسحاب في اليوم الأول\n• الرغبة الشديدة — تستمر كل منها عادةً من 3 إلى 5 دقائق\n• التهيج وصعوبة التركيز\n• زيادة الشهية\n\nهذه مؤقتة ويمكن التحكم فيها. يقدم برنامج NHS Better Health دعمًا مجانيًا يشمل التطبيقات ونصائح الصيدلي.';

  @override
  String get smokingReferenceDay3 =>
      'اليوم الثالث: ذروة الانسحاب\n\nالمصدر: ماكلولين وداني ودي بياسي\n\nبحلول 72 ساعة، يختفي النيكوتين من جسمك. قام الدماغ ببناء مستقبلات نيكوتين إضافية خلال سنوات التدخين؛ الآن يتم التقليل من تحفيزهم، مما يسبب متلازمة الانسحاب.\n\nأعراض الذروة\n• الرغبة الشديدة – الأكثر شدة الآن\n• التهيج، والإحباط، والأرق\n• صعوبة في التركيز\n• القلق\n• الصداع\n• زيادة الشهية\n• السعال (تنظف المسالك الهوائية — علامة جيدة)\n\nهذا هو أصعب يوم. لا يصبح الأمر أسوأ من هذا، فمن هنا تخف الأعراض بشكل مطرد مع إعادة ضبط دماغك.\n\nالعلاج ببدائل النيكوتين، والفارينيكلين، والبوبروبيون كلها تقلل بشكل كبير من شدة الانسحاب في هذه المرحلة.';

  @override
  String get smokingReferenceDay7 =>
      'أسبوع واحد: عودة التذوق والشم\n\nالمصدر: NHS صحة أفضل\n\nإن الوصول إلى أسبوع خالٍ من التدخين هو مؤشر قوي للنجاح على المدى الطويل - فالأشخاص الذين يجتازون الأسبوع الأول هم أكثر عرضة للإقلاع عن التدخين إلى الأبد.\n\nما تم استرداده\n• مذاق الطعام أكثر نكهة\n• الروائح أكثر حيوية\n• أصبح التنفس أسهل — وأصبحت المسالك الهوائية نظيفة\n• الدورة الدموية آخذة في التحسن\n• الجلد رطب بشكل أفضل\n\nيؤدي التدخين إلى إتلاف مستقبلات التذوق والشم بشكل مباشر؛ وفي غضون أيام من التوقف، يبدأون في التعافي.\n\nإن انسحاب النيكوتين الحاد يتراجع. الرغبة الشديدة الجسدية أقصر وأقل تواترا. ربما لا تزال الرغبة الشديدة القائمة على المحفزات موجودة، ولكن أسوأ ما في الإلحاح الجسدي قد أصبح وراءك.';

  @override
  String get smokingReferenceDay14 =>
      'أسبوعين: تتحسن الدورة الدموية\n\nالمصدر: NHS صحة أفضل\n\nوفي غضون 2-12 أسبوعًا من التوقف، تتحسن الدورة الدموية. يقوم النيكوتين بتضييق الأوعية الدموية مع كل سيجارة؛ وبدونها تسترخي الأوعية ويتدفق الدم بحرية أكبر.\n\nماذا يعني هذا\n• يتحسن تدفق الدم إلى اليدين والقدمين والأنسجة الطرفية\n• يلاحظ العديد من الأشخاص أن الأيدي والأقدام أكثر دفئًا\n• يصبح المشي وصعود السلالم أسهل\n\nومع إزالة أول أكسيد الكربون من الدم بالفعل في اليوم الأول وتحسن الدورة الدموية الآن، يصل الأكسجين إلى العضلات بشكل أكثر فعالية.\n\nتتعافى الأهداب المبطنة للممرات الهوائية وتدفع المخاط المتراكم إلى الخارج. إذا كنت تسعل أكثر من المعتاد، فهذه علامة على التعافي، وليس انتكاسة.';

  @override
  String get smokingReferenceDay30 =>
      'شهر واحد: تتحسن وظائف الرئة\n\nالمصدر: NHS صحة أفضل\n\nيصبح التنفس أسهل وتتحسن وظائف الرئة — وتزيد بنسبة تصل إلى 10% خلال فترة تتراوح من 3 إلى 9 أشهر. في شهر واحد، تكون قد وصلت إلى منحنى التعافي هذا.\n\nما يحدث في الرئتين\n• تنمو الأهداب من جديد وتقوم بإزالة المخاط بشكل أكثر فعالية\n• يستقر التهاب مجرى الهواء\n• تلاشي سعال المدخن المستمر\n• التسامح مع ممارسة الرياضة آخذ في التحسن\n\nتتحسن أي سعال وأزيز ومشاكل في التنفس مع زيادة وظائف الرئة. شهر واحد هو نقطة ذات معنى على منحنى الانتعاش.';

  @override
  String get smokingReferenceDay90 =>
      'ثلاثة أشهر: انخفاض خطر الإصابة بالنوبات القلبية\n\nالمصدر: PMC - آثار التدخين على القلب والأوعية الدموية والإقلاع عنه (2024)\n\nيؤدي التدخين إلى إتلاف القلب والشرايين بطرق متعددة: فهو يسرع من تراكم لويحات الشرايين، ويعزز تخثر الدم، ويرفع ضغط الدم، ويدمر بطانة الشرايين. تنعكس التأثيرات المسببة للتخثر والمعززة للجلطة خلال أيام من التوقف، وتشير هذه المراجعة إلى انخفاض ملحوظ في النوبات القلبية والسكتات الدماغية خلال السنة الأولى من الإقلاع عن التدخين.\n\nما تحسن الآن\n• عودة عوامل تخثر الدم إلى طبيعتها\n• استقرار ضغط الدم ومعدل ضربات القلب\n• إن أكبر انخفاض مبكر في مخاطر الإصابة بأمراض القلب والأوعية الدموية الحادة يجري على قدم وساق\n\nتستغرق فوائد المفعول الأبطأ — عكس سنوات من تراكم اللويحات الشريانية — وقتًا أطول ويتم تغطيتها في مراحل لاحقة. كل شهر خالي من التدخين يضيف إلى التعافي.';

  @override
  String get smokingReferenceDay180 =>
      'ستة أشهر: خلايا المناعة في الرئتين تستعيد قوتها\n\nالمصدر: فترة خالية من التدخين واستعادة وظيفة الخلايا المناعية السنخية (PubMed)\n\nيمكن للتدخين أن يثبط البلاعم السنخية — وهي خلايا مناعية عميقة في الرئتين تبتلع البكتيريا وتقتلها.\n\nما الذي قاستْه الدراسة\nقارن الباحثون 15 شخصًا لم يدخنوا قط، و15 مدخنًا حاليًا، و41 مدخنًا سابقًا كانوا بلا تدخين لمدة شهرين أو 3–5 أشهر أو 6–12 شهرًا أثناء التخدير العام.\n\nإشارة تعافٍ ملموسة\nأثناء التخدير، كان الانخفاض في بلعمة البلاعم السنخية وقدرتها على قتل البكتيريا أكبر بمقدار 1.5–3 مرات لدى المدخنين الحاليين ومن أقلعوا منذ شهرين مقارنة بمن لم يدخنوا قط. وبعد 3–12 شهرًا بلا تدخين، أصبحت الاستجابات المضادة للميكروبات أقرب إلى نمط غير المدخنين مما كانت عليه عند شهرين.\n\nتعافت الإشارات الالتهابية بوتيرة أبطأ، مع استمرار اختلافات في استجابات السيتوكينات حتى ستة أشهر. ستة أشهر محطة حقيقية في تعافي مناعة الرئتين، وما زال المزيد من التعافي في الطريق.';

  @override
  String get smokingReferenceDay365 =>
      'سنة واحدة: ينخفض خطر الإصابة بالنوبات القلبية بشكل حاد\n\nالمصدر: PMC - الإقلاع عن التدخين ونتائج السكتة الدماغية؛ مركز السيطرة على الأمراض، فوائد الإقلاع عن التدخين\n\nيضاعف التدخين تقريبًا خطر الإصابة بالسكتة الدماغية عن طريق تعزيز تراكم لويحات الشرايين، وزيادة تخثر الدم، ورفع ضغط الدم، وإتلاف الأوعية الدموية الدماغية. يضع الجدول الزمني لفوائد الإقلاع عن التدخين الخاص بمراكز السيطرة على الأمراض والوقاية منها (CDC) الانخفاض الحاد في خطر الإصابة بالنوبات القلبية عند علامة تتراوح من عام إلى عامين - وأنت على الحافة الأمامية لتلك النافذة.\n\nالجدول الزمني للاسترداد\nيستغرق التطبيع الكامل لخطر الإصابة بالسكتة الدماغية وقتًا أطول: اتبعت دراسة السكتة الدماغية المذكورة المقلعين عن التدخين لمدة متوسطها ما يقرب من خمس سنوات لإظهار معدل سكتة دماغية أقل بشكل ملحوظ من المدخنين المستمرين، وتضع بيانات مركز السيطرة على الأمراض (CDC) خطر الإصابة بأمراض القلب التاجية إلى النصف عند 3 إلى 6 سنوات، مع انخفاض خطر الإصابة بالسكتة الدماغية على مدى 5 إلى 10 سنوات.\n\nلا يزال عام واحد يمثل إنجازًا طبيًا حقيقيًا - لقد تجاوزنا الجزء الأكثر حدة من الانخفاض الحاد في المخاطر، على الرغم من أن فوائد القلب والأوعية الدموية والسرطان على المدى الطويل تستمر في التراكم لسنوات.';

  @override
  String get smokingReferenceDay730 =>
      'عامان: فوائد القلب والأوعية مستمرة\n\nالمصدر: مراكز مكافحة الأمراض، فوائد الإقلاع عن التدخين\n\nتذكر مراكز مكافحة الأمراض أن خطر النوبة القلبية ينخفض بوضوح خلال 1–2 عام بعد الإقلاع. بلوغ عامين يمثل نهاية هذه الفترة المدعومة بالأدلة، وليس تحولًا مفاجئًا في يوم محدد.\n\nويستمر الاتجاه طويل الأمد: يواصل الخطر الإضافي لمرض الشريان التاجي الانخفاض ويهبط إلى النصف خلال فترة 3–6 أعوام. عامان بلا تدخين يستحقان الاحتفال من دون اختراع موعد بيولوجي دقيق.';

  @override
  String get smokingReferenceDay1095 =>
      'ثلاثة أعوام: تبدأ نافذة تحسن القلب\n\nالمصدر: مراكز مكافحة الأمراض، فوائد الإقلاع عن التدخين\n\nتضع مراكز مكافحة الأمراض انخفاض الخطر الإضافي لمرض الشريان التاجي إلى النصف ضمن فترة 3–6 أعوام بعد الإقلاع. ثلاثة أعوام هي بداية هذا النطاق.\n\nالأدلة تصف فترة زمنية لا عتبة فورية. عند بلوغ ثلاثة أعوام يكون انخفاض الخطر القلبي الوعائي طويل الأمد قد تقدم بوضوح ويستمر في التراكم.';

  @override
  String get smokingReferenceDay1460 =>
      'أربعة أعوام: فوائد القلب تتزايد\n\nالمصدر: مراكز مكافحة الأمراض، فوائد الإقلاع عن التدخين\n\nأربعة أعوام بلا تدخين تقع داخل فترة 3–6 أعوام التي تذكرها مراكز مكافحة الأمراض، حيث ينخفض الخطر الإضافي لمرض الشريان التاجي إلى النصف مقارنة بالاستمرار في التدخين.\n\nأهمية هذا النطاق أنه يتجنب الادعاء بوجود تحول بيولوجي دقيق عند أربعة أعوام، مع الاعتراف بفترة مدعومة طبيًا من التحسن الكبير لصحة القلب والأوعية.';

  @override
  String get smokingReferenceDay1825 =>
      'خمس سنوات: تبدأ مكاسب كبيرة ضد مخاطر السرطان\n\nالمصدر: CDC، فوائد الإقلاع عن التدخين\n\nخمس سنوات تضعك عند بداية نافذة مهمة لانخفاض المخاطر.\n\nمحطات 5–10 سنوات\n• الخطر الإضافي لسرطانات الفم والحلق والحنجرة: ينخفض إلى النصف\n• خطر السكتة الدماغية: ينخفض\n\nوما زال أمامك\n• نحو 10 سنوات: ينخفض خطر سرطانات المثانة والمريء والكلى\n• 10–15 سنة: ينخفض الخطر الإضافي لسرطان الرئة إلى النصف\n• 15 سنة: ينخفض خطر مرض القلب التاجي ليقترب من مستوى شخص لا يدخن\n• 20 سنة: يقترب خطر سرطانات الفم والحلق والحنجرة من مستوى شخص لا يدخن، وينخفض الخطر الإضافي لسرطان عنق الرحم بنحو النصف\n\nخمس سنوات بلا تدخين إنجاز ضخم — لقد وصلت إلى النافذة التي تبدأ فيها تخفيضات كبيرة في مخاطر السرطان والسكتة الدماغية، وما زالت مكاسب أكبر في الطريق.';

  @override
  String get snriReferenceDay3 =>
      'التوقف عن SNRI: الأيام الأولى\n\nالمصدر: Harvard Health Publishing\n\nملاحظة سلامة مهمة\nيجب إيقاف أدوية SNRI فقط تحت إشراف طبي وبخفض تدريجي للجرعة. يتميز فينلافاكسين (Effexor) خصوصًا بنصف عمر قصير جدًا يبلغ نحو 5 ساعات، لذلك يغادر الجسم بسرعة وقد تظهر أعراض التوقف بصورة شديدة ومفاجئة.\n\nلماذا قد يكون إيقاف SNRIs أصعب من SSRIs\nتؤثر SNRIs في مادتين كيميائيتين تنظمان المزاج — السيروتونين والنورأدرينالين — ولذلك يحتاج النظامان إلى إعادة التكيف عند الإيقاف. وغالبًا ما تكون أعراض التوقف أشد مع SNRIs منها مع SSRIs:\n• أعراض شبيهة بالإنفلونزا (التعب، التعرق، آلام العضلات)\n• الأرق واضطراب النوم\n• الغثيان — وقد يكون أوضح من SSRIs\n• اختلال التوازن والدوخة\n• اضطرابات حسية — وقد تكون «صعقات الدماغ» شديدة مع فينلافاكسين\n• فرط الاستثارة والتهيج والقلق\n\nمقارنة SNRIs\nلفينلافاكسين أصعب أنماط التوقف بسبب نصف عمره القصير. ويكون دولوكستين (Cymbalta) أسهل نسبيًا بسبب نصف عمره الأطول البالغ نحو 12 ساعة، بينما يقع ديسفينلافاكسين بينهما.';

  @override
  String get snriReferenceDay7 =>
      'أسبوع واحد بعد SNRIs: تعديل نظامين كيميائيين للدماغ\n\nالمصدر: NHS - إيقاف مضادات الاكتئاب أو التخلص منها (إرشادات عامة حول مضادات الاكتئاب؛ تعكس الآليات الخاصة بالنورادرينالين أدناه علم الصيدلة العام لـ SNRI بدلاً من التفاصيل الخاصة بـ SNRI من صفحة NHS نفسها)\n\nتحدي النظام المزدوج\nعلى عكس معظم مضادات الاكتئاب التي تؤثر على نظام واحد، تؤثر SNRIs على كل من السيروتونين والنورادرينالين. وبعد أسبوع واحد، يتم تعديل كلا النظامين:\n\nتأثيرات نظام النورادرينالين\nيتحكم نظام النورادرينالين في استجابة الجسم للقتال أو الطيران، وتنظيم ضغط الدم، ومستويات الطاقة. كما يعدل:\n• قد تحدث تقلبات في ضغط الدم\n• قد يكون القلق جسديًا أكثر (تسارع نبضات القلب والتعرق)\n• قد تكون مستويات الطاقة غير متناسقة\n\nآثار نظام السيروتونين\nفي الوقت نفسه، يتكيف نظام السيروتونين - مما يؤدي إلى ظهور أعراض الانسحاب النموذجية لإيقاف أي مضاد للاكتئاب. إن الجمع بين كلا النظامين يمكن أن يجعل الأسبوع الأول صعبًا بشكل خاص.\n\nجسديًا، يُظهر هذا غالبًا تحسنًا في استقرار ضغط الدم وتقليل نوبات الدوخة عند الوقوف. على المستوى العاطفي، يكون المزاج أكثر تقلبًا مما سيكون عليه بعد 30 يومًا ولكنه لم يعد في حالة سقوط حر.';

  @override
  String get snriReferenceDay14 =>
      'بعد أسبوعين من SNRIs: تتلاشى الأعراض الجسدية\n\nالمصدر: ديفيز آند ريد (2019)، سلوكيات الإدمان\n\nحالة لمدة أسبوعين\nبالنسبة لمعظم الأشخاص الذين يتبعون التناقص التدريجي المناسب، يتم حل المرحلة الجسدية الحادة إلى حد كبير خلال أسبوعين:\n• انخفاض ملحوظ في صعقات الدماغ أو غيابها\n• حل الغثيان والأعراض الشبيهة بالأنفلونزا\n• تحسن مشاكل الدوخة والتوازن\n• استقرار ضغط الدم ومعدل ضربات القلب مع إعادة توازن النورادرينالين\n\nما قد يستمر\n• الحساسية العاطفية وتقلب المزاج\n• القلق — والذي يؤثر بشكل خاص على نظام النورادرينالين\n• التعب، حيث يوفر نظام النورادرينالين اليقظة والطاقة\n\nسياق البحث\nأكدت المراجعة المنهجية لسلوكيات الإدمان (Davies & Read, 2019) أن تأثيرات التوقف عن تناول SNRI هي من بين أشد التأثيرات خطورة بين أي فئة من مضادات الاكتئاب، حيث يرتبط الفينلافاكسين بمعدلات عالية بشكل خاص من أعراض الانسحاب المهمة.';

  @override
  String get snriReferenceDay30 =>
      'بعد شهر واحد من SNRIs: استقرار النظام المزدوج\n\nالمصدر: ديفيز آند ريد (2019)، سلوكيات الإدمان - مراجعة منهجية لحدوث انسحاب مضادات الاكتئاب وشدتها ومدتها\n\nمرحلة الاستقرار\nيمثل شهر واحد علامة بارزة في استعادة السيروتونين والنورادرينالين. وجدت هذه المراجعة أنه في حين أن أقلية كبيرة من الأشخاص يعانون من آثار الانسحاب التي تستمر لأكثر من بضعة أسابيع، فإن معظم الناس قد تجاوزوا المرحلة الحادة والأكثر شدة من أعراض التوقف الجسدي بحلول هذه المرحلة.\n\nما يتحسن عادة لمدة شهر واحد\n• تم حل أعراض التوقف الجسدي (صعقات الدماغ، والغثيان، والدوخة) بالنسبة لمعظم الناس\n• عودة ضغط الدم إلى مستواه الطبيعي\n• تحسين نوعية النوم — استعادة أنماط نوم حركة العين السريعة بشكل طبيعي\n• تبدأ مستويات الطاقة في الاستقرار مع عودة تنظيم النورادرينالين إلى طبيعته\n\nقرار التدهور العاطفي\nإحدى التجارب الأكثر شيوعًا في هذه المرحلة هي حل التبلد العاطفي - حيث يلاحظ العديد من الأشخاص الذين يستخدمون SNRIs نطاقًا عاطفيًا \"مسطحًا\". ومع زوال الدواء وإعادة ضبط الدماغ، عادةً ما يعود النطاق العاطفي والحساسية.';

  @override
  String get snriReferenceDay90 =>
      'ثلاثة أشهر بعد إيقاف SNRIs: تجاوز فترة الانسحاب المعتادة\n\nالمصدر: Fava وآخرون (2018)، \"Withdrawal Symptoms after Serotonin-Noradrenaline Reuptake Inhibitor Discontinuation: Systematic Review\"، Psychotherapy and Psychosomatics\n\nكيف تسير أعراض انسحاب SNRIs عادةً\nفي 61 تقريرًا — بينها 22 تجربة عشوائية محكومة مزدوجة التعمية — وُصفت أعراض انسحاب بعد كل أنواع SNRIs التي شملتها الدراسات. كانت الأعراض تبدأ عادةً خلال بضعة أيام من الإيقاف وتستمر بضعة أسابيع، حتى مع الخفض التدريجي للجرعة. وظهرت مع فينلافاكسين نسبة أعلى من أعراض الانسحاب عبر التقارير.\n\nلماذا يهم اليوم 90\nتسعون يومًا تتجاوز بكثير المسار المعتاد الذي يستمر بضعة أسابيع. بلوغ ثلاثة أشهر يعني أن فترة انسحاب SNRIs المعتادة أصبحت خلفك.\n\nقد تستمر بعض الحالات مدة أطول\nوجدت المراجعة أيضًا اضطرابات تبدأ متأخرًا أو تستمر مدة أطول. إذا بقيت أعراض مهمة عند ثلاثة أشهر، فراجعها مع الطبيب الذي يصف لك الدواء.';

  @override
  String get snriReferenceDay180 =>
      'ستة أشهر بعد SNRIs: تعافي الدماغ والأعصاب\n\nإشارة الاسترداد على بيانات ستة أشهر\nبعد مرور ستة أشهر على التخفيض التدريجي الكامل تحت إشراف طبي، تكون فترة الانسحاب الشديدة المبكرة من SNRI متأخرة كثيرًا. لقد استغرقت الحالة المزاجية والنوم والوظيفة الجنسية والتفكير الواضح أشهرًا للتعافي:\n• مسارات السيروتونين: تم استعادتها بشكل كبير\n• مسارات النورادرينالين: طبيعية، مع استقرار نظام الاستجابة للضغط أيضًا\n• بنية النوم: من المتوقع أن تتم استعادتها بالكامل\n• الوظيفة الجنسية: يتم استعادة الوظيفة الجنسية إلى حد كبير بالنسبة لمعظم الأشخاص (يعد العجز الجنسي أحد الآثار الجانبية الشائعة لـ SNRI، على الرغم من أنه يمكن أن يستمر بالنسبة للبعض ويستحق المناقشة مع الطبيب)\n\nالقدرة على التحمل للإجهاد\nأفاد العديد من الأشخاص في عمر الستة أشهر عن تحسن ملحوظ في القدرة على التكيف مع الضغوطات اليومية حيث أن دور نظام النورادرينالين في الاستجابة للتوتر والإثارة - والذي تعدله SNRIs بقوة - يعود إلى مستواه الطبيعي.';

  @override
  String get snriReferenceDay365 =>
      'بعد عام واحد من SNRIs: تم تحقيق التعافي\n\nعام واحد: استرداد كامل للنظام المزدوج\nبعد عام واحد من استكمال عملية التخفيض التدريجي لـSNRI، يكون لكل من نظامي السيروتونين والنورادرينالين دورة كاملة للتكيف والاستقرار.\n\nما تدعمه الأدلة فعليًا في عام واحد\nتشير مراجعة رسالة العلاج هذه إلى أن أعراض الانسحاب الموثقة \"تظهر عادةً في غضون أيام قليلة من التوقف\" وأن معظمها يختفي في غضون أسبوعين تقريبًا - لا توجد دراسة خاضعة للرقابة تتبع الأشخاص على وجه التحديد بعد عام واحد من توقف SNRI. ما تدعمه الصورة السريرية الأوسع على هذه المسافة:\n• غالبية أولئك الذين أكملوا التخفيض التدريجي المناسب وتلقوا الدعم النفسي ما زالوا في صحة جيدة\n• إن الضعف العاطفي والخلل الجنسي الذي يميز استخدام SNRI قد تم حله بالكامل بالنسبة لمعظم الناس\n• يتم الحفاظ على التفكير الواضح، بما في ذلك فوائد التركيز التي يمكن أن توفرها SNRIs، من خلال وظيفة الدماغ الطبيعية\n\nأهمية هذا المعلم\nيعد إيقاف استخدام SNRI بنجاح — وخاصة الفينلافاكسين — إنجازًا كبيرًا. إن شدة عملية التوقف والالتزام المطلوب لإدارتها تحت إشراف طبي تظهر مرونة ملحوظة.';

  @override
  String get socialMediaReferenceDay1 =>
      'التراجع عن وسائل التواصل الاجتماعي: اليوم الأول\n\nالمصدر: لامبرت وآخرون، \"أخذ استراحة لمدة أسبوع واحد من وسائل التواصل الاجتماعي يحسن الرفاهية والاكتئاب والقلق: تجربة عشوائية محكومة\"، علم النفس السيبراني والسلوك والشبكات الاجتماعية (2022)، على PubMed\n\nما تظهره الأدلة\nفي هذه الدراسة القوية الخاضعة للرقابة، تم اختيار الأشخاص عشوائيًا إما لأخذ استراحة لمدة أسبوع واحد من فيسبوك، وإنستغرام، وتويتر، وتيك توك، أو الاستمرار في استخدامها كالمعتاد. أظهرت مجموعة الاستراحة تحسينات كبيرة في الرفاهية وانخفاضًا في الاكتئاب والقلق. وهذا دليل حقيقي ومحكم على أن التراجع يساعد.\n\nما تظهره الأدلة\nويرتبط الاستخدام القهري لوسائل التواصل الاجتماعي بقوة بانخفاض الحالة المزاجية وزيادة القلق، وتظهر التجارب العشوائية أن التقليل المتعمد من استخدام وسائل التواصل الاجتماعي يمكن أن يحسن الرفاهية مع تقليل الاكتئاب والقلق في غضون أسبوع.\n\nاليوم الأول: ما يمكن توقعه\n• الأرق والرغبة في التحقق\n• الإشعارات \"الوهمية\" — الشعور بغصة لم تحدث\n• الملل أثناء التكيف مع التحفيز الأقل ثباتًا\nهذه أحاسيس طبيعية مرتبطة بالعادة، وهي مؤقتة. التعرف على النمط هو الخطوة الأولى في تغييره.';

  @override
  String get socialMediaReferenceDay3 =>
      'ثلاثة أيام بدون وسائل التواصل الاجتماعي: القلق والمزاج\n\nالمصدر: لامبرت وآخرون، \"أخذ استراحة لمدة أسبوع واحد من وسائل التواصل الاجتماعي يحسن الرفاهية والاكتئاب والقلق: تجربة عشوائية محكومة\"، علم النفس السيبراني والسلوك والشبكات الاجتماعية (2022)، على PubMed\n\nلماذا يساعد الاستراحة على تحسين المزاج؟\nفي هذه التجربة الخاضعة للرقابة، تم اختيار الأشخاص بشكل عشوائي لأخذ استراحة لمدة أسبوع واحد من وسائل التواصل الاجتماعي، وأنهوا الأسبوع بانخفاض مستوى القلق والاكتئاب والسعادة مقارنة بأولئك الذين استمروا في تصفح وسائل التواصل الاجتماعي. يأتي الكثير من المعاناة اليومية الناجمة عن الاستخدام المكثف من المقارنة الاجتماعية - قياس حياتك الحقيقية مقابل مقاطع مميزة منسقة للآخرين - ومن الجذب المنخفض للخوف من تفويت شيء ما.\n\nماذا يحدث بعد 72 ساعة\nفي وقت مبكر من الاستراحة، لا تزال هذه العادة عالية:\n• حوافز قوية للتحقق، غالبًا ما تكون ناجمة عن لحظات روتينية (الاستيقاظ، والانتظار في الطابور)\n• بعض التهيج والأرق\n• بالنسبة لبعض الناس، يعتبر هذا أول تخفيف للقلق الناتج عن المقارنة\n• بدأت عادة التمرير قبل النوم في التراجع\n\nفخ المقارنة يتحرر\nومن دون تغذية مستمرة لأبرز الأحداث التي ينشرها الآخرون، فإن المقارنة التي تغذي الكثير من القلق على وسائل التواصل الاجتماعي تصبح أقل قوة. تشير نتائج التجربة إلى أنه بحلول نهاية الأسبوع الأول، تؤدي هذه التحولات المبكرة إلى تحسن ملموس في الحالة المزاجية، وبالتالي فإن الشعور بعدم الراحة بعد ثلاثة أيام هو الجزء الصعب من التغيير الذي يؤتي ثماره.';

  @override
  String get socialMediaReferenceDay7 =>
      'أسبوع واحد بدون وسائل التواصل الاجتماعي: المردود المقاس\n\nالمصدر: لامبرت وآخرون، \"أخذ استراحة لمدة أسبوع واحد من وسائل التواصل الاجتماعي يحسن الرفاهية والاكتئاب والقلق: تجربة عشوائية محكومة\"، علم النفس السيبراني والسلوك والشبكات الاجتماعية (2022)، على PubMed\n\nأسبوع واحد بالضبط – وقد نجح الأمر\nهذا هو الحدث المهم الذي يتحدث عنه البحث بشكل مباشر: كان تدخل التجربة عبارة عن استراحة لمدة أسبوع واحد. وبالمقارنة مع الأشخاص الذين استمروا في استخدام وسائل التواصل الاجتماعي، أظهرت مجموعة الاستراحة مستوى أعلى بكثير من الصحة وانخفاضًا ملحوظًا في الاكتئاب والقلق بعد سبعة أيام فقط. الوصول إلى أسبوع واحد هو الوصول إلى النقطة التي وجدت فيها دراسة مضبوطة فائدة حقيقية.\n\nما يلاحظه الناس عادة\nإلى جانب المكاسب المزاجية المقاسة، غالبًا ما يبلغ الأشخاص عن:\n• المزيد من الوقت المستعاد – يتفاجأ الكثيرون بالمبلغ الذي أنفقوه\n• سهولة التركيز، حيث تضعف عادة تبديل الانتباه المستمر\n• أمسيات أكثر هدوءًا ونومًا أسهل دون الحاجة إلى الذهاب إلى السرير\nتتناسب هذه المكاسب مع التحسن الأوسع في الرفاهية الذي تم قياسه في التجربة.\n\nاستمر\nأسبوع واحد هو علامة فارقة حقيقية ومدعومة بالأدلة. تميل فوائد المزاج والوقت والاهتمام إلى التعمق كلما استمر النمط الصحي لفترة أطول.';

  @override
  String get socialMediaReferenceDay14 =>
      'أسبوعين بدون وسائل التواصل الاجتماعي: مكاسب لمدة أسبوعين\n\nالمصدر: كوين وودروف، \"أخذ استراحة: آثار المشاركة في التخلص من السموم الرقمية لوسائل التواصل الاجتماعي لمدة أسبوعين... بين الشباب\"، العلوم السلوكية (2023)، على PubMed Central\n\nحول هذه الدراسة\nوحصر الشباب استخدام وسائل التواصل الاجتماعي في نحو 30 دقيقة يوميا لمدة أسبوعين، مع تتبع الاستخدام بشكل موضوعي على هواتفهم (انخفضت النسبة بنحو 78%). فقد نجح المشاركون في خفض استخدام وسائل التواصل الاجتماعي بنسبة 78% تقريبا، مما أعطى هذا الإنجاز اختبارا مباشرا في العالم الحقيقي لما يحدث عندما ينخفض ​​الاستخدام بشكل حاد لمدة أسبوعين.\n\nما تحسن\nعلى مدار الأسبوعين، أظهر المشاركون تحسينات في:\n• النوم – المدة والجودة\n• الرضا عن الحياة\n• الإجهاد\n• العافية المدركة\n• النتائج على مقاييس إدمان الهواتف الذكية ووسائل التواصل الاجتماعي\nوكانت المكاسب المقاسة ملموسة: نوم أطول وأفضل، وانخفاض التوتر، وارتفاع مستوى الرضا عن الحياة والصحة، وانخفاض درجات إدمان الهواتف الذكية/وسائل التواصل الاجتماعي.\n\nاحترس من الانزلاق الخلفي\nولاحظ الباحثون أيضًا أن الاستخدام يزحف مرة أخرى نحو المستويات السابقة بعد ذلك. يعد أسبوعين مكسبًا حقيقيًا، لكنه يسلط الضوء على السبب وراء كون الخطة المتعمدة - وليس مجرد استراحة مؤقتة - هي التي تحافظ على الفوائد.';

  @override
  String get socialMediaReferenceDay30 =>
      'شهر بدون وسائل التواصل الاجتماعي: الاتصال الحقيقي يتعمق\n\nالمصدر: كوين وودروف، \"أخذ استراحة: آثار المشاركة في التخلص من السموم الرقمية لوسائل التواصل الاجتماعي لمدة أسبوعين... بين الشباب\"، العلوم السلوكية (2023)، على PubMed Central\n\nيمكن أن يتحسن الاتصال عندما تتراجع\nقد يبدو الأمر متناقضًا، ولكن في هذه الدراسة، ارتبط قطع وسائل التواصل الاجتماعي بتحسن العلاقات الداعمة، إلى جانب الرضا الأفضل عن الحياة وانخفاض التوتر. أصبح الوقت والاهتمام الذي تم تخصيصه للخلاصة متاحًا للأشخاص الموجودين فعليًا في حياتك.\n\nما يميل شهر واحد إلى إحضاره\nبحلول 30 يومًا، مع ضعف السحب التلقائي للتحقق، يجد الكثير من الأشخاص ما يلي:\n• المحادثات أكثر حضورا وأقل انقطاعا\n• المزيد من الاهتمام بالأنشطة والهوايات الواقعية\n• تعتمد الصورة الذاتية بدرجة أقل على الإعجابات والتعليقات وعدد المتابعين\n\nإشارة الاسترداد\nبحلول شهر واحد، تكون قد حافظت على النمط الصحي لمدة ضعف فترة التدخل الخاصة بالدراسة. إن مكاسب النوم، والتوتر، والرضا عن الحياة، والعافية، والعلاقات التي تم قياسها خلال أسبوعين، كان لها أسبوعين آخرين لدمجها في الروتين.\n\nقم بحساب الوقت\nاهدف إلى ملء وقت الفراغ بالأنشطة التي تبني تواصلًا حقيقيًا وإنجازًا، بدلاً من مجرد تبديل شاشة بأخرى.';

  @override
  String get socialMediaReferenceDay60 =>
      'شهرين بدون وسائل التواصل الاجتماعي: ما تدعمه الأدلة\n\nالمصدر: رمضان وآخرون، \"تأثيرات التخلص من سموم وسائل التواصل الاجتماعي على الصحة العقلية: مراجعة منهجية وتحليل تلوي\"، نارا ج (2024)، على موقع PubMed Central\n\nالصورة الأكثر موثوقية\nجمع الباحثون نتائج 10 دراسات، بما في ذلك سبع تجارب خاضعة للرقابة. وكانت النتيجة الأوضح هي انخفاض كبير في أعراض الاكتئاب بعد تراجع الناس عن وسائل التواصل الاجتماعي.\n\nالنتيجة الأقوى\nوجد البحث المشترك انخفاضًا واضحًا في أعراض الاكتئاب. وبعد مرور شهرين، ستحافظ على نفس النوع المنخفض من التعرض الرقمي الذي أنتج تلك الفائدة للصحة العقلية.\n\nكيف يمكن أن يبدو شهرين\nمع مقارنة يومية أقل وتعزيز أقل، فإن الصورة الذاتية لديها سبب أقل بكثير للاعتماد على الإعجابات أو التعليقات أو عدد المتابعين، في حين تشير أقوى الأدلة المجمعة إلى انخفاض أعراض الاكتئاب.\n\nالوجبات الجاهزة العملية\nالأدلة تكافئ التغيير المتعمد والمستدام. استخدم نقطة الشهرين للحفاظ على الحدود المتعمدة في مكانها بدلاً من الانجراف إلى الوراء، والاستثمار في مصادر المعنى والاتصال غير المتصلة بالإنترنت.';

  @override
  String get socialMediaReferenceDay90 =>
      'ثلاثة أشهر بدون وسائل التواصل الاجتماعي: وضع طبيعي جديد\n\nالمصدر: كوين وودروف، \"أخذ استراحة: آثار المشاركة في التخلص من السموم الرقمية لوسائل التواصل الاجتماعي لمدة أسبوعين... بين الشباب\"، العلوم السلوكية (2023)، على PubMed Central\n\nالنوم هو الصدارة\nومن بين أوضح النتائج التي توصلت إليها هذه الدراسة، تحسن النوم - سواء من حيث المدة أو الجودة - عندما قطع المشاركون وسائل التواصل الاجتماعي. وبعد ثلاثة أشهر من اتباع نمط صحي مستدام، توقفت فترة الليل المتأخرة التي اعتادت على تناول الطعام أثناء النوم منذ فترة طويلة عن التنافس مع الراحة، ويميل النوم الأفضل إلى تحسين الحالة المزاجية والتركيز والطاقة معها.\n\nما تحسن آخر\nوجدت نفس الدراسة مكاسب في الإجهاد، والرضا عن الحياة، والعافية المتصورة، والعلاقات الداعمة. وبعد مرور ثلاثة أشهر، لم تعد هذه الأمور جديدة، بل أصبح لديها الوقت للاستقرار في الوضع الطبيعي الجديد.\n\nإشارة الاسترداد على الآلية\nأدى قطع وسائل التواصل الاجتماعي إلى تحسين مدة النوم وجودته بشكل حاد في دراسة التدخل. ثلاثة أشهر من الحفاظ على هذا النمط يحول تقليل التمرير في وقت متأخر من الليل إلى عادة نوم دائمة.\n\nالحضور والعلاقات\nنظرًا لأن رد الفعل لملء كل لحظة هادئة بالهاتف أضعف بكثير، فإن التواجد - في المحادثات والوجبات ووقت التوقف عن العمل - يصبح أكثر طبيعية، وتميل العلاقات التي استثمرتها على مدار ثلاثة أشهر إلى الشعور بالقوة بسبب ذلك.';

  @override
  String get socialMediaReferenceDay180 =>
      'ستة أشهر بدون وسائل التواصل الاجتماعي: التعافي المُقاس\n\nالمصدر: رمضان وآخرون، \"تأثيرات التخلص من سموم وسائل التواصل الاجتماعي على الصحة العقلية: مراجعة منهجية وتحليل تلوي\"، نارا ج (2024)، على موقع PubMed Central\n\nما يضيفه التحليل التلوي\nمن خلال الجمع بين 10 دراسات، بما في ذلك سبع تجارب خاضعة للرقابة، وجد الباحثون انخفاضًا واضحًا في أعراض الاكتئاب بعد أن قام الأشخاص بتقليل وسائل التواصل الاجتماعي أو إيقافها مؤقتًا.\n\nما وجده فعلا\n• الاكتئاب: انخفاض ذو دلالة إحصائية (الفائدة الأكثر وضوحًا وثباتًا)\n• الرضا عن الحياة: لا يوجد تأثير كبير\n• الإجهاد: لا يوجد تأثير كبير\n• الصحة العقلية العامة: لا يوجد تأثير كبير\nالنتيجة المجمعة الأقوى واضحة: التخلص من السموم الرقمية يقلل بشكل كبير من أعراض الاكتئاب.\n\nلماذا قد لا تزال تشعر بفوائد واسعة النطاق\nستة أشهر من انخفاض التعرض للتغذية تؤدي إلى تفاقم المكاسب العملية التي شوهدت في التدخلات الأقصر: مزيد من الوقت المتاح، وتقليل الفحص الإلزامي، وانخفاض مستمر في التعرض الرقمي المرتبط بأعراض الاكتئاب.\n\nحافظ على التحكم في الخلاصة\nأكبر المكاسب تأتي من كسر الاستخدام الثقيل والسلبي والقهري. بحلول ستة أشهر، يصبح التحكم المتعمد في وسائل التواصل الاجتماعي هو الإجراء الافتراضي الجديد بدلاً من التحكم في انتباهك.';

  @override
  String get socialMediaReferenceDay365 =>
      'عام واحد بدون وسائل التواصل الاجتماعي: علاقة مُعاد التفاوض بشأنها\n\nالمصدر: رمضان وآخرون، \"تأثيرات التخلص من سموم وسائل التواصل الاجتماعي على الصحة العقلية: مراجعة منهجية وتحليل تلوي\"، نارا ج (2024)، على موقع PubMed Central\n\nسنة واحدة من التغيير المستدام\nتظهر أقوى الأبحاث المجمعة أن الابتعاد عن وسائل التواصل الاجتماعي يقلل من أعراض الاكتئاب. عام كامل يعني أن نمط التعرض المنخفض أصبح طبيعيًا وليس استراحة قصيرة.\n\nما يبني سنة\nسنة كاملة تمنحك مئات الساعات من العلاقات الحقيقية والهوايات والمهارات والتفكير والإبداع. لقد استغرق الفحص التلقائي عامًا كاملاً ليضعف، بينما استغرقت تلك الإجراءات غير المتصلة بالإنترنت عامًا كاملاً لتقويتها.\n\nالفوائد المستدامة\nإن أوضح مكاسب الصحة العقلية التي تم قياسها هي انخفاض أعراض الاكتئاب. إن المكاسب العملية - المزيد من الوقت، والانقطاعات الأقل، والفحص الإلزامي الأقل - تتضاعف مع كل يوم تحافظ فيه على التحكم في البث.\n\nماذا يأتي بعد ذلك\nلقد أدى عام من التغيير المتعمد إلى إعادة ضبط العلاقة. سواء عدت إلى الاستخدام المحدود والمتعمد أو ابتعدت تمامًا، فقد تم كسر الحلقة القهرية - وهذا هو الفوز الدائم.';

  @override
  String get ssriReferenceDay3 =>
      'إيقاف SSRI: الأيام الأولى\n\nالمصدر: Harvard Health Publishing\n\nملاحظة مهمة للسلامة\nينبغي إيقاف مثبطات استرداد السيروتونين الانتقائية فقط تحت إشراف طبي ومع خفض الجرعة تدريجيًا. الإيقاف المفاجئ — خصوصًا بعد الاستخدام الطويل — قد يزيد شدة أعراض الانسحاب بشكل واضح.\n\nما متلازمة إيقاف SSRI؟\nهي ظاهرة طبية موثقة قد تحدث عند إيقاف SSRI أو خفض جرعته بدرجة كبيرة. يستخدم الأطباء الاختصار FINISH لوصف الأعراض الشائعة:\n• أعراض شبيهة بالإنفلونزا (تعب، تعرّق، آلام عضلية)\n• أرق واضطراب النوم\n• غثيان\n• اختلال التوازن والدوخة\n• اضطرابات حسية — خصوصًا إحساس «الصعقات الدماغية»\n• فرط الاستثارة والتهيّج والقلق\n\nأهمية نصف العمر\nيمتلك فلوكستين (Prozac) نصف عمر طويلًا جدًا يبلغ 4–6 أيام، لذلك ينخفض مستواه تدريجيًا بصورة طبيعية وتكون أعراض الإيقاف عادة أخف. أما باروكستين (Paxil) فله أقصر نصف عمر بين أدوية SSRI الشائعة ويميل إلى إحداث أعراض إيقاف أشد. يقع سيرترالين وسيتالوبرام وإسيتالوبرام بينهما.';

  @override
  String get ssriReferenceDay7 =>
      'أسبوع واحد بعد SSRIs: المرحلة الحادة\n\nالمصدر: NHS – إيقاف مضادات الاكتئاب أو التخلص منها\n\nمرحلة التوقف الحاد\nتوثق هيئة الخدمات الصحية الوطنية أن معظم أعراض التوقف عن تناول مضادات الاكتئاب تبدأ خلال خمسة أيام من التوقف وتستمر لمدة تصل إلى ستة أسابيع في معظم الحالات. بحلول أسبوع واحد، عادة ما تكون الأعراض الجسدية الحادة في أكثر حالاتها وضوحًا وتبدأ في الاتجاه نحو الانخفاض بالنسبة لأولئك الذين تناقصوا تدريجيًا.\n\nما يمكن توقعه في أسبوع واحد\n• تكون الأعراض الجسدية (الغثيان، والدوخة، والمشاعر الشبيهة بالأنفلونزا) في أشد حالاتها ولكن من المفترض أن تبدأ في التراجع\n• اضطرابات النوم بما في ذلك الأحلام الواضحة أو الأرق شائعة\n• القدرة العاطفية – تغيرات مزاجية سريعة – شائعة في هذه المرحلة\n• ربما لا تزال الصعقات الدماغية موجودة ولكنها تبدأ عادةً في تقليل تكرارها\n\nدور التناقص\nتوصي هيئة الخدمات الصحية الوطنية (NHS) بشدة بالتخفيض التدريجي البطيء - أحيانًا على مدى أشهر للمستخدمين على المدى الطويل - لتقليل آثار التوقف. وضعت الكلية الملكية للأطباء النفسيين مبادئ توجيهية تدريجية تقترح تخفيضات تدريجية جدًا في الجرعة، غالبًا باستخدام تركيبات سائلة، لأولئك الذين تناولوا مثبطات استرداد السيروتونين الانتقائية لفترات طويلة.';

  @override
  String get ssriReferenceDay14 =>
      'بعد أسبوعين من مثبطات استرداد السيروتونين الانتقائية: حل الأعراض الجسدية\n\nالمصدر: Davies & Read (2019)، سلوكيات الإدمان - \"مراجعة منهجية لحدوث وشدة ومدة آثار الانسحاب المضادة للاكتئاب\"\n\nما وجده البحث\nوجدت هذه المراجعة المنهجية التاريخية أن ما يقرب من 56% من الأشخاص الذين توقفوا عن تناول مضادات الاكتئاب يعانون من آثار الانسحاب، ووصفها 46% منهم بأنها شديدة. بالنسبة لمعظم الأشخاص الذين يتبعون التناقص التدريجي المناسب، يتم حل المرحلة الحادة إلى حد كبير خلال أسبوعين:\n• انخفاض ملحوظ في صعقات الدماغ أو غيابها\n• حل الغثيان والأعراض الشبيهة بالأنفلونزا\n• تحسن مشاكل الدوخة والتوازن\n• بدأ النوم في العودة إلى طبيعته\n\nالتمييز بين التوقف عن الانتكاس\nالأعراض التي تظهر خلال أيام من التوقف وتطابق ملف تعريف FINISH هي على الأرجح متلازمة التوقف. الأعراض التي تظهر بعد 2-4 أسابيع وتشبه الحالة الأصلية التي يتم علاجها تكون أكثر عرضة للانتكاس. من المهم مراقبة هذا التمييز مع الواصف الخاص بك.';

  @override
  String get ssriReferenceDay30 =>
      'بعد شهر واحد من SSRIs: الاستقرار\n\nالمصدر: حداد بي إم (2001)، سلامة الأدوية - \"متلازمات التوقف عن تناول مضادات الاكتئاب\".\n\nمرحلة الاستقرار\nتصف هذه المراجعة بداية التوقف عن تناول الدواء بأنها سريعة، عادةً خلال أيام من التوقف عن تناول مضادات الاكتئاب أو تقليلها، وتشير إلى أن معظم التفاعلات تكون خفيفة وقصيرة الأجل، وتختفي دون علاج محدد. ويمثل شهر واحد الانتقال من تلك النافذة الحادة إلى الاستقرار؛ بالنسبة لمعظم الأشخاص الذين أكملوا التخفيض التدريجي، تم الآن حل أعراض التوقف الحادة إلى حد كبير.\n\nالمشهد العاطفي في شهر واحد\nالتغيرات العاطفية في شهر واحد متغيرة ومن المهم مراقبتها:\n• يشعر بعض الأشخاص \"بالاستواء\" عاطفيًا في البداية عندما يتكيف الدماغ - وهذا يتحسن عادةً\n• ويختبر آخرون حيوية عاطفية لم يشعروا بها منذ سنوات\n• تختلف مستويات القلق بشكل كبير حسب الحالة الفردية والحالة الأساسية\n\nقيمة الدعم غير الدوائي\nتظهر الأبحاث باستمرار أن العلاج بالكلام مثل العلاج السلوكي المعرفي (CBT) وغيره من العلاجات النفسية القائمة على الأدلة فعال للغاية في الحالات التي تعالجها مثبطات استرداد السيروتونين الانتقائية. تعد علامة الشهر الواحد وقتًا ممتازًا لضمان وجود هذا الدعم.';

  @override
  String get ssriReferenceDay90 =>
      'ثلاثة أشهر: منحنى أعراض الانسحاب يتغيّر\n\nالمصدر: Duffy وآخرون، \"Antidepressant medication to prevent depression relapse in primary care: the ANTLER RCT,\" Health Technology Assessment (2021)\n\nالقياس عند 12 أسبوعًا\nوزعت تجربة ANTLER عشوائيًا 478 مريضًا في الرعاية الأولية كانوا يتناولون مضادات الاكتئاب لمدة 9 أشهر على الأقل وشعروا بأنهم بحالة تسمح لهم بالتفكير في التوقف. كانت الأدوية citalopram أو sertraline أو fluoxetine أو mirtazapine. كان الفرق في أعراض الانسحاب بين مجموعة الإيقاف ومجموعة الاستمرار أكبر ما يكون عند 12 أسبوعًا ثم أصبح أصغر في المتابعات اللاحقة.\n\nلماذا يناسب هذا محطة SSRI\nثلاثة من الأدوية الأربعة المدروسة — citalopram وsertraline وfluoxetine — هي من مثبطات استرداد السيروتونين الانتقائية. ويذكر ملخص الدراسة المبسط أن الزيادة في أعراض الانسحاب بعد الإيقاف تركزت غالبًا في أول 3–4 أشهر.\n\nثلاثة أشهر قوية\nاليوم 90 يقع مباشرة عند نقطة التحول المقاسة هذه. بعد هذه النقطة يضيق الفرق في أعراض الانسحاب، ما يجعل ثلاثة أشهر محطة تعافٍ ملموسة. إذا عاد الاكتئاب أو القلق بقوة فتواصل مبكرًا مع الطبيب الذي يصف لك العلاج.';

  @override
  String get ssriReferenceDay180 =>
      'بعد ستة أشهر من إيقاف مضادات الاكتئاب: 65٪ ظلوا بحالة جيدة\n\nالمصدر: Volkmann وزملاؤه (2026)، European Archives of Psychiatry and Clinical Neuroscience\n\nنتيجة ملموسة بعد ستة أشهر\nتابعت الدراسة أشخاصًا كان اضطراب الاكتئاب الشديد لديهم في حالة هدوء أثناء إيقاف مضادات الاكتئاب. من بين 83 مشاركًا لديهم بيانات متابعة لستة أشهر، ظل 54 — أي 65٪ — بحالة جيدة، بينما انتكس 29.\n\nلماذا تهم هذه المحطة\nهذه النتيجة المقاسة بعد ستة أشهر تجعلها محطة حقيقية للاستقرار طويل الأمد. كما قيّمت الدراسة أعراض الانسحاب بشكل منفصل عن الانتكاس، ما ساعد على التمييز بينهما.\n\nإذا عادت أعراض الاكتئاب بقوة، تواصل مع الطبيب الذي يصف لك الدواء مبكرًا.';

  @override
  String get ssriReferenceDay365 =>
      'عام واحد بعد مضادات الاكتئاب طويلة الأمد: ما الذي قاسه ANTLER\n\nالمصدر: Duffy وآخرون (2021)، Health Technology Assessment — تجربة ANTLER\n\nما الذي وجدته التجربة فعلاً\nوزعت ANTLER عشوائيًا 478 بالغًا في الرعاية الأولية بالمملكة المتحدة ممن كانوا بحالة جيدة بما يكفي للتفكير في إيقاف مضادات الاكتئاب طويلة الأمد. بحلول 52 أسبوعًا، حدث انتكاس لدى 56% من مجموعة الإيقاف مقابل 39% من مجموعة الاستمرار. كان معدل الخطر مع الزمن للانتكاس أعلى بنحو الضعف (HR 2.06)، أما نسب الانتكاس المرصودة خلال عام فكانت 56% مقابل 39% وليست ضعفًا.\n\nالصورة الكاملة\nلم يكن الإيقاف طريقًا مسدودًا: 44% لم ينتكسوا خلال التجربة التي استمرت 52 أسبوعًا. لكن النتائج المتوسطة مالت لصالح العلاج الاستمراري؛ فقد عانت مجموعة الإيقاف من أعراض انسحاب أكثر ومن سنوات حياة معدلة حسب الجودة أقل خلال 12 شهرًا. وعاد 39% ممن وُزعوا على مجموعة الإيقاف إلى مضاد الاكتئاب الأصلي.\n\nمحطتك بعد عام\nإذا وصلت إلى عام كامل من دون الدواء وما زلت بخير، فهذا إنجاز كبير. لا تقول ANTLER إن على الجميع الاستمرار في الدواء أو أن على الجميع إيقافه؛ بل توضح لماذا يستحق خطر الانتكاس وقرارات العلاج متابعة فردية. العودة إلى الدواء عند الحاجة قرار سريري وليست فشلاً.';

  @override
  String get steroidsReferenceDay1 =>
      'إيقاف المنشطات الابتنائية: الأيام الأولى\n\nالمصدر: \"الأعراض الشائعة المرتبطة باستخدام ووقف المنشطات الأندروجينية الابتنائية لدى الرجال،\" أفضل الممارسات والأبحاث السريرية للغدد الصماء والتمثيل الغذائي (2022)\n\nالمرحلة الحادة\nتصف هذه المراجعة انسحاب AAS بأنه يتكشف على مرحلتين. الأول، مدفوعًا بتنشيط الجهاز العصبي الودي بدلاً من مستويات الهرمون، ويظهر خلال يوم أو يومين من التوقف ويمكن أن يشمل:\n• الصداع\n• الهزات\n• الخفقان\n• الغثيان\n\nلماذا تظهر الأعراض\nتعمل الستيرويدات الابتنائية أيضًا على قمع إنتاج هرمون التستوستيرون في الجسم، حيث يكتشف الدماغ المنشطات ويوقف الإشارات الهرمونية التي تحركه عادةً. يستمر هذا القمع بعد التوقف، مما يؤدي إلى المرحلة الثانية الأطول أمدًا من الانسحاب الموصوفة في المعالم اللاحقة.\n\nملاحظة السلامة\nيمكن أن يظهر الاكتئاب أثناء انسحاب الستيرويد ويصبح خطيرًا. اطلب الرعاية الطبية والمساعدة العاجلة لأي أفكار تتعلق بإيذاء النفس. غالبًا ما يقوم الأطباء بتوجيه عملية التعافي؛ يستخدم البعض الأدوية لدعمها.';

  @override
  String get steroidsReferenceDay14 =>
      'أسبوعين من التوقف عن المنشطات\n\nالمصدر: \"الأعراض الشائعة المرتبطة باستخدام ووقف المنشطات الأندروجينية الابتنائية لدى الرجال،\" أفضل الممارسات والأبحاث السريرية للغدد الصماء والتمثيل الغذائي (2022)\n\nتبدأ المرحلة المزمنة\nوبعد مرور أسبوعين، عادةً ما تنتهي الأعراض الودية القصيرة التي ظهرت في الأيام الأولى، وتكون المرحلة الثانية من المراجعة — مدفوعة بنقص هرمون التستوستيرون المستمر — أكثر وضوحًا:\n• التعب وتدني الحالة المزاجية\n• آلام العضلات (ألم عضلي)\n• انخفاض الرغبة الجنسية\n• الأرق والرغبة الشديدة\n\nلا يزال في مستوى منخفض\nيستغرق إنتاج هرمون التستوستيرون الطبيعي وقتًا أطول بكثير من أسبوعين لإعادة ضبطه، لذا فإن هذه المرحلة متوقعة وليست علامة على وجود خطأ ما.\n\nفخ معروف\nيعود بعض الرجال إلى استخدام هذه العادة خصيصًا للهروب من هذه الفجوة، وهي دورة تعيد ضبط ساعة التعافي بدلاً من إنهائها. يساعد الدعم المقدم من الطبيب أو المستشار في سد هذه المرحلة بدلاً من علاجها بمزيد من المنشطات.';

  @override
  String get steroidsReferenceDay30 =>
      'شهر واحد من التوقف عن المنشطات\n\nالمصدر: \"التعافي الجسدي والنفسي والكيميائي الحيوي من قصور الغدد التناسلية الناجم عن الستيرويدات البنائية: مراجعة لتحديد النطاق،\" في PubMed\n\nيبدأ التعافي\nبعد التوقف، تبدأ الإشارات الهرمونية التي تخبر الخصيتين بإنتاج هرمون التستوستيرون في العودة للعمل مرة أخرى. تضع الأبحاث جزءًا كبيرًا من هذا التعافي في نطاق ثلاثة إلى ستة أشهر، لذلك بعد شهر واحد تكون العملية جارية بالفعل.\n\nماذا تتوقع\nعادةً ما يستمر انخفاض الحالة المزاجية والرغبة الجنسية والطاقة بينما تعود الهرمونات إلى الارتفاع. يعتمد التعافي على العمر ومدى شدة الاستخدام وطول فترة استخدامه.';

  @override
  String get steroidsReferenceDay90 =>
      'ثلاثة أشهر من المنشطات الابتنائية\n\nالمصدر: \"التعافي الجسدي والنفسي والكيميائي الحيوي من قصور الغدد التناسلية الناجم عن الستيرويدات البنائية: مراجعة لتحديد النطاق،\" في PubMed\n\nالوقت المناسب لفحص الدم\nبحلول ثلاثة أشهر، يكون لدى النظام الهرموني الوقت الكافي لإظهار التعافي ذي المغزى. هذه نقطة مفيدة أن تطلب من طبيبك العام فحص هرمون التستوستيرون والهرمونات التي تتحكم فيه.\n\nماذا تتوقع\nبالنسبة للعديد من الرجال في عمر الثلاثة أشهر، ترتفع المستويات ولكنها لا تعود إلى طبيعتها بالكامل. غالبًا ما يتحسن المزاج والرغبة الجنسية قبل أن يصل هرمون التستوستيرون إلى المستوى المطلوب. يتعافى حجم الخصية وإنتاج الحيوانات المنوية بشكل أبطأ ويمكن أن يستمرا في التحسن خلال العام التالي. من غير المرجح أن يتراجع نمو أنسجة الثدي (التثدي)، حيث حدث، دون علاج محدد.';

  @override
  String get steroidsReferenceDay180 =>
      'ستة أشهر من المنشطات الابتنائية\n\nالمصدر: \"التعافي الجسدي والنفسي والكيميائي الحيوي من قصور الغدد التناسلية الناجم عن الستيرويدات البنائية: مراجعة لتحديد النطاق،\" في PubMed\n\nحيث تشير الأدلة\nتشير المراجعة إلى أن الهرمونين LH وFSH — الهرمونات التي تخبر الخصيتين بإنتاج هرمون التستوستيرون — يتعافيان عادة في غضون ثلاثة إلى ستة أشهر تقريبًا. وبحلول ستة أشهر، يكون التستوستيرون نفسه على طول مسار التعافي أيضًا.\n\nإذا لم تكن هناك بعد\nإذا استمرت أعراض انخفاض هرمون التستوستيرون لمدة ستة أشهر، فيمكن لأخصائي الغدد الصماء التحقق مما يحدث ومناقشة العلاج بدلاً من تركك للانتظار.';

  @override
  String get steroidsReferenceDay365 =>
      'عام واحد دون الستيرويدات البنائية\n\nالمصدر: \"Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review,\" Endocrine Connections (2023)\n\nعام من الحرية\nيختلف التعافي بعد استخدام الستيرويدات البنائية كثيرًا. تشير المراجعة إلى تعافٍ شبه كامل للتستوستيرون على مدى أشهر، وتعافي الغونادوتروبينات خلال نحو ثلاثة إلى ستة أشهر، بينما قد يستمر تعافي حجم الخصيتين وإنتاج الحيوانات المنوية من أشهر إلى سنوات. أما التعافي النفسي فأقل قابلية للتنبؤ.\n\nعام كامل يستحق الاحتفال\nعام كامل بلا منشطات إنجاز ضخم، وليس موعدًا عالميًا لوصول الهرمونات إلى المستوى الطبيعي. إذا استمرت أعراض انخفاض التستوستيرون، يمكن للتقييم المتخصص أن يوضح أين وصل التعافي.';

  @override
  String get steroidsReferenceDay730 =>
      'عامان دون الستيرويدات البنائية\n\nالمصدر: \"Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review,\" Endocrine Connections (2023)\n\nعامان من القوة\nعامان بلا منشطات فترة طويلة من دون إعادة التعرض. يختلف التعافي بحسب عوامل منها العمر ومدى استخدام الأندروجينات سابقًا؛ ولا توجد نقطة موحدة عند عامين يجب أن تكون فيها هرمونات الجميع طبيعية.\n\nالمسار الطويل\nتشير المراجعة إلى تعافي التستوستيرون على مدى أشهر والغونادوتروبينات خلال نحو ثلاثة إلى ستة أشهر، بينما قد يستمر تعافي حجم الخصيتين وإنتاج الحيوانات المنوية من أشهر إلى سنوات. استمرار أعراض انخفاض التستوستيرون يستحق تقييمًا متخصصًا — لا دورة ستيرويدات أخرى.';

  @override
  String get tcaReferenceDay3 =>
      'إيقاف مضادات الاكتئاب ثلاثية الحلقات: الأيام الأولى — الارتداد الكوليني\n\nالمصدر: Dilsaver, Feinberg & Greden (1983)، American Journal of Psychiatry — \'Antidepressant withdrawal symptoms treated with anticholinergic agents\' (تقرير حالات، 3 مرضى)\n\nلماذا قد يختلف إيقاف مضادات الاكتئاب ثلاثية الحلقات\nللعديد من هذه الأدوية تأثيرات مضادة للكولين إلى جانب تأثيرها في السيروتونين والنورأدرينالين. في ثلاث حالات منشورة، استجابت أعراض الانسحاب بعد الإيقاف المفاجئ أو الخفض السريع لعلاج مضاد للكولين، ما دفع المؤلفين إلى اقتراح فرط النشاط الكوليني المركزي كإحدى الآليات.\n\nأعراض أُبلغ عنها مع انسحاب مضادات الاكتئاب ثلاثية الحلقات\n• الغثيان والقيء والإسهال وألم البطن وفقدان الشهية\n• الأرق أو اضطرابات النوم الأخرى\n• القلق والهياج وسرعة الاستثارة\n• الصداع وأعراض جسدية أخرى\n\nالتوقيت يختلف\nقد تبدأ أعراض الانسحاب مبكرًا، خاصة بعد الإيقاف المفاجئ أو الخفض السريع. تدعم سلسلة الحالات الثلاث الارتداد الكوليني كآلية. ولم تُصمم لتحديد جدول يومي ثابت أو مقارنة أدوية TCA حسب شدة الارتداد.';

  @override
  String get tcaReferenceDay7 =>
      'بعد أسبوع من إيقاف مضادات الاكتئاب ثلاثية الحلقات: اجتزت المرحلة الأولى\n\nماذا يعني أسبوع واحد\nتذكر إرشادات NHS أن انسحاب مضادات الاكتئاب يبدأ عادة خلال بضعة أيام ويستمر بضعة أسابيع. لدى بعض الأشخاص قد يكون الانسحاب شديدًا أو تستمر الأعراض أشهرًا أو أكثر.\n\nأعراض قد تظل موجودة\n• الصداع وآلام العضلات\n• الغثيان والتعرق\n• تسارع القلب أو خفقانه أو عدم انتظام ضرباته\n• الدوخة أو عدم الثبات\n• مشاكل النوم والأحلام الغريبة والتعب\n• التململ وسرعة الاستثارة والقلق وانخفاض المزاج أو صعوبة التفكير\n\nسبعة أيام تقدم حقيقي\nأسبوع كامل من دون TCA يستحق الاحتفال. تصف إرشادات NHS الانسحاب على مدى أيام إلى أسابيع، وأحيانًا أطول، لذلك قد تهدأ أعراض معدل القلب والهضم والنوم وغيرها من الوظائف اللاإرادية وفق جداول زمنية مختلفة.';

  @override
  String get tcaReferenceDay14 =>
      'أسبوعان بعد مضادات الاكتئاب ثلاثية الحلقات: الانسحاب الحاد غالبًا يبدأ بالانحسار\n\nالنافذة الحادة المعتادة\nتذكر مراجعة سريرية لمتلازمة إيقاف مضادات الاكتئاب أن الأعراض المعتادة — مثل أعراض شبيهة بالإنفلونزا والأرق والغثيان واضطراب التوازن والأعراض الحسية وفرط الاستثارة — تستمر عادةً من أسبوع إلى أسبوعين.\n\nماذا يعني اليوم 14\nعند أسبوعين يصل كثير من الناس إلى نهاية نافذة الانسحاب الحاد الكلاسيكية، وغالبًا ما تكون أعراض الموجة الأولى قد بدأت تخف بشكل واضح.\n\nأربعة عشر يومًا دون TCA\nهذا يجعل اليوم 14 علامة تعافٍ حقيقية: موجة الانسحاب الحادة غالبًا ما تكون في طريقها للانحسار، وقد تجاوزت الجزء الأصعب من البداية.';

  @override
  String get tcaReferenceDay30 =>
      'بعد شهر واحد من إيقاف مضادات الاكتئاب ثلاثية الحلقات: الانسحاب الحاد هدأ غالبًا\n\nالفترة الحادة المعتادة\nيذكر وارنر وزملاؤه أن أعراض التوقف عن مضادات الاكتئاب تكون خفيفة عادةً وتستمر من أسبوع إلى أسبوعين. وتشمل المراجعة مضادات الاكتئاب ثلاثية الحلقات صراحةً؛ وقد تكون مشكلات التوازن والحركة من السمات المميزة بعد إيقافها.\n\nماذا يعني اليوم 30\nبعد شهر واحد، يكون معظم الناس قد تجاوزوا هذه المرحلة الحادة المعتادة. عادةً ما تكون الأعراض الشبيهة بالإنفلونزا والغثيان واضطراب التوازن والأرق والاضطرابات الحسية وفرط الاستثارة قد هدأت أو زالت.\n\nثلاثون يومًا قوية\nشهر كامل دون مضادات الاكتئاب ثلاثية الحلقات علامة تعافٍ ملموسة: نافذة الانسحاب الحاد المعتادة أصبحت خلفك غالبًا.';

  @override
  String get tcaReferenceDay90 =>
      'بعد ثلاثة أشهر من إيقاف مضادات الاكتئاب ثلاثية الحلقات: الانسحاب الحاد أصبح خلفك غالبًا\n\nالفترة الحادة المعتادة\nيذكر وارنر وزملاؤه أن أعراض التوقف عن مضادات الاكتئاب تكون خفيفة عادةً وتستمر من أسبوع إلى أسبوعين. وتشمل المراجعة مضادات الاكتئاب ثلاثية الحلقات صراحةً؛ وقد تكون مشكلات التوازن والحركة من السمات المميزة بعد إيقافها.\n\nماذا يعني اليوم 90\nعند 90 يومًا، تكون قد تجاوزت الحد الأعلى لهذه الفترة الحادة المعتادة بأكثر من عشرة أسابيع. إذا ظهرت لديك أعراض الموجة الأولى المعتادة مثل الأعراض الشبيهة بالإنفلونزا والغثيان واضطراب التوازن والأرق والاضطرابات الحسية وفرط الاستثارة، فهي تكون قد هدأت أو زالت عادةً منذ مدة.\n\nتسعون يومًا قوية\nثلاثة أشهر دون مضادات الاكتئاب ثلاثية الحلقات علامة تعافٍ ملموسة: الانسحاب الحاد أصبح خلفك غالبًا بوضوح. إذا عادت أعراض اكتئاب مهمة، فتواصل مع طبيبك مبكرًا.';

  @override
  String get tcaReferenceDay180 =>
      'ستة أشهر بعد إيقاف مضادات الاكتئاب: الغالبية بلا انتكاسة\n\nنقطة الستة أشهر للانتكاس\nجمع تحليل تلوي نُشر عام 2024 بيانات 35 تجربة عشوائية لإيقاف مضادات الاكتئاب لدى أشخاص عولجوا من الاكتئاب الشديد. بلغ معدل الانتكاس المجمع بعد الإيقاف 34.81% عند ستة أشهر — أي أن نحو 65% ظلوا بلا انتكاسة عند هذه النقطة.\n\nنتيجة حقيقية طويلة المدى\nوجد التحليل نفسه معدل انتكاس قدره 45.12% عند 12 شهرًا. لذلك تمثل ستة أشهر نقطة مهمة للاستقرار: أغلب المشاركين في التجارب المجمعة لم تحدث لديهم انتكاسة حتى ذلك الوقت.\n\nاحمِ التقدم\nإذا بدأت أعراض الاكتئاب في العودة، تواصل مبكرًا مع طبيبك أو مقدم الرعاية. الوصول إلى ستة أشهر فترة استقرار كبيرة تستحق الحماية.';

  @override
  String get tcaReferenceDay365 =>
      'سنة بعد إيقاف مضادات الاكتئاب: الغالبية بلا انتكاسة\n\nمحطة الاثني عشر شهرًا\nجمع تحليل تلوي نُشر عام 2024 نتائج 35 تجربة عشوائية لإيقاف مضادات الاكتئاب لدى أشخاص عولجوا من اضطراب الاكتئاب الشديد. بلغ معدل الانتكاس المجمع بعد الإيقاف 45.12% عند 12 شهرًا — أي أن نحو 55% ظلوا بلا انتكاسة عند محطة العام الواحد.\n\nعام كامل من الاستقرار\nوجد التحليل نفسه معدل انتكاس قدره 34.81% عند ستة أشهر. وعند 12 شهرًا، كان معظم المشاركين في التجارب المجمعة لا يزالون بلا انتكاسة. عام كامل بلا انتكاسة محطة كبرى من الاستقرار طويل الأمد.\n\nاحمِ تقدمك\nإذا بدأت أعراض الاكتئاب بالعودة، تواصل مع طبيبك مبكرًا. بلوغ عام كامل إنجاز كبير يستحق الحماية.';

  @override
  String get settingsLocaleArabic => 'العربية';

