  @override
  String vapingStreakTitle(int days) {
    return 'بلا فيب: اليوم $days';
  }

  @override
  String get vapingDay1Description =>
      'اليوم الأول بلا فيب. إذا كان الفيب الذي تستخدمه يحتوي على النيكوتين، فقد تكون الرغبة الشديدة أو التهيّج أو التوتر أو المزاج المنخفض أو سوء النوم أو صعوبة التركيز أعراض انسحاب النيكوتين — وليست سببًا لإطعامه نيكوتين جديدًا. في كل الأحوال، أنت تكسر حلقة الفيب بالفعل.';

  @override
  String get vapingDay3Description =>
      'ثلاثة أيام بلا فيب. في دراسة سريرية على مدخنين سابقين كانوا يستخدمون السجائر الإلكترونية يوميًا، بلغ متوسط أعراض الانسحاب ذروته في اليوم الأول أو الثاني، ثم انخفض خلال الأيام الأربعة التالية من الامتناع. أنت الآن بعد نافذة الذروة المبكرة التي ظهرت في تلك الدراسة؛ قد تظهر الرغبة مجددًا، لكنها ليست من يمسك بالمقود.';

  @override
  String get vapingDay7Description =>
      'سبعة أيام كاملة من دون استنشاق رذاذ الفيب. أسبوع بلا تعرّض جديد من الفيب للنيكوتين أو الجسيمات فائقة الدقة أو المعادن الثقيلة أو المركبات العضوية المتطايرة أو غيرها من المواد الضارة التي قد يحملها الرذاذ. سلسلة نظيفة — واصل.';

  @override
  String vapingLongStreakDescription(int days) {
    return '$days يومًا من دون أخذ نفخة أخرى من رذاذ الفيب. أي $days يومًا بلا تعرّض جديد من الفيب للمواد الضارة التي قد يحملها الرذاذ. وإذا كان الفيب يحتوي على النيكوتين، فهي أيضًا $days يومًا من دون تعزيز ذلك الاعتماد. سلسلة ضخمة — استمر.';
  }

  @override
  String get vapingMilestone730Title => 'عامان: قوة بلا فيب';

  @override
  String get vapingMilestone730Description =>
      'عامان كاملان بلا فيب. تقول CDC إن إدمان النيكوتين قد يجعل الإقلاع صعبًا وإن الآثار الصحية طويلة المدى للفيب ما زالت قيد الدراسة. الفوز المؤكد هنا هو الاستمرار نفسه: 730 يومًا من دون العودة إلى الفيب.';

  @override
  String get vapingMilestone1095Title => 'ثلاث سنوات: زخم ثابت';

  @override
  String get vapingMilestone1095Description =>
      'ثلاث سنوات بلا فيب. حافظت على تغيير صعب طوال 1,095 يومًا. لا تحدد CDC عتبة تعافٍ بيولوجية عند ثلاث سنوات، لذا احتفل بما يدعمه الدليل فعلًا: استمرار الحرية من الفيب.';

  @override
  String get vapingMilestone1460Title => 'أربع سنوات: أساس أقوى';

  @override
  String get vapingMilestone1460Description =>
      'أربع سنوات بلا فيب. هذا يعني 1,460 يومًا من دون تعزيز عادة الفيب. لا يحدد العلم جدولًا زمنيًا موحدًا للتعافي طويل المدى، لكن هذا التغيير المتين حقيقي ويستحق الاحتفال.';

  @override
  String get vapingMilestone1825Title => 'خمس سنوات: نصف عقد';

  @override
  String get vapingMilestone1825Description =>
      'خمس سنوات بلا فيب. نصف عقد من دون العودة إلى الفيب إنجاز كبير طويل المدى. لا تجعل أدلة CDC السنة الخامسة نقطة نهاية طبية؛ الإنجاز هو التغيير المستمر الذي بنيته.';

  @override
  String get vapingLongTermReference =>
      'الفيب والإقلاع والدليل طويل المدى\n\nالمصدر: CDC — Vaping and Quitting؛ CDC — Health Effects of Vaping\n\nتقول CDC إن مستخدمي الفيب قد يصبحون معتمدين على النيكوتين، وإن الإقلاع قد يسبب أعراض انسحاب النيكوتين، وإن أفضل طرق المساعدة على الإقلاع عن الفيب ما زالت قيد الدراسة. كما تؤكد أن الآثار الصحية طويلة المدى للسجائر الإلكترونية ما زالت غير مكتملة المعرفة.\n\nلا تحدد هذه المصادر عتبات تعافٍ بيولوجية عند سنتين أو ثلاث أو أربع أو خمس سنوات بعد الإقلاع عن الفيب. لذلك يتعامل Quitter مع هذه التواريخ كذكريات سنوية لتقدم مستمر بلا فيب، لا كنقاط نهاية طبية.';

  @override
  String get vapingWithdrawalReference =>
      'الامتناع عن السجائر الإلكترونية وأعراض الانسحاب\n\nالمصدر: Hughes وزملاؤه، Nicotine & Tobacco Research (2020)\n\nلدى 109 مدخنين سابقين كانوا يستخدمون السجائر الإلكترونية يوميًا، أدت ستة أيام من الامتناع المؤكد بيولوجيًا إلى زيادة أعراض انسحاب النيكوتين والرغبة. اتبعت الأعراض نمط الصعود والهبوط المعتاد للانسحاب، مع زيادة واضحة خلال أول يومين. تؤكد الدراسة أن انسحاب السجائر الإلكترونية حقيقي، لكنها لا تحدد جدول تعافٍ يوميًا موحدًا للجميع.';

  @override
  String get vapingHealthReference =>
      'ما الذي يعرّضك له الفيب\n\nالمصدر: CDC — Health Effects of Vaping\n\nتقول CDC إن معظم السجائر الإلكترونية تحتوي على نيكوتين مسبب للإدمان. وقد يحتوي الرذاذ على النيكوتين ومواد كيميائية مسرطنة ومعادن ثقيلة مثل النيكل والقصدير والرصاص وجسيمات دقيقة تصل عميقًا إلى الرئتين ومركبات عضوية متطايرة وبعض مواد النكهة الضارة. قد يسبب انسحاب النيكوتين التهيّج والقلق أو التوتر والمزاج المنخفض ومشكلات النوم والتركيز والجوع والرغبة، وتخف هذه الأعراض مع الوقت. ما زالت الآثار طويلة المدى للفيب قيد الدراسة، لذلك يحتفل Quitter بالامتناع الحقيقي بدل استعارة جداول السجائر الخاصة بأول أكسيد الكربون والقطران والسرطان أو مخاطر القلب.';

  @override
  String get adderallMilestone730Title => 'عامان: تغيير راسخ';

  @override
  String get adderallMilestone730Description =>
      'عامان من دون إساءة استخدام Adderall يعنيان تغييرًا مستمرًا، لا مجرد سلسلة قصيرة. لقد بنيت عادات وخيارات يمكنها أن تواصل دفعك إلى الأمام.';

  @override
  String get adderallReferenceDay730 =>
      'عامان من دون إساءة استخدام Adderall: تقدّم راسخ\n\nالمصدر: SAMHSA، Treatment of Stimulant Use Disorders\n\nيشمل دليل SAMHSA المنشطات من نوع الأمفيتامين، بما في ذلك إساءة استخدام المنشطات الموصوفة طبيًا، ويدعم الرعاية المبنية على الدليل للتعافي. ولا يحدد «إعادة ضبط» بيولوجية عند مرور عامين.\n\nومع ذلك، يظل العامان إنجازًا كبيرًا. لقد حافظت على التغيير مدة طويلة؛ احتفل بالاستقرار الذي بنيته وواصل ما أثبت فائدته.';

  @override
  String get adderallMilestone1095Title => 'ثلاث سنوات: أساس قوي';

  @override
  String get adderallMilestone1095Description =>
      'ثلاث سنوات هي تقدّم طويل الأمد صنعته يومًا بعد يوم. واصل حماية الحياة والعادات والدعم الذي جعل ذلك ممكنًا.';

  @override
  String get adderallReferenceDay1095 =>
      'ثلاث سنوات من دون إساءة استخدام Adderall: تعافٍ يزداد زخمًا\n\nالمصدر: SAMHSA، Treatment of Stimulant Use Disorders\n\nتدعم SAMHSA العلاج المبني على الدليل والتعافي طويل الأمد من اضطرابات استخدام المنشطات، بما فيها المشكلات المتعلقة بالمنشطات الموصوفة طبيًا. ولا يدّعي الدليل أن تغيرًا محددًا في الدماغ يكتمل بعد ثلاث سنوات.\n\nثلاث سنوات تعكس تغييرًا راسخًا استمر في الأيام العادية والصعبة معًا. حافظ على العادات والعلاقات والدعم الذي أوصلك إلى هنا.';

  @override
  String get adderallMilestone1460Title => 'أربع سنوات: جذور عميقة';

  @override
  String get adderallMilestone1460Description =>
      'أربع سنوات تُظهر ثباتًا رائعًا. يحتفي هذا الإنجاز باستمرار ابتعادك عن إساءة الاستخدام وبالاستقرار الذي بنيته حول ذلك.';

  @override
  String get adderallReferenceDay1460 =>
      'أربع سنوات من دون إساءة استخدام Adderall: تغيير طويل الأمد في الحياة\n\nالمصدر: SAMHSA، Treatment of Stimulant Use Disorders\n\nيركز دليل SAMHSA على العلاجات وأشكال الدعم التي تساعد الناس على تحقيق تعافٍ طويل الأمد. ولا يحدد خط نهاية طبيًا عند أربع سنوات، لذلك يحتفي هذا الإنجاز بالتقدم المستمر بدل وعد صحي مختلق.\n\nأربع سنوات تُظهر ثباتًا على مدى طويل حقًا. احمِ الهياكل والأشخاص الذين يساعدون على بقاء تقدمك ثابتًا.';

  @override
  String get adderallMilestone1825Title => 'خمس سنوات: فوز كبير';

  @override
  String get adderallMilestone1825Description =>
      'خمس سنوات تستحق الاحتفال. لقد حافظت على اتجاه مختلف طوال 1,825 يومًا وبنيت سنوات من الخبرة التي تثبت أن التغيير يمكن أن يدوم.';

  @override
  String get adderallReferenceDay1825 =>
      'خمس سنوات من دون إساءة استخدام Adderall: نصف عقد من التقدم\n\nالمصدر: SAMHSA، Treatment of Stimulant Use Disorders\n\nتعد SAMHSA التعافي طويل الأمد هدفًا مهمًا في رعاية اضطرابات استخدام المنشطات. ولا يعد دليلها بحدث بيولوجي خاص عند خمس سنوات، ولا يحتاج هذا الإنجاز إلى مثل هذا الوعد كي يكون مهمًا.\n\nخمس سنوات تعني 1,825 يومًا من الحفاظ على اتجاه مختلف. إنها خبرة معيشة كبيرة تدل على أن تغييرك يمكن أن يستمر. احتفل بها، ثم واصل ما جعلها ممكنة.';

  @override
  String get alcoholMilestone730Title => 'عامان: تقدّم مستدام';

  @override
  String get alcoholMilestone730Description =>
      'عامان بلا كحول يقعان ضمن فترة السنة إلى خمس سنوات التي تستخدمها NIAAA كمدة مستدامة في أبحاث التعافي. إنه إنجاز كبير يستحق الحماية.';

  @override
  String get alcoholReferenceDay730 =>
      'عامان بلا كحول: تقدّم مستدام\n\nالمصدر: NIAAA، Recovery Research Definitions\n\nتستخدم NIAAA مدة من سنة إلى خمس سنوات كفئة «مستدامة» لهدوء اضطراب استخدام الكحول والتوقف عن الشرب الثقيل عند الحفاظ عليهما مع الوقت. الامتناع الكامل يتجاوز حد الشرب، لكنه وحده لا يثبت كل معايير الهدوء السريري.\n\nعامان يعنيان 730 يومًا من الحفاظ على التغيير. احتفل بهذا الثبات واستمر في حماية العادات والعلاقات والدعم الذي يساعده على الاستمرار.';

  @override
  String get alcoholMilestone1095Title => 'ثلاثة أعوام: أساس أقوى';

  @override
