  @override
  String get alcoholReferenceDay1095 =>
      'ثلاثة أعوام بلا كحول: أساس أقوى\n\nالمصدر: NIAAA، Recovery Research Definitions\n\nتستخدم NIAAA من سنة إلى خمس سنوات كفئة مدة مستدامة لهدوء اضطراب استخدام الكحول والتوقف عن الشرب الثقيل. ولا تدّعي حدوث «إعادة ضبط» بيولوجية خاصة في السنة الثالثة.\n\nثلاثة أعوام هي 1,095 يومًا من ترسيخ نمط مختلف. هذا الثبات مهم بحد ذاته، والدعم الذي أوصلك إلى هنا يستحق أن تحافظ عليه.';

  @override
  String get alcoholMilestone1460Title => 'أربعة أعوام: تغيير راسخ';

  @override
  String get alcoholMilestone1460Description =>
      'أربعة أعوام بلا كحول تُظهر تغييرًا استمر زمنًا طويلًا حقًا. الإنجاز هو الاستمرارية نفسها، لا موعد طبي مختلق.';

  @override
  String get alcoholReferenceDay1460 =>
      'أربعة أعوام بلا كحول: تغيير راسخ\n\nالمصدر: NIAAA، Recovery Research Definitions\n\nتبقى أربعة أعوام داخل نافذة NIAAA المستدامة من سنة إلى خمس سنوات في الأبحاث. يتناول الإطار استمرار الهدوء والتوقف عن الشرب الثقيل، ولا يقول إن جسم أو دماغ كل شخص يصل إلى خط النهاية نفسه في اليوم نفسه.\n\nأربعة أعوام بلا كحول تعني تغييرًا صمد خلال الأيام العادية والضغط والفصول والمحطات المختلفة. الاستمرارية نفسها إنجاز.';

  @override
  String get alcoholMilestone1825Title => 'خمسة أعوام: محطة كبيرة';

  @override
  String get alcoholMilestone1825Description =>
      'خمسة أعوام بلا كحول تصل إلى الحد الأعلى لنافذة NIAAA المستدامة من سنة إلى خمس سنوات. ولا تبدأ فئة «المستقر» إلا بعد أكثر من خمس سنوات.';

  @override
  String get alcoholReferenceDay1825 =>
      'خمسة أعوام بلا كحول: محطة كبيرة\n\nالمصدر: NIAAA، Recovery Research Definitions\n\nتسمي NIAAA المدة من سنة إلى خمس سنوات «مستدامة»، وتخصص «مستقرة» لما يزيد على خمس سنوات. لذلك تبقى خمس سنوات بالضبط عند الطرف الأخير من النافذة المستدامة. ويشمل الإطار أيضًا هدوء أعراض AUD، لذا لا ينبغي اعتبار الامتناع وحده تشخيصًا سريريًا.\n\nخمسة أعوام بلا كحول هي 1,825 يومًا من التغيير المستمر. نصف عقد يستحق تقديرًا حقيقيًا من دون اختراع خط نهاية طبي لا تدعمه الأدلة.';

