  @override
  String get ghbReferenceDay730 =>
      'عامان من دون GHB: تقدّم راسخ\n\nالمصدر: SAMHSA، التعافي ودعم التعافي\n\nتصف SAMHSA التعافي بأنه مسار فردي ومتواصل من التغيير، ولا تحدد نقطة بيولوجية خاصة بـ GHB عند أي من هذه الذكريات السنوية.\n\nعامان يساويان 730 يومًا من الحفاظ على اتجاه مختلف. الاستمرار نفسه يستحق التقدير، وكذلك الأشخاص والعادات والدعم التي تجعله قابلًا للاستمرار.';

