  @override
  String get ghbReferenceDay1095 =>
      'ثلاثة أعوام من دون GHB: أساس أقوى\n\nالمصدر: SAMHSA، التعافي ودعم التعافي\n\nتصف SAMHSA التعافي بأنه مسار فردي ومتواصل من التغيير، ولا تحدد نقطة بيولوجية خاصة بـ GHB عند أي من هذه الذكريات السنوية.\n\nثلاثة أعوام تساوي 1,095 يومًا من التغيير المحافظ عليه. هذا سجل كبير من الثبات وحماية ما يساعد التعافي على الاستمرار.';

