  @override
  String get ghbReferenceDay1460 =>
      'أربعة أعوام من دون GHB: تغيير مستمر\n\nالمصدر: SAMHSA، التعافي ودعم التعافي\n\nتصف SAMHSA التعافي بأنه مسار فردي ومتواصل من التغيير، ولا تحدد نقطة بيولوجية خاصة بـ GHB عند أي من هذه الذكريات السنوية.\n\nأربعة أعوام تساوي 1,460 يومًا من حمل التغيير عبر تفاصيل الحياة اليومية. المتانة نفسها إنجاز يستحق الاحتفاء.';

