  @override
  String get ghbReferenceDay1825 =>
      'خمسة أعوام من دون GHB: محطة كبيرة\n\nالمصدر: SAMHSA، التعافي ودعم التعافي\n\nتصف SAMHSA التعافي بأنه مسار فردي ومتواصل من التغيير، ولا تحدد نقطة بيولوجية خاصة بـ GHB عند أي من هذه الذكريات السنوية.\n\nخمسة أعوام تساوي 1,825 يومًا من التغيير المحافظ عليه. نصف عقد من الالتزام المتكرر يستحق تقديرًا حقيقيًا.';

  @override
  String get inhalantsMilestone1095Title => 'ثلاث سنوات: تعافٍ راسخ';

  @override
  String get inhalantsMilestone1095Description =>
      'ثلاث سنوات بعيدًا عن المستنشقات تمثل تقدمًا مستمرًا. تدعم الأبحاث التعافي طويل الأمد من دون تحديد عتبة بيولوجية خاصة عند السنة الثالثة.';

  @override
  String get inhalantsMilestone1460Title => 'أربع سنوات: تقدم ثابت';

  @override
  String get inhalantsMilestone1460Description =>
      'أربع سنوات فترة مهمة أخرى من التعافي. تدعم الأدلة استمرار الامتناع، ولا تجعل السنة الرابعة خط نهاية عام لتعافي الدماغ.';

  @override
  String get inhalantsMilestone1825Title => 'خمس سنوات: أساس قوي';

  @override
  String get inhalantsMilestone1825Description =>
      'خمس سنوات تمثل تقدمًا دائمًا يستحق الاحتفاء. قد يدعم الامتناع طويل الأمد التعافي، مع بقاء النتائج مرتبطة بنوع الإصابة السابقة وشدتها.';

  @override
  String get inhalantsReferenceDay1095 =>
      'ثلاث سنوات دون مستنشقات\n\nالمصدر: Cairney وآخرون، «دراسة مستقبلية للتغيرات العصبية المعرفية بعد 15 عامًا من إساءة استخدام المستنشقات المزمنة»، Addiction (2013)، PubMed\n\nبعد العامين\nوجدت الدراسة تعافيًا ملحوظًا بعد عامين من الامتناع لدى المشاركين من دون اعتلال دماغي بالرصاص، وتابعت المجموعة نفسها حتى 15 عامًا. لم تحدد عتبة بيولوجية خاصة عند السنة الثالثة.\n\nثلاث سنوات من التقدم\nتمثل ثلاث سنوات امتناعًا مستمرًا. قد يستمر التعافي على المدى الطويل، بينما تتأثر النتائج بالتعرض والإصابات السابقة؛ وقد يترك اعتلال الدماغ بالرصاص عجزًا مستمرًا.';

  @override
  String get inhalantsReferenceDay1460 =>
      'أربع سنوات دون مستنشقات\n\nالمصدر: Cairney وآخرون، «دراسة مستقبلية للتغيرات العصبية المعرفية بعد 15 عامًا من إساءة استخدام المستنشقات المزمنة»، Addiction (2013)، PubMed\n\nالتعافي طويل الأمد\nفي المجموعة التي لم تعانِ اعتلالًا دماغيًا بالرصاص، عادت معظم النتائج إلى الطبيعي بعد عامين وأعيد تقييم المجموعة عند 15 عامًا. لا تنسب الورقة حدث تعافٍ مستقلًا إلى السنة الرابعة.\n\nأربع سنوات من المسافة\nتضيف أربع سنوات عامًا كاملًا آخر من الامتناع المستمر وتقوي أساس التعافي. تختلف النتائج، خاصة عند وجود إصابة عصبية شديدة سابقة.';

  @override
  String get inhalantsReferenceDay1825 =>
      'خمس سنوات دون مستنشقات\n\nالمصدر: Cairney وآخرون، «دراسة مستقبلية للتغيرات العصبية المعرفية بعد 15 عامًا من إساءة استخدام المستنشقات المزمنة»، Addiction (2013)، PubMed\n\nمحطة طويلة الأمد\nتدعم الدراسة احتمال حدوث تعافٍ عصبي ومعرفي ملحوظ مع الامتناع الطويل عند غياب اعتلال الدماغ بالرصاص. كانت نقاط التقييم عند عامين و15 عامًا، لذلك لا تعتبر خمس سنوات خط نهاية بيولوجيًا عامًا.\n\nخمس سنوات مبنية\nخمس سنوات تقدم دائم وفترة كبيرة من الحياة بعيدًا عن المستنشقات. تدعم الأدلة التعافي طويل الأمد مع الإقرار بأن الإصابات الشديدة المرتبطة بالرصاص قد تبقى مستمرة.';

  @override
  String get maoiMilestone730Title => 'عامان: مسار ثابت';

  @override
  String get maoiMilestone730Description =>
      'يمثل مرور عامين بعد إيقاف مثبطات أكسيداز أحادي الأمين فترة طويلة من التغيير المستمر. تصف أبحاث إيقاف ترانيلسيبرومين مخاطر الانقطاع الحادة، لكنها لا تحدد نقطة تعافٍ بيولوجية خاصة عند عامين. تحتفي هذه المرحلة بالاستمرارية والدعم والعادات التي أوصلتك إلى هنا.';

  @override
  String get maoiMilestone1095Title => 'ثلاثة أعوام: تقدم راسخ';

  @override
  String get maoiMilestone1095Description =>
      'تمثل ثلاثة أعوام سنة كاملة أخرى من الحفاظ على الاتجاه الذي اخترته. لا تحدد أبحاث إيقاف مثبطات أكسيداز أحادي الأمين عتبة تعافٍ فسيولوجية عند ثلاث سنوات؛ والإنجاز هو نمط القرارات والدعم الذي أصبح جزءاً ثابتاً من الحياة اليومية.';

  @override
  String get maoiMilestone1460Title => 'أربعة أعوام: ثبات مستمر';

  @override
  String get maoiMilestone1460Description =>
      'أربعة أعوام تعني استمرار الالتزام عبر تغير الظروف والضغوط والعادات. لا تحدد الأدبيات الطبية خط نهاية عاماً عند أربع سنوات؛ تحتفي هذه المرحلة بالاستمرارية التي حافظت عليها.';

  @override
  String get maoiMilestone1825Title => 'خمسة أعوام: تغيير راسخ';

  @override
  String get maoiMilestone1825Description =>
      'خمسة أعوام مرحلة طويلة المدى مهمة. تركز الأدلة حول إيقاف مثبطات أكسيداز أحادي الأمين على مخاطر الانقطاع والإيقاف الآمن، لا على تاريخ شفاء عند خمس سنوات. الإنجاز هو حجم الوقت والعادات والدعم الذي حافظت عليه.';

  @override
  String get maoiReferenceDay730 =>
      'عامان بعد مثبطات أكسيداز أحادي الأمين\n\nالمصدر: غار وزملاؤه (2013)، مراجعة منهجية لأعراض انسحاب وانقطاع ترانيلسيبرومين.\n\nتوثق المراجعة متلازمات قد تكون شديدة بعد الإيقاف المفاجئ، لكنها لا تحدد عتبة تعافٍ بيولوجية خاصة عند عامين. لذلك تمثل هذه الذكرى تغيراً مستمراً ودعماً وعادات راسخة، لا خط نهاية طبياً.';

  @override
  String get maoiReferenceDay1095 =>
      'ثلاثة أعوام بعد مثبطات أكسيداز أحادي الأمين\n\nالمصدر: غار وزملاؤه (2013)، مراجعة منهجية لأعراض انسحاب وانقطاع ترانيلسيبرومين.\n\nتصف المراجعة الانسحاب والانقطاع الحادين، لكنها لا تحدد نقطة تعافٍ فسيولوجية عند ثلاث سنوات. تحتفي ثلاثة أعوام بسنة كاملة أخرى من الحفاظ على الاتجاه المختار وبالدعم الذي ساعد على استمراره.';

  @override
  String get maoiReferenceDay1460 =>
      'أربعة أعوام بعد مثبطات أكسيداز أحادي الأمين\n\nالمصدر: غار وزملاؤه (2013)، مراجعة منهجية لأعراض انسحاب وانقطاع ترانيلسيبرومين.\n\nلا تحدد الأدلة المنشورة نقطة نهاية بيولوجية عامة عند أربع سنوات. تعكس هذه المرحلة استمرار الالتزام عبر تغير الظروف والضغوط والعادات من دون اختراع موعد سريري.';

  @override
  String get maoiReferenceDay1825 =>
      'خمسة أعوام بعد مثبطات أكسيداز أحادي الأمين\n\nالمصدر: غار وزملاؤه (2013)، مراجعة منهجية لأعراض انسحاب وانقطاع ترانيلسيبرومين.\n\nتتناول الأدبيات مخاطر الانقطاع والإيقاف الآمن؛ ولا تعرف خمس سنوات كتاريخ شفاء أو خط نهاية بيولوجي عام. تبقى خمس سنوات مرحلة كبيرة بسبب الوقت والعادات والدعم المستمر طوال 1825 يوماً.';

  @override
  String get marijuanaMilestone730Title => 'عامان: أساس قوي';

  @override
  String get marijuanaMilestone730Description =>
      'عامان من دون القنب فترة كبيرة من التغيير المستمر. توصي SAMHSA برعاية تناسب الشخص ومرحلة حياته بدل اعتماد جدول واحد للتعافي. يحتفي هذا الإنجاز بالعادات والدعم اللذين أوصلاك إلى هنا.';

  @override
  String get marijuanaReferenceDay730 =>
      'عامان من دون القنب\n\nالمصدر: SAMHSA (2026), Addressing Cannabis Use Disorder in Primary Care Settings—A Lifespan Approach.\n\nتوضح SAMHSA أن اضطراب استخدام القنب يختلف باختلاف الشخص ومرحلة الحياة، وتوصي برعاية مخصصة ومبنية على الأدلة. ولا تحدد عتبة بيولوجية موحدة للتعافي عند عامين.\n\nلذلك يمثل العامان تغييرا مستمرا وعادات ودعما، لا خط نهاية طبيا.';

  @override
  String get marijuanaMilestone1095Title => 'ثلاثة أعوام: زخم مستمر';

  @override
  String get marijuanaMilestone1095Description =>
      'ثلاثة أعوام تعكس زخما ثابتا. اضطراب استخدام القنب لا يسير بالطريقة نفسها لدى الجميع، ولا تحدد SAMHSA نقطة بيولوجية خاصة عند ثلاثة أعوام. الإنجاز هو عام كامل إضافي من الخيارات والدعم المستمرين.';

  @override
  String get marijuanaReferenceDay1095 =>
      'ثلاثة أعوام من دون القنب\n\nالمصدر: SAMHSA (2026), Addressing Cannabis Use Disorder in Primary Care Settings—A Lifespan Approach.\n\nتؤكد الإرشادات أن المخاطر والأعراض واحتياجات العلاج المرتبطة بالقنب تختلف بين الأشخاص ومراحل الحياة. ولا تحدد نقطة بيولوجية موحدة عند ثلاثة أعوام.\n\nتحتفي ثلاثة أعوام بخيارات ثابتة وبالدعم الذي ساعدها على الاستمرار.';

  @override
  String get marijuanaMilestone1460Title => 'أربعة أعوام: تغيير راسخ';

  @override
  String get marijuanaMilestone1460Description =>
      'أربعة أعوام تعكس تغييرا راسخا. تركز الإرشادات المبنية على الأدلة على احتياجات الفرد لا على حد موحد للتعافي بعد أربعة أعوام. احتفل بالثبات الذي حافظت عليه رغم تغير الروتين والضغوط ومراحل الحياة.';

  @override
  String get marijuanaReferenceDay1460 =>
      'أربعة أعوام من دون القنب\n\nالمصدر: SAMHSA (2026), Addressing Cannabis Use Disorder in Primary Care Settings—A Lifespan Approach.\n\nتوصي SAMHSA برعاية فردية ومبنية على الأدلة لأن اضطراب استخدام القنب لا يتبع مسارا واحدا لدى الجميع. ولا تضع الإرشادات حدا موحدا للتعافي عند أربعة أعوام.\n\nتعكس أربعة أعوام الاستمرار رغم تغير الروتين والضغوط ومراحل الحياة. هذا الثبات هو الإنجاز.';

  @override
  String get marijuanaMilestone1825Title => 'خمسة أعوام: تقدم مستمر';

  @override
  String get marijuanaMilestone1825Description =>
      'خمسة أعوام إنجاز كبير على المدى الطويل. لا تحدد SAMHSA تاريخ شفاء عند خمسة أعوام لاضطراب استخدام القنب. الإنجاز هو نصف عقد من الاتجاه الواضح والعادات التي مارستها والدعم الذي حافظت عليه.';

  @override
  String get marijuanaReferenceDay1825 =>
      'خمسة أعوام من دون القنب\n\nالمصدر: SAMHSA (2026), Addressing Cannabis Use Disorder in Primary Care Settings—A Lifespan Approach.\n\nتدعم إرشادات SAMHSA رعاية مخصصة عبر مراحل الحياة، ولا تحدد تاريخ شفاء عند خمسة أعوام أو نهاية بيولوجية موحدة لاضطراب استخدام القنب.\n\nخمسة أعوام إنجاز كبير طويل الأمد: نصف عقد من الاتجاه والعادات والدعم المستمر.';

  @override
  String get mdmaMilestone730Title => 'عامان: أساس راسخ';

  @override
  String get mdmaMilestone730Description =>
      'عامان من دون MDMA يمثلان تغييرًا مستمرًا. أفضل مراجعة متاحة لا تعتبر العامين نقطة تعافٍ بيولوجية ثابتة، لذلك يحتفي هذا الإنجاز بالثبات والعادات والدعم بدل اختراع خط نهاية طبي.';

  @override
  String get mdmaReferenceDay730 =>
      'عامان من دون MDMA\n\nالمصدر: Ung وآخرون (2026)، مراجعة منهجية وتحليل تلوي للنتائج العصبية المعرفية طويلة الأمد بعد الامتناع المستمر عن MDMA.\n\nشملت المراجعة دراسات بمدة امتناع لا تقل عن ستة أشهر، وقيّمت جودة الأدلة بأنها منخفضة، ولم تجد أن طول مدة الامتناع يتنبأ بصورة موثوقة بتحسن أكبر في التعلم أو الذاكرة. ولا تعتبر العامين نقطة تعافٍ بيولوجية عامة.\n\nيبقى العامان علامة مهمة على تغيير مستمر بُني من قرارات متكررة، لا من موعد طبي نهائي.';

  @override
  String get mdmaMilestone1095Title => 'ثلاثة أعوام: زخم ثابت';

  @override
  String get mdmaMilestone1095Description =>
      'ثلاثة أعوام تضيف عامًا كاملًا آخر من الزخم المستمر. لا تحدد الأبحاث نهاية عصبية معرفية عامة عند ثلاث سنوات؛ الإنجاز هو الحفاظ على الاتجاه في الحياة اليومية.';

  @override
  String get mdmaReferenceDay1095 =>
      'ثلاثة أعوام من دون MDMA\n\nالمصدر: Ung وآخرون (2026)، مراجعة منهجية وتحليل تلوي للامتناع المستمر عن MDMA.\n\nلا تحدد الدراسات المتاحة نقطة عند ثلاث سنوات تزول فيها الآثار المعرفية لدى الجميع. ولم تجد المراجعة علاقة موثوقة بين امتداد الامتناع وزيادة تعافي التعلم أو الذاكرة، كما قيّمت جودة الأدلة بأنها منخفضة.\n\nثلاثة أعوام تحتفي بزخم ثابت واستمرارية حقيقية من دون ادعاء موعد بيولوجي لا تدعمه الأدلة.';

  @override
  String get mdmaMilestone1460Title => 'أربعة أعوام: جذور راسخة';

  @override
  String get mdmaMilestone1460Description =>
      'أربعة أعوام تعكس تغييرًا أصبح راسخًا. ما تزال الأدلة بعد الامتناع الطويل عن MDMA محدودة، لذلك يستحق الاستمرار نفسه الاحتفاء بدل تحديد موعد تعافٍ غير مثبت.';

  @override
  String get mdmaReferenceDay1460 =>
      'أربعة أعوام من دون MDMA\n\nالمصدر: Ung وآخرون (2026)، مراجعة منهجية وتحليل تلوي للامتناع المستمر عن MDMA.\n\nما تزال الأبحاث محدودة ولا تعتبر أربعة أعوام حدًا عامًا للتعافي. وقد تستمر بعض الفروق المقاسة، مع تنبيه المراجعة إلى انخفاض جودة الأدلة الأساسية.\n\nأربعة أعوام تمثل تغييرًا راسخًا عبر تغير الروتين والضغوط ومراحل الحياة. هذا الاستمرار هو الإنجاز.';

