  @override
  String get mdmaReferenceDay1825 =>
      'خمسة أعوام من دون MDMA\n\nالمصدر: Ung وآخرون (2026)، مراجعة منهجية وتحليل تلوي للامتناع المستمر عن MDMA.\n\nلا تدعم الأدلة الحالية اعتبار خمسة أعوام موعد شفاء أو نهاية عصبية معرفية عامة. وجدت المراجعة أدلة محدودة منخفضة الجودة، ولم تجد نمطًا موثوقًا لزيادة تعافي التعلم أو الذاكرة مع طول مدة الامتناع.\n\nتبقى خمسة أعوام إنجازًا كبيرًا طويل الأمد: نصف عقد من الاتجاه المستمر يستحق التقدير بذاته.';

