  @override
  String get nitrousOxideReferenceDay730 =>
      'عامان - التقدم مستمر\n\nالمصدر: Marsden وSharma وRotella ‏(2022)، مراجعة منهجية للاستخدام المزمن لأكسيد النيتروز.\n\nوجدت المراجعة أن المشكلات العصبية سمة شائعة للاستخدام المزمن، وأن تعويض فيتامين B12 هو العلاج الرئيسي، وأن التعافي الجزئي هو النتيجة الأكثر وروداً. ولم تحدد جدولاً زمنياً عاماً للتعافي يمتد لسنوات.\n\nعامان من دون أكسيد النيتروز يعنيان 730 يوماً من دون تعرّض جديد. تختلف النتائج العصبية، وغالباً ما يُبلَّغ عن تعافٍ جزئي بعد التوقف والعلاج، لذلك تحتفي هذه المحطة بالحماية المستمرة لا بموعد طبي ثابت.';

